#include <stdlib.h>
#include <string.h>

char** allocate_and_copy_string_array(char** input_array, size_t num_strings) {
    if (input_array == NULL || num_strings == 0) {
        return NULL;
    }

    char** new_array = malloc(num_strings * sizeof(char*));
    if (new_array == NULL) {
        return NULL;
    }

    for (size_t i = 0; i < num_strings; i++) {
        if (input_array[i] != NULL) {
            size_t length = strlen(input_array[i]) + 1;
            new_array[i] = malloc(length);
            if (new_array[i] == NULL) {
                // Free previously allocated strings in case of failure
                for (size_t j = 0; j < i; j++) {
                    free(new_array[j]);
                }
                free(new_array);
                return NULL;
            }
            strcpy(new_array[i], input_array[i]);
        } else {
            new_array[i] = NULL;
        }
    }

    return new_array;
}
