#include <stdint.h>
#include <time.h>

struct transaction {
    uint64_t id;
    double weighted_sum;
    uint32_t sent;
    time_t timestamp;
};

struct transaction_filter {
    time_t oldest;
    time_t latest;
    uint32_t max_sent;
    double max_weighted_sum;
    uint64_t max_weighted_sum_txid;
    uint32_t transaction_count;
};

void *filter_transactions(struct transaction_filter *filter, void *_ptr, void *value) {
    struct transaction *tx = (struct transaction *)value;
    time_t current_time = time(NULL);

    if ((filter->oldest == 0 || tx->timestamp >= filter->oldest) &&
        (filter->latest == 0 || tx->timestamp < filter->latest)) {

        if (tx->sent < filter->max_sent) {
            filter->transaction_count++;
            if (tx->weighted_sum > filter->max_weighted_sum) {
                filter->max_weighted_sum = tx->weighted_sum;
                filter->max_weighted_sum_txid = tx->id;
            }
        }
    }

    return (filter->transaction_count >= 100) ? (void *)1 : (void *)0; // Example limit for max items
}
