    FILE *file = fopen(filePath, "r");
    if (!file) {
        return -1; // Error opening file
    }

    ResourceBundle *resBundle = (ResourceBundle *)malloc(sizeof(ResourceBundle));
    if (!resBundle) {
        fclose(file);
        return -2; // Memory allocation error
    }

    resBundle->items = NULL;
    resBundle->count = 0;

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        resBundle->count++;
        resBundle->items = (char **)realloc(resBundle->items, resBundle->count * sizeof(char *));
        if (!resBundle->items) {
            free(resBundle);
            fclose(file);
            return -2; // Memory allocation error
        }
        resBundle->items[resBundle->count - 1] = strdup(line);
        if (!resBundle->items[resBundle->count - 1]) {
            free(resBundle->items);
            free(resBundle);
            fclose(file);
            return -2; // Memory allocation error
        }
    }

    fclose(file);
    *bundle = resBundle;
    return resBundle->count; // Return the number of items
}
