#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 1024

void printCommaSeparated(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    char *line = (char *)malloc(MAX_LINE_LENGTH);
    if (!line) {
        perror("Failed to allocate memory");
        fclose(file);
        return;
    }

    while (fgets(line, MAX_LINE_LENGTH, file)) {
        char *token;
        double lastField = 0.0, secondLastField = 0.0;
        int fieldCount = 0;

        // Print fields in comma-separated format
        token = strtok(line, " \n");
        while (token) {
            printf("%s", token);
            fieldCount++;

            // Store the last two fields for average calculation
            if (fieldCount > 1) {
                secondLastField = lastField;
            }
            lastField = atof(token);

            token = strtok(NULL, " \n");
            if (token) {
                printf(", ");
            }
        }

        // Calculate and print the average of the last two fields
        if (fieldCount > 1) {
            double average = (lastField + secondLastField) / 2.0;
            printf(", %.2f\n", average);
        } else {
            printf("\n");
        }
    }

    free(line);
    fclose(file);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return EXIT_FAILURE;
    }

    printCommaSeparated(argv[1]);
    return EXIT_SUCCESS;
}
