#include <stdlib.h>

typedef struct TreeNode {
    int offset;
    struct TreeNode *left;
    struct TreeNode *right;
} TreeNode;

TreeNode* insert_offset(TreeNode *root, int offset) {
    if (root == NULL) {
        TreeNode *newNode = (TreeNode *)malloc(sizeof(TreeNode));
        if (newNode == NULL) {
            return NULL; // Memory allocation failed
        }
        newNode->offset = offset;
        newNode->left = newNode->right = NULL;
        return newNode;
    }

    if (offset < root->offset) {
        root->left = insert_offset(root->left, offset);
    } else if (offset > root->offset) {
        root->right = insert_offset(root->right, offset);
    }
    // If the offset is already present, do nothing

    return root;
}
