#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <errno.h>

#define MAXDATASIZE 1024
#define RETRIES 5
#define TIMEOUT 5

void receive_file_via_udp(const char *filename, const char *mode, const char *server_ip, int server_port) {
    int sock;
    struct sockaddr_in server_addr;
    unsigned char buffer[MAXDATASIZE];
    FILE *fp;
    ssize_t bytes_received;
    int retries;

    // Create socket
    if ((sock = socket(PF_INET, SOCK_DGRAM, IPPROTO_UDP)) < 0) {
        perror("Socket creation failed");
        return;
    }

    // Set up server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(server_port);
    if (inet_pton(AF_INET, server_ip, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sock);
        return;
    }

    // Open file for writing
    fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("File cannot be opened for writing");
        close(sock);
        return;
    }

    // Receive data
    for (retries = 0; retries < RETRIES; retries++) {
        bytes_received = recvfrom(sock, buffer, MAXDATASIZE, 0, NULL, NULL);
        if (bytes_received < 0) {
            perror("Error receiving data");
            continue; // Retry receiving
        }

        // Write to file
        if (fwrite(buffer, 1, bytes_received, fp) != bytes_received) {
            perror("Error writing to file");
            fclose(fp);
            close(sock);
            return;
        }

        // Break on successful reception
        if (bytes_received < MAXDATASIZE) {
            break; // End of file
        }
    }

    if (retries == RETRIES) {
        fprintf(stderr, "Failed to receive file after %d retries\n", RETRIES);
    } else {
        printf("File received successfully: %s\n", filename);
    }

    fclose(fp);
    close(sock);
}
