#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 256

typedef struct {
    char **strings;
    int *counts;
    size_t size;
} ExtractedData;

static ExtractedData* processTextFile(const char *file_name, size_t *total_count) {
    FILE *file = fopen(file_name, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    ExtractedData *data = malloc(sizeof(ExtractedData));
    if (!data) {
        fclose(file);
        return NULL;
    }
    data->strings = NULL;
    data->counts = NULL;
    data->size = 0;

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        // Trim whitespace
        char *trimmed_line = line;
        while (*trimmed_line == ' ' || *trimmed_line == '\t') trimmed_line++;
        if (*trimmed_line == '\0' || *trimmed_line == '\n' || *trimmed_line == '#') {
            continue; // Ignore empty and comment lines
        }

        if (trimmed_line[0] == '\'') { // String
            data->strings = realloc(data->strings, (data->size + 1) * sizeof(char *));
            if (!data->strings) {
                free(data);
                fclose(file);
                return NULL;
            }
            data->strings[data->size] = strdup(trimmed_line + 1); // Skip the leading quote
            data->strings[data->size][strcspn(data->strings[data->size], "\n")] = '\0'; // Remove newline
            data->size++;
        } else if (trimmed_line[0] == '!') { // String count
            data->counts = realloc(data->counts, (data->size + 1) * sizeof(int));
            if (!data->counts) {
                free(data->strings);
                free(data);
                fclose(file);
                return NULL;
            }
            data->counts[data->size] = atoi(trimmed_line + 1); // Skip the leading exclamation mark
            data->size++;
        }
    }

    fclose(file);
    *total_count = data->size;
    return data;
}

// Example usage
int main() {
    size_t total_count;
    ExtractedData *data = processTextFile("example.txt", &total_count);
    if (data) {
        for (size_t i = 0; i < total_count; i++) {
            if (data->strings && data->strings[i]) {
                printf("String: %s\n", data->strings[i]);
                free(data->strings[i]);
            }
            if (data->counts) {
                printf("Count: %d\n", data->counts[i]);
            }
        }
        free(data->strings);
        free(data->counts);
        free(data);
    }
    return 0;
}
