#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <ctype.h>

#define LEX_EOF 0
#define LEX_ID 1
#define LEX_INT 2
#define LEX_FLOAT 3
#define LEX_STR 4
#define LEX_OPERATOR_START 128
#define LEX_OPERATOR_END 255

int getToken(const char *input) {
    int token = LEX_EOF;
    bool foundToken = false;
    const char *ptr = input;

    while (*ptr != '\0') {
        if (isspace(*ptr)) {
            ptr++;
            continue;
        }

        if (isalpha(*ptr)) {
            token = LEX_ID;
            foundToken = true;
            while (isalnum(*ptr) || *ptr == '_') ptr++;
        } else if (isdigit(*ptr)) {
            token = LEX_INT;
            foundToken = true;
            while (isdigit(*ptr)) ptr++;
            if (*ptr == '.') {
                token = LEX_FLOAT;
                ptr++;
                while (isdigit(*ptr)) ptr++;
            }
        } else {
            switch (*ptr) {
                case '+':
                case '-':
                case '*':
                case '/':
                    token = LEX_OPERATOR_START + (*ptr);
                    foundToken = true;
                    ptr++;
                    break;
                case '"':
                case '\'':
                    token = LEX_STR;
                    foundToken = true;
                    ptr++;
                    while (*ptr != '\0' && *ptr != *ptr[-1]) ptr++;
                    if (*ptr == *ptr[-1]) ptr++;
                    break;
                default:
                    token = LEX_EOF;
                    foundToken = false;
                    ptr++;
                    break;
            }
        }

        if (foundToken) {
            return token;
        }
    }
    return LEX_EOF;
}

int main() {
    const char *testInput = "int x = 10; if (x > 5) { return x; }";
    const char *ptr = testInput;
    int token;

    while ((token = getToken(ptr)) != LEX_EOF) {
        printf("Token: %d\n", token);
        while (*ptr != '\0' && !isspace(*ptr)) ptr++;
        while (isspace(*ptr)) ptr++;
    }

    return 0;
}
