void parse_ip_packet(const uint8_t *packet, int length) {
    int opt_len, opt_type;
    const uint8_t *p = packet;

    while (length > 0) {
        if (length < 2) {
            printf("Packet too short to read option\n");
            return;
        }

        opt_type = p[0];
        opt_len = p[1];

        if (opt_len < 2 || opt_len > length) {
            printf("Invalid option length %u for option type %u\n", opt_len, opt_type);
            return;
        }

        printf("Option Type: %u, Length: %u\n", opt_type, opt_len);

        switch (opt_type) {
            case 0: // No-operation option
                printf("  No-operation option\n");
                break;
            case 1: // End of options
                printf("  End of options\n");
                return; // End of options reached
            default:
                printf("  Unknown option\n");
                break;
        }

        p += opt_len;
        length -= opt_len;
    }
}
