#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

#define MAX_HOSTS 100
#define HOSTNAME_SIZE 256
#define PORT_SIZE 16

struct downstream_s {
    char hostname[HOSTNAME_SIZE];
    char data_port[PORT_SIZE];
    char health_port[PORT_SIZE];
};

struct downstream_list {
    int num_hosts;
    struct downstream_s hosts[MAX_HOSTS];
};

struct downstream_list parse_downstream_hosts(const char *input) {
    struct downstream_list result;
    result.num_hosts = 0;

    char *hosts = strdup(input);
    if (hosts == NULL) {
        perror("strdup failed");
        return result;
    }

    char *host = strtok(hosts, ",");
    while (host != NULL && result.num_hosts < MAX_HOSTS) {
        char *data_port = strchr(host, ':');
        if (data_port == NULL) {
            fprintf(stderr, "No data port for host: %s\n", host);
            free(hosts);
            return result;
        }
        *data_port++ = 0;

        char *health_port = strchr(data_port, ':');
        if (health_port == NULL) {
            fprintf(stderr, "No health port for host: %s\n", host);
            free(hosts);
            return result;
        }
        *health_port++ = 0;

        strncpy(result.hosts[result.num_hosts].hostname, host, HOSTNAME_SIZE);
        strncpy(result.hosts[result.num_hosts].data_port, data_port, PORT_SIZE);
        strncpy(result.hosts[result.num_hosts].health_port, health_port, PORT_SIZE);

        result.num_hosts++;
        host = strtok(NULL, ",");
    }

    free(hosts);
    return result;
}
