typedef struct {
    double *data;
    size_t size;
} DataDistribution;

DataDistribution *calculate_average_and_allocate(double *dataset, size_t dataset_size, size_t items_per_block, size_t reserved_size) {
    if (dataset_size == 0 || items_per_block == 0) {
        return NULL; // Handle empty dataset or block size
    }

    double sum = 0.0;
    for (size_t i = 0; i < dataset_size; i++) {
        sum += dataset[i];
    }
    double average = sum / dataset_size;

    size_t distribution_size = (dataset_size / items_per_block) + reserved_size;
    DataDistribution *distribution = (DataDistribution *)malloc(sizeof(DataDistribution));
    if (distribution == NULL) {
        return NULL; // Handle memory allocation failure
