    distribution->data = (double *)malloc(distribution_size * sizeof(double));
    if (distribution->data == NULL) {
        free(distribution);
        return NULL; // Handle memory allocation failure
    }

    distribution->size = distribution_size;

    // Optionally fill the distribution array with the average value
    for (size_t i = 0; i < distribution_size; i++) {
        distribution->data[i] = average;
    }

    return distribution;
}
