#include <string.h>

char* allocate_and_copy_string(const char* input) {
    if (input == NULL) {
        return NULL;
    }

    size_t length = strlen(input);
    char* new_string = (char*)calloc(length + 1, sizeof(char));
    if (new_string == NULL) {
        return NULL;
    }

    strcpy(new_string, input);
    return new_string;
