#include <stdio.h>
#include <string.h>
#include <stdarg.h>

#define MAX_BUFFER_SIZE 1024

void log_message(char *buffer, size_t buffer_size, const char *format, ...) {
    if (buffer == NULL || buffer_size == 0) {
        return; // No buffer to log to
    }

    va_list args;
    va_start(args, format);

    // Create a temporary buffer to format the message
    char temp_buffer[MAX_BUFFER_SIZE];
    int msg_len = vsnprintf(temp_buffer, sizeof(temp_buffer), format, args);

    if (msg_len < 0) {
        // Formatting error
        va_end(args);
        return;
    }

    // Trim the message if it exceeds the buffer size
    if ((size_t)msg_len >= buffer_size) {
        msg_len = buffer_size - 1; // Leave space for null terminator
    }

    // Copy the message to the provided buffer and null-terminate it
    strncpy(buffer, temp_buffer, msg_len);
    buffer[msg_len] = '\0';

    va_end(args);
}
