    // If staying in the title room, retain the ping setting
    if (connection->stayInTitleRoom) {
        connection->pingRoom[0] = connection->pingRoom[0]; // Assuming TitleRoom is index 0
    }

    // Update connection state
    connection->stayInTitleRoom = PEERFalse;

    return PEERTrue;
}
