#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char hostname[256];
    int port;
} server_t;

server_t* parse_server_list(const char *str, int *count) {
    server_t *servers = NULL;
    char *token, *str_copy, *saveptr;
    int srv_count = 0;
    int capacity = 2;

    servers = (server_t *)malloc(capacity * sizeof(server_t));
    if (servers == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    str_copy = strdup(str);
    if (str_copy == NULL) {
        free(servers);
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    token = strtok_r(str_copy, ", ", &saveptr);
    while (token != NULL) {
        if (srv_count >= capacity) {
            capacity *= 2;
            servers = (server_t *)realloc(servers, capacity * sizeof(server_t));
            if (servers == NULL) {
                free(str_copy);
                fprintf(stderr, "Memory reallocation failed\n");
                return NULL;
            }
        }

        sscanf(token, "%255[^:]:%d", servers[srv_count].hostname, &servers[srv_count].port);
        srv_count++;
        token = strtok_r(NULL, ", ", &saveptr);
    }

    free(str_copy);
    *count = srv_count;
    return servers;
}
