#include <stdlib.h>
#include <string.h>
#include <stdarg.h>

char* replace_substrings(const char* input, const char* format, ...) {
    if (!input || !format) {
        return NULL;
    }

    va_list args;
    va_start(args, format);

    // Create a buffer for the formatted string
    char formatted[256];
    vsnprintf(formatted, sizeof(formatted), format, args);
    va_end(args);

    // Count occurrences of the formatted string in the input
    int count = 0;
    const char* temp = input;
    while ((temp = strstr(temp, formatted)) != NULL) {
        count++;
        temp += strlen(formatted);
    }

    // Allocate memory for the new string
    size_t new_length = strlen(input) + (strlen(formatted) * count);
    char* result = (char*)malloc(new_length + 1);
    if (!result) {
        return NULL;
    }

    // Replace substrings
    char* pos = result;
    const char* start = input;
    while ((temp = strstr(start, formatted)) != NULL) {
        size_t len = temp - start;
        strncpy(pos, start, len);
        pos += len;
        start = temp + strlen(formatted);
    }
    strcpy(pos, start); // Copy the remaining part

    return result;
}
