#include <stdlib.h>
#include <string.h>
#include <poll.h>
#include <stdbool.h>

struct pollfd *pollset = NULL;
size_t current_size = 0;
size_t max_size = 0;

bool allocate_pollset(size_t initial_size) {
    if (initial_size == 0) {
        return false;
    }

    max_size = initial_size;
    pollset = (struct pollfd *)malloc(max_size * sizeof(struct pollfd));
    if (pollset) {
        memset(pollset, 0, max_size * sizeof(struct pollfd));
        current_size = 0;
        return true;
    }
    return false;
}

bool add_poll_desc(int fd) {
    if (current_size >= max_size) {
        size_t new_size = max_size > 0 ? max_size * 2 : 1;
        struct pollfd *new_pollset = (struct pollfd *)realloc(pollset, new_size * sizeof(struct pollfd));
        if (new_pollset) {
            pollset = new_pollset;
            memset(pollset + max_size, 0, (new_size - max_size) * sizeof(struct pollfd));
            max_size = new_size;
        } else {
            free(pollset);
            pollset = NULL;
            max_size = 0;
            return false;
