    pollset[current_size].fd = fd;
    pollset[current_size].events = POLLIN;
    pollset[current_size].revents = 0;
    current_size++;
    return true;
}

void free_pollset() {
    free(pollset);
    pollset = NULL;
    current_size = 0;
    max_size = 0;
}
