if (psi->pollres_len > ev_state_len)
psi->pollres_len = ev_state_len;
psi->pollres = erts_alloc(ERTS_ALC_T_POLLSET,
sizeof(ErtsPollResFd) * psi->pollres_len);
}

ERTS_MSACC_POP_STATE();
}

