    for (size_t i = 0; i < options->size; i++) {
        newDict->entries[i] = options->entries[i];
    }

    // Add new entries
    newDict->entries[options->size].key = strdup("filename");
    newDict->entries[options->size].value = strdup(fileInfo->filename);

    newDict->entries[options->size + 1].key = strdup("mode");
    newDict->entries[options->size + 1].value = strdup(fileInfo->mode);

    newDict->entries[options->size + 2].key = strdup("encoding");
    newDict->entries[options->size + 2].value = strdup(fileInfo->encoding);

