void print_client_ip(int socket_fd, struct sockaddr_in *client_addr) {
    socklen_t addr_len = sizeof(*client_addr);
    int client_socket = accept(socket_fd, (struct sockaddr*)client_addr, &addr_len);

    if (client_socket < 0) {
        perror("accept failed");
        return;
    }

    char ip_str[INET_ADDRSTRLEN];
    if (inet_ntop(AF_INET, &client_addr->sin_addr, ip_str, sizeof(ip_str)) != NULL) {
        printf("Client IP Address: %s\n", ip_str);
    } else {
        perror("inet_ntop failed");
    }

    close(client_socket);
}
