#include <string.h>

static int is_rotation(const char *s1, const char *s2) {
    int len1 = strlen(s1);
    int len2 = strlen(s2);

    if (len1 != len2) {
        return 0; // Not a rotation if lengths are different
    }

    // Concatenate s1 with itself
    char *temp = (char *)malloc(2 * len1 + 1);
    if (!temp) {
        return 0; // Memory allocation failed
    }
    strcpy(temp, s1);
    strcat(temp, s1);

    // Check if s2 is a substring of the concatenated string
    int result = strstr(temp, s2) != NULL;

    free(temp);
    return result; // 1 if s2 is a rotation of s1, 0 otherwise
}
