#include <string.h>
#include <stdint.h>

char* format_memory_data(void* address, size_t size, const char* data_type, const char* data_format) {
    if (size == 0) {
        return strdup("Error: Size is zero.");
    }

    // Check if the requested size exceeds the available memory
    if (address == NULL) {
        return strdup("Error: Invalid memory address.");
    }

    // Allocate a buffer for the output string
    char* result = (char*)malloc(size * 8 + 1); // 8 chars for binary representation + null terminator
    if (result == NULL) {
        return strdup("Error: Memory allocation failed.");
    }

    if (strcmp(data_format, "binary") == 0) {
        for (size_t i = 0; i < size; i++) {
            uint8_t byte = *((uint8_t*)address + i);
            for (int j = 7; j >= 0; j--) {
                result[i * 8 + (7 - j)] = (byte & (1 << j)) ? '1' : '0';
            }
        }
        result[size * 8] = '\0'; // Null-terminate the string
    } else if (strcmp(data_format, "text") == 0) {
        if (strcmp(data_type, "int") == 0) {
            for (size_t i = 0; i < size / sizeof(int); i++) {
                int value = *((int*)address + i);
                char buffer[12]; // Enough to hold an int as a string
                snprintf(buffer, sizeof(buffer), "%d", value);
                strcat(result, buffer);
                if (i < (size / sizeof(int)) - 1) {
                    strcat(result, " "); // Add space between numbers
                }
            }
        } else if (strcmp(data_type, "float") == 0) {
            for (size_t i = 0; i < size / sizeof(float); i++) {
                float value = *((float*)address + i);
                char buffer[32]; // Enough to hold a float as a string
                snprintf(buffer, sizeof(buffer), "%.2f", value);
                strcat(result, buffer);
                if (i < (size / sizeof(float)) - 1) {
                    strcat(result, " "); // Add space between numbers
                }
            }
        } else {
            free(result);
            return strdup("Error: Unsupported data type.");
        }
    } else {
        free(result);
        return strdup("Error: Unsupported data format.");
    }

    return result;
}
