int convertJpegToPdf(const char *inputFile, const char *outputFile) {
    char buffer[512];
    const char *psFile = "/tmp/junk_image.ps";
    PIX *pixs;
    l_int32 ignore;

    // Read the JPEG file
    if ((pixs = pixRead(inputFile)) == NULL) {
        return 1; // Return 1 if the image cannot be read
    }

    // Convert JPEG to PostScript
    if (pixWrite("/tmp/junk_image.jpg", pixs, IFF_JFIF_JPEG) == 0) {
        convertJpegToPS("/tmp/junk_image.jpg", psFile, "w", 0, 0, 300, 1.0, 1, TRUE);
    }

    // Convert PostScript to PDF
    sprintf(buffer, "ps2pdf %s %s", psFile, outputFile);
    ignore = system(buffer);  // Ignore any errors from the third-party tool

    // Clean up
    pixDestroy(&pixs);
    return 0; // Return 0 if successful
}
