#define BUFFER_SIZE 256

typedef struct {
    char *buffer;
    size_t size;
    size_t position;
} LineBuffer;

void init_line_buffer(LineBuffer *line_buffer) {
    line_buffer->buffer = (char *)malloc(BUFFER_SIZE);
    line_buffer->size = BUFFER_SIZE;
    line_buffer->position = 0;
}

void free_line_buffer(LineBuffer *line_buffer) {
    free(line_buffer->buffer);
    line_buffer->buffer = NULL;
    line_buffer->size = 0;
    line_buffer->position = 0;
}

int read_line(FILE *file, LineBuffer *line_buffer) {
    if (line_buffer->position > 0) {
        // If there's already data in the buffer, return it
        return 1;
