#include <gtk/gtk.h>

static void on_checkbox_toggled(GtkToggleButton *togglebutton, GtkComboBox *combo_box) {
    gtk_widget_set_sensitive(GTK_WIDGET(combo_box), !gtk_toggle_button_get_active(togglebutton));
}

static GtkWidget *create_speed_combo_box(void) {
    GtkWidget *hbox;
    GtkWidget *label;
    GtkWidget *combo_box;
    GtkWidget *entry;
    GtkWidget *checkbox;

    const char *speed_options[] = {"1200", "2400", "4800", "9600", "19200", "38400", "57600", "115200"};
    int num_options = sizeof(speed_options) / sizeof(speed_options[0]);

    hbox = gtk_hbox_new(FALSE, 5);
    gtk_container_set_border_width(GTK_CONTAINER(hbox), 5);

    label = gtk_label_new("Speed:");
    gtk_box_pack_start(GTK_BOX(hbox), label, FALSE, FALSE, 0);

    combo_box = gtk_combo_box_entry_new_text();
    for (int i = 0; i < num_options; i++) {
        gtk_combo_box_append_text(GTK_COMBO_BOX(combo_box), speed_options[i]);
    }
    entry = gtk_bin_get_child(GTK_BIN(combo_box));
    gtk_entry_set_text(GTK_ENTRY(entry), speed_options[0]);
    gtk_editable_set_editable(GTK_EDITABLE(entry), FALSE);
    gtk_box_pack_start(GTK_BOX(hbox), combo_box, FALSE, FALSE, 0);

    checkbox = gtk_check_button_new_with_label("Disable Speed Selection");
    gtk_box_pack_start(GTK_BOX(hbox), checkbox, FALSE, FALSE, 0);
    g_signal_connect(checkbox, "toggled", G_CALLBACK(on_checkbox_toggled), combo_box);

    return hbox;
}

int main(int argc, char *argv[]) {
    GtkWidget *window;
    GtkWidget *vbox;

    gtk_init(&argc, &argv);

    window = gtk_window_new(GTK_WINDOW_TOPLEVEL);
    gtk_window_set_title(GTK_WINDOW(window), "Speed Selector");
    gtk_window_set_default_size(GTK_WINDOW(window), 300, 100);
    g_signal_connect(window, "destroy", G_CALLBACK(gtk_main_quit), NULL);

    vbox = gtk_vbox_new(FALSE, 5);
    gtk_container_set_border_width(GTK_CONTAINER(vbox), 10);
    gtk_container_add(GTK_CONTAINER(window), vbox);

    GtkWidget *speed_combo_box = create_speed_combo_box();
    gtk_box_pack_start(GTK_BOX(vbox), speed_combo_box, FALSE, FALSE, 0);

    gtk_widget_show_all(window);
    gtk_main();

    return 0;
}
