#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define CARD_NUM_CARDS 52
#define CARD_SHUFFLE_POOL 64

typedef struct {
    int type; // Card type (e.g., suit)
    char name[30]; // Unique name of the card
} card_t;

typedef struct cardStack {
    card_t *data;
    struct cardStack *next;
} cardStack_t;

unsigned int SimpleHash(const char *str, unsigned int hashSize) {
    unsigned int hash = 0;
    while (*str) {
        hash = (hash << 5) + *str++;
    }
    return hash % hashSize;
}

cardStack_t* shuffleDeck(card_t *cards, size_t numCards) {
    cardStack_t *cardHT[CARD_SHUFFLE_POOL] = { 0 };
    card_t cardsFake[CARD_NUM_CARDS];
    memcpy(cardsFake, cards, sizeof(card_t) * numCards);

    srand(time(NULL)); // Seed for random number generation

    for (size_t i = numCards - 1; i > 0; i--) {
        size_t j = rand() % (i + 1);
        card_t temp = cardsFake[i];
        cardsFake[i] = cardsFake[j];
        cardsFake[j] = temp;
    }

    for (size_t i = 0; i < numCards; i++) {
        unsigned int hash = (SimpleHash(cardsFake[i].name, CARD_SHUFFLE_POOL) ^ rand()) & (CARD_SHUFFLE_POOL - 1);
        cardStack_t *current = cardHT[hash];

        if (current) {
            while (current->next) {
                current = current->next;
            }
            current->next = (cardStack_t *)malloc(sizeof(cardStack_t));
            current = current->next;
            current->data = &cardsFake[i];
            current->next = NULL;
        } else {
            cardHT[hash] = (cardStack_t *)malloc(sizeof(cardStack_t));
            cardHT[hash]->data = &cardsFake[i];
            cardHT[hash]->next = NULL;
        }
    }

    cardStack_t *head = NULL;
    for (size_t i = 0; i < CARD_SHUFFLE_POOL; i++) {
        if (cardHT[i]) {
            cardStack_t *current = cardHT[i];
            while (current) {
                cardStack_t *newNode = (cardStack_t *)malloc(sizeof(cardStack_t));
                newNode->data = current->data;
                newNode->next = head;
                head = newNode;
                current = current->next;
            }
        }
    }

    return head;
}
