#include <openssl/evp.h>
#include <openssl/sha.h>
#include <string.h>
#include <stdlib.h>

#define CRYPT_IV_SIZE 16
#define CRYPT_KEY_SIZE 32

EVP_CIPHER_CTX *crypt_init(const char *password) {
    if (!password || !*password) {
        return NULL;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        return NULL;
    }

    const EVP_CIPHER *cipher = EVP_aes_256_cbc();
    if (EVP_CIPHER_iv_length(cipher) != CRYPT_IV_SIZE) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    if (EVP_CIPHER_key_length(cipher) != CRYPT_KEY_SIZE) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    unsigned char key[CRYPT_KEY_SIZE];
    unsigned char iv[CRYPT_IV_SIZE];

    // Derive key using SHA-1
    EVP_BytesToKey(cipher, EVP_sha1(), NULL, (unsigned char*)password,
                   strlen(password), 1, key, iv);

    if (EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

void crypt_cleanup(EVP_CIPHER_CTX *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
    }
}
