#include <stdint.h>
#include <string.h>

#define MAX_DNS_SERVICES 10
#define MAX_DNS_NAME_LENGTH 256
#define DNS_TTL 240 // 4 minutes in seconds

uint8_t* GenerateDNSResponse(uint8_t* buffer, const char* services[], int num_services) {
    if (num_services <= 0) return buffer;

    uint16_t* header = (uint16_t*)buffer;
    *(header++) = htons(0x1234); // Transaction ID
    *(header++) = htons(0x8400); // Authoritative response
    *(header++) = 0;              // Questions
    *(header++) = htons(num_services); // Answers
    *(header++) = 0;              // Authority
    *(header++) = 0;              // Additional

    buffer = (uint8_t*)header;

    for (int i = 0; i < num_services; i++) {
        char service_name[MAX_DNS_NAME_LENGTH];
        int service_length = strlen(services[i]);

        memcpy(buffer, services[i], service_length);
        buffer += service_length;
        *(buffer++) = 0; // End of the service name

        *(buffer++) = 0x00; *(buffer++) = 0x0c; // PTR record
        *(buffer++) = 0x00; *(buffer++) = 0x01; // Class IN
        *(buffer++) = (DNS_TTL >> 24) & 0xFF; *(buffer++) = (DNS_TTL >> 16) & 0xFF; // TTL
        *(buffer++) = (DNS_TTL >> 8) & 0xFF; *(buffer++) = DNS_TTL & 0xFF; // TTL

        *(buffer++) = 0x00; *(buffer++) = service_length + 8; // Length of the service name + ".local"
        memcpy(buffer, services[i], service_length);
        buffer += service_length;
        memcpy(buffer, ".local", 7);
        buffer += 7;
        *(buffer++) = 0x00; // End of the name
    }

    return buffer;
}
