#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    const char *pcTaskName;
    unsigned portBASE_TYPE uxCurrentPriority;
    unsigned portBASE_TYPE usStackHighWaterMark;
    unsigned portBASE_TYPE xTaskNumber;
    enum { eReady, eBlocked, eSuspended, eDeleted } eCurrentState;
} xTaskStatusType;

void printTaskStatus(xTaskStatusType *pxTaskStatusArray, size_t uxArraySize, char *pcWriteBuffer) {
    char cStatus;
    *pcWriteBuffer = 0x00; // Ensure the buffer starts empty

    for (size_t x = 0; x < uxArraySize; x++) {
        switch (pxTaskStatusArray[x].eCurrentState) {
            case eReady:       cStatus = 'R'; break;
            case eBlocked:     cStatus = 'B'; break;
            case eSuspended:   cStatus = 'S'; break;
            case eDeleted:     cStatus = 'D'; break;
            default:          cStatus = 'U'; break; // Unknown state
        }

        sprintf(pcWriteBuffer + strlen(pcWriteBuffer), 
                "%s\t%c\t%u\t%u\t%u\r\n", 
                pxTaskStatusArray[x].pcTaskName, 
                cStatus, 
                (unsigned int)pxTaskStatusArray[x].uxCurrentPriority, 
                (unsigned int)pxTaskStatusArray[x].usStackHighWaterMark, 
                (unsigned int)pxTaskStatusArray[x].xTaskNumber);
    }
}
