#include <unistd.h>

int countFilesWithFormat(const char *path, const char *format) {
    struct dirent *entry;
    DIR *dp = opendir(path);
    int count = 0;

    if (dp == NULL) {
        fprintf(stderr, "opendir error: %s\n", path);
        return 0;
    }

    while ((entry = readdir(dp)) != NULL) {
        if (entry->d_type == DT_DIR) {
            // Skip the "." and ".." entries
            if (strcmp(entry->d_name, ".") != 0 && strcmp(entry->d_name, "..") != 0) {
                char newPath[1024];
                snprintf(newPath, sizeof(newPath), "%s/%s", path, entry->d_name);
                count += countFilesWithFormat(newPath, format);
            }
        } else {
            if (strstr(entry->d_name, format) != NULL) {
                count++;
            }
        }
    }

    closedir(dp);
    return count;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <directory> <format>\n", argv[0]);
        return EXIT_FAILURE;
