        return NULL;
    }

    // Generate a random number for the file name
    srand((unsigned int)time(NULL));
    int random_number = rand();

    // Create the file name
    char file_name[256];
    snprintf(file_name, sizeof(file_name), "%s_%d.txt", file_prefix, random_number);

    // Calculate the total length of the path
    size_t dir_len = strlen(dir_path);
    size_t file_len = strlen(file_name);
    size_t total_len = dir_len + file_len + 2; // +2 for '/' and '\0'

    // Check if the total length exceeds the size limit
    if (total_len > size) {
        return NULL;
    }

    // Allocate memory for the full path
    char *full_path = (char *)malloc(total_len);
    if (full_path == NULL) {
        return NULL;
    }

    // Construct the full path
    snprintf(full_path, total_len, "%s/%s", dir_path, file_name);

    return full_path;
}
