		memcpy(path, pathrec->name, pathrec->length);
		path[pathrec->length] = 0;
		strcat(path, "/");
		strcat(path, tail);
		strncpy(tail, path, PATH_MAX);
	}

	if (1 != numrec) {
		dir = vfs_subtree_lookup(root, tail);
	}

	return dir;
}
