int* socket_initialize(const char* protocol, const char* path, const char* name, int timeout) {
    int sfd = -1;
    struct sockaddr_in saddr;
    int opt = 1;

    if (strcmp(protocol, "TCP") == 0) {
        sfd = socket(PF_INET, SOCK_STREAM, IPPROTO_TCP);
    } else if (strcmp(protocol, "UDP") == 0) {
        sfd = socket(PF_INET, SOCK_DGRAM, IPPROTO_UDP);
    } else {
        fprintf(stderr, "Unsupported protocol: %s\n", protocol);
        return NULL;
    }

    if (sfd < 0) {
        perror("socket()");
        return NULL;
    }

    if (setsockopt(sfd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt()");
        close(sfd);
        return NULL;
    }

    memset(&saddr, 0, sizeof(saddr));
    saddr.sin_family = AF_INET;
    saddr.sin_addr.s_addr = inet_addr(path);
    saddr.sin_port = htons(atoi(name));

    if (bind(sfd, (struct sockaddr*)&saddr, sizeof(saddr)) < 0) {
        perror("bind()");
        close(sfd);
        return NULL;
    }

    if (timeout > 0) {
        struct timeval tv;
        tv.tv_sec = timeout;
        tv.tv_usec = 0;

        if (setsockopt(sfd, SOL_SOCKET, SO_SNDTIMEO, (const char*)&tv, sizeof(tv)) < 0) {
            perror("setsockopt() SO_SNDTIMEO");
            close(sfd);
            return NULL;
        }

        if (setsockopt(sfd, SOL_SOCKET, SO_RCVTIMEO, (const char*)&tv, sizeof(tv)) < 0) {
            perror("setsockopt() SO_RCVTIMEO");
            close(sfd);
            return NULL;
        }
    }

    return (int*)sfd;
}
