#include <string.h>
#include <pthread.h>

static int error_counter = 0;
static pthread_mutex_t error_mutex = PTHREAD_MUTEX_INITIALIZER;

void parse_http_response(const char *response) {
    char *line = strdup(response);
    char *status_line = strtok(line, "\r\n");
    int response_code = 0;

    if (status_line) {
        // Extract the response code from the status line
        char *p = status_line;
        while (*p && !isspace(*p)) p++; // Skip method
        while (isspace(*p)) p++; // Skip spaces
        response_code = strtol(p, NULL, 10);

        // Check if the response code is 2xx
        if (response_code < 200 || response_code >= 300) {
            pthread_mutex_lock(&error_mutex);
            error_counter++;
            printf("Warning: Received non-2xx response code: %d\n", response_code);
            pthread_mutex_unlock(&error_mutex);
        }
    }

    free(line);
}
