#include <string.h>

char* modify_string(char* input) {
    if (input == NULL) {
        return NULL;
    }

    size_t len = strlen(input);

    // Remove trailing newlines and carriage returns
    while (len > 0 && (input[len - 1] == '\n' || input[len - 1] == '\r')) {
        input[--len] = '\0';
    }

    // Append a newline character
    input[len] = '\n';
    input[len + 1] = '\0';

    return input;
}
