#include <stdlib.h>

#define BLOBFRAC 8
#define BIGSIZE 32

struct blob {
    int blobx;
    int bloby;
    int blobdx;
    int blobdy;
    int bloblife;
    int blobsize;
    struct blob *blobnext;
};

struct blob *freeblobs = NULL;
struct blob *activeblobs = NULL;

void addblob(void) {
    int dx, dy;
    struct blob *ablob;

    if (!freeblobs) return;
    dx = (rand() & 255) - 128;
    dy = (rand() % 200) + 340;
    ablob = freeblobs;
    freeblobs = freeblobs->blobnext;
    ablob->bloblife = (rand() & 511) + 256;
    ablob->blobdx = dx;
    ablob->blobdy = dy;
    ablob->blobx = (256 + (rand() & 127)) << BLOBFRAC;
    ablob->bloby = 2 << BLOBFRAC;
    ablob->blobnext = activeblobs;
    ablob->blobsize = BIGSIZE;
    activeblobs = ablob;
}

void updateblobs(void) {
    struct blob *current = activeblobs;
    struct blob *prev = NULL;

    while (current) {
        current->blobx += current->blobdx;
        current->bloby += current->blobdy;
        current->bloblife--;

        if (current->bloblife <= 0) {
            if (prev) {
                prev->blobnext = current->blobnext;
            } else {
                activeblobs = current->blobnext;
            }
            current->blobnext = freeblobs;
            freeblobs = current;
            current = (prev) ? prev->blobnext : activeblobs;
        } else {
            prev = current;
            current = current->blobnext;
        }
    }
}
