double generate_random_number() {
    return (double)rand() / (double)RAND_MAX;
}

void benchmark_random_generation(int iterations, int array_length) {
    struct timeval start, end;
    double elapsed_time;

    gettimeofday(&start, NULL);

    for (int i = 0; i < iterations; i++) {
        double *random_numbers = (double *)malloc(array_length * sizeof(double));
        for (int j = 0; j < array_length; j++) {
            random_numbers[j] = generate_random_number();
        }
        free(random_numbers);
    }

    gettimeofday(&end, NULL);
    elapsed_time = (end.tv_sec - start.tv_sec) * 1000.0;      // Convert seconds to milliseconds
    elapsed_time += (end.tv_usec - start.tv_usec) / 1000.0;   // Convert microseconds to milliseconds

    printf("Elapsed time: %.2f ms\n", elapsed_time);
}

