#include <string.h>

#define MAX_VERTICES 100
#define MAX_NAME_LENGTH 50

typedef struct {
    char name[MAX_NAME_LENGTH];
    int edges[MAX_VERTICES];
    int edgeCount;
} Vertex;

typedef struct {
    Vertex vertices[MAX_VERTICES];
    int vertexCount;
} Graph;

void CreateGraph(Graph *g) {
    g->vertexCount = 0;
}

void DisplayGraph(Graph g) {
    for (int i = 0; i < g.vertexCount; i++) {
        printf("Vertex: %s, Edges: ", g.vertices[i].name);
        for (int j = 0; j < g.vertices[i].edgeCount; j++) {
            printf("%s ", g.vertices[g.vertices[i].edges[j]].name);
        }
        printf("\n");
    }
}

int FindVertexIndex(Graph *g, const char *name) {
    for (int i = 0; i < g->vertexCount; i++) {
        if (strcmp(g->vertices[i].name, name) == 0) {
            return i;
        }
    }
    return -1;
}

void PutVex(Graph *g, const char *v1, const char *v2) {
    int index1 = FindVertexIndex(g, v1);
    int index2 = FindVertexIndex(g, v2);
    if (index1 != -1 && index2 != -1) {
        g->vertices[index1].edges[g->vertices[index1].edgeCount++] = index2;
    }
}

void InsertVex(Graph *g, const char *name) {
    if (g->vertexCount < MAX_VERTICES) {
        strcpy(g->vertices[g->vertexCount].name, name);
        g->vertices[g->vertexCount].edgeCount = 0;
        g->vertexCount++;
    }
}

