#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <fcntl.h>

#define BUFFER_SIZE 1024
#define SUCCESS 0
#define ERROR -1

int retrieve_file(const char *filename, const char *ip_address, const char *mode) {
    int sock;
    struct sockaddr_in server_addr;
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received, bytes_written;
    FILE *file;

    // Create socket
    sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("Socket creation failed");
        return ERROR;
    }

    // Set up server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(8080); // Assuming port 8080
    if (inet_pton(AF_INET, ip_address, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sock);
        return ERROR;
    }

    // Connect to server
    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Connection failed");
        close(sock);
        return ERROR;
    }

    // Send request for the file
    if (send(sock, filename, strlen(filename), 0) < 0) {
        perror("Send failed");
        close(sock);
        return ERROR;
    }

    // Open file for writing
    file = fopen(filename, mode);
    if (!file) {
        perror("File open failed");
        close(sock);
        return ERROR;
    }

    // Receive file data
    while ((bytes_received = recv(sock, buffer, BUFFER_SIZE, 0)) > 0) {
        bytes_written = fwrite(buffer, sizeof(char), bytes_received, file);
        if (bytes_written < bytes_received) {
            perror("File write failed");
            fclose(file);
            close(sock);
            return ERROR;
        }
    }

    if (bytes_received < 0) {
        perror("Receive failed");
        fclose(file);
        close(sock);
        return ERROR;
    }

    // Clean up
    fclose(file);
    close(sock);
    return SUCCESS;
}
