#define CO 80 // Console width
#define BUFSZ 256

void format_and_display(const char *format, ...) {
    char buffer[BUFSZ];
    va_list args;
    int len, cut_pos;

    va_start(args, format);
    vsnprintf(buffer, sizeof(buffer), format, args);
    va_end(args);

    len = strlen(buffer);
    if (len == 0) return;

    // Handle line breaks for long messages
    while (len > 0) {
        if (len > CO) {
            // Find a cut point
            cut_pos = CO;
            while (cut_pos > 0 && buffer[cut_pos] != ' ' && buffer[cut_pos] != '\n') {
                cut_pos--;
            }
            if (cut_pos == 0) cut_pos = CO; // No space found, cut at CO

            // Print the cut line
            printf("%.*s\n", cut_pos, buffer);
            // Move the remaining part of the message
            memmove(buffer, buffer + cut_pos, len - cut_pos + 1);
            len -= cut_pos;
        } else {
            // Print the remaining message
            printf("%s\n", buffer);
            len = 0; // All printed
        }
    }

    // Allow user to continue typing
    printf("> "); // Prompt for user input
}
