void aes_128_ctr_encrypt(const uint8_t *test_vector, const uint8_t *key_schedule, size_t length, uint8_t *output) {
    AES_KEY aes_key;
    uint8_t counter[AES_BLOCK_SIZE] = {0};
    uint8_t stream[AES_BLOCK_SIZE];
    size_t i;

    // Set the key schedule
    AES_set_encrypt_key(key_schedule, 128, &aes_key);

    for (i = 0; i < length; i += AES_BLOCK_SIZE) {
        // Generate the next block of the keystream
        AES_encrypt(counter, stream, &aes_key);

        // XOR the keystream with the plaintext
        size_t block_size = (length - i < AES_BLOCK_SIZE) ? (length - i) : AES_BLOCK_SIZE;
        for (size_t j = 0; j < block_size; j++) {
            output[i + j] = test_vector[i + j] ^ stream[j];
