bool validate_oauth2_token_response(const char *json_str) {
    json_error_t error;
    json_t *root = json_loads(json_str, 0, &error);

    if (!root) {
        return false; // Invalid JSON
    }

    // Check required fields
    json_t *access_token = json_object_get(root, "access_token");
    json_t *expires_in = json_object_get(root, "expires_in");
    json_t *token_type = json_object_get(root, "token_type");

    if (!json_is_string(access_token) || 
        !json_is_integer(expires_in) || 
        !json_is_string(token_type)) {
        json_decref(root);
        return false; // Missing or invalid fields
    }

    // Check token_type value
    if (strcmp(json_string_value(token_type), "Bearer") != 0) {
        json_decref(root);
        return false; // Invalid token_type
    }

    // Check expires_in value
    if (json_integer_value(expires_in) <= 0) {
        json_decref(root);
        return false; // expires_in must be a positive integer
    }

    // Optional refresh_token check
    json_t *refresh_token = json_object_get(root, "refresh_token");
    if (refresh_token && !json_is_string(refresh_token)) {
        json_decref(root);
        return false; // Invalid refresh_token
    }

    json_decref(root);
    return true; // All checks passed
}
