from Crypto.Cipher import AES
from Crypto.Util.Padding import pad, unpad
from Crypto.Util import Counter
from Crypto.Random import get_random_bytes
import base64

class SymmetricEncryption:
    def __init__(self, key):
        self.key = key

    def encrypt_ecb(self, message):
        cipher = AES.new(self.key, AES.MODE_ECB)
        padded_message = pad(message.encode(), AES.block_size)
        return base64.b64encode(cipher.encrypt(padded_message)).decode()

    def decrypt_ecb(self, encrypted_message):
        cipher = AES.new(self.key, AES.MODE_ECB)
        decrypted_padded_message = cipher.decrypt(base64.b64decode(encrypted_message))
        return unpad(decrypted_padded_message, AES.block_size).decode()

    def encrypt_cbc(self, message):
        cipher = AES.new(self.key, AES.MODE_CBC)
        iv = get_random_bytes(AES.block_size)
        padded_message = pad(message.encode(), AES.block_size)
        encrypted_message = iv + cipher.encrypt(padded_message)
        return base64.b64encode(encrypted_message).decode()

    def decrypt_cbc(self, encrypted_message):
        encrypted_message = base64.b64decode(encrypted_message)
        iv = encrypted_message[:AES.block_size]
        cipher = AES.new(self.key, AES.MODE_CBC, iv)
        decrypted_padded_message = cipher.decrypt(encrypted_message[AES.block_size:])
        return unpad(decrypted_padded_message, AES.block_size).decode()

    def encrypt_cfb64(self, message):
        iv = get_random_bytes(AES.block_size)
        cipher = AES.new(self.key, AES.MODE_CFB, iv)
        encrypted_message = iv + cipher.encrypt(message.encode())
        return base64.b64encode(encrypted_message).decode()

    def decrypt_cfb64(self, encrypted_message):
        encrypted_message = base64.b64decode(encrypted_message)
        iv = encrypted_message[:AES.block_size]
        cipher = AES.new(self.key, AES.MODE_CFB, iv)
        decrypted_message = cipher.decrypt(encrypted_message[AES.block_size:])
        return decrypted_message.decode()

def main():
    key = get_random_bytes(16)  # Example key, must be 16, 24, or 32 bytes long
    message = "Hello, World!"
    mode = "encrypt"  # or "decrypt"
    operation = "ecb"  # or "cbc" or "cfb64"

    encryption = SymmetricEncryption(key)

    if mode == "encrypt":
        if operation == "ecb":
            result = encryption.encrypt_ecb(message)
        elif operation == "cbc":
            result = encryption.encrypt_cbc(message)
        elif operation == "cfb64":
            result = encryption.encrypt_cfb64(message)
    else:
        if operation == "ecb":
            result = encryption.decrypt_ecb(message)
        elif operation == "cbc":
            result = encryption.decrypt_cbc(message)
        elif operation == "cfb64":
            result = encryption.decrypt_cfb64(message)

    print("Result:", result)

if __name__ == "__main__":
