uint8_t* density_compress_data(const char *file_path) {
    // Open file and get its size
    FILE *file = fopen(file_path, "rb");
    if (file == NULL) {
        perror("Error opening file");
        return NULL;
    }

    struct stat file_attributes;
    stat(file_path, &file_attributes);
    uint_fast64_t uncompressed_size = (uint_fast64_t)file_attributes.st_size;

    // Calculate safe size for compression
    uint_fast64_t memory_allocated = density_compress_safe_size(uncompressed_size);
    uint8_t *in = malloc(memory_allocated * sizeof(uint8_t));
    uint8_t *out = malloc(memory_allocated * sizeof(uint8_t));
    if (in == NULL || out == NULL) {
        perror("Memory allocation failed");
        fclose(file);
        free(in);
        free(out);
        return NULL;
    }

    // Read file into memory
    size_t read = fread(in, sizeof(uint8_t), uncompressed_size, file);
    if (uncompressed_size != read) {
        perror("Error reading file");
        fclose(file);
        free(in);
        free(out);
        return NULL;
    }
    fclose(file);

    // Compress data using a density-based algorithm
    density_processing_result result = density_compress(in, uncompressed_size, out, memory_allocated, DENSITY_ALGORITHM_CHAMELEON);
    if (result.state) {
        perror("Compression failed");
        free(in);
        free(out);
        return NULL;
    }

    // Allocate memory for the compressed data
    uint8_t *compressed_data = malloc(result.bytesWritten * sizeof(uint8_t));
    if (compressed_data == NULL) {
        perror("Memory allocation for compressed data failed");
        free(in);
        free(out);
        return NULL;
    }

