#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

void initialize_arrays(size_t n, long **offsets, int **keys, record **records, int min, int max) {
    srand(time(NULL));

    *offsets = malloc(n * sizeof(long));
    *keys = malloc(n * sizeof(int));
    *records = malloc(n * sizeof(record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < n; i++) {
        (*offsets)[i] = 0; // Initialize offsets as needed
        (*keys)[i] = 0;    // Initialize keys as needed
        (*records)[i].value = min + rand() % (max - min + 1); // Random value in range
    }
}
