void des_encrypt(unsigned char key[3], unsigned char *plaintext, unsigned char result[3][8]) {
    DES_key_schedule schedule;
    unsigned char key56[8] = {0};

    // Prepare the key (expand to 8 bytes)
    memcpy(key56, key, 3);
    memset(key56 + 3, 0, 5); // Zero out the remaining bytes

    // Set up the key schedule
    DES_set_key((DES_cblock *)key56, &schedule);

    // Encrypt each block of plaintext
