#include <stdint.h>
#include <string.h>
#include <stdlib.h>

typedef struct {
    uint32_t A, B, C, D;
    uint32_t Nl, Nh;
    uint8_t data[64];
    size_t num;
} MD4_CTX;

void MD4_Transform(MD4_CTX *ctx, const uint8_t *block);
void MD4_Init(MD4_CTX *ctx);
void MD4_Update(MD4_CTX *ctx, const void *data, size_t len);
void MD4_Final(unsigned char *md, MD4_CTX *ctx);
unsigned char *MD4(const unsigned char *d, size_t n, unsigned char *md);

void MD4_Init(MD4_CTX *ctx) {
    ctx->A = 0x67452301;
    ctx->B = 0xEFCDAB89;
    ctx->C = 0x98BADCFE;
    ctx->D = 0x10325476;
    ctx->Nl = 0;
    ctx->Nh = 0;
    ctx->num = 0;
    memset(ctx->data, 0, sizeof(ctx->data));
}

void MD4_Update(MD4_CTX *ctx, const void *data, size_t len) {
    size_t i, j;

    j = (ctx->Nl >> 3) & 0x3F;
    if ((ctx->Nl += (len << 3)) < (len << 3)) {
        ctx->Nh++;
    }
    ctx->Nh += (len >> 29);

    if ((j + len) > 63) {
        memcpy(&ctx->data[j], data, 64 - j);
        MD4_Transform(ctx, ctx->data);
        for (i = 64 - j; i + 63 < len; i += 64) {
            MD4_Transform(ctx, (const uint8_t *)data + i);
        }
        j = 0;
    } else {
        i = 0;
    }
    memcpy(&ctx->data[j], (const uint8_t *)data + i, len - i);
}

void MD4_Final(unsigned char *md, MD4_CTX *ctx) {
    uint8_t padding[64];
    size_t i = ctx->num;

    padding[0] = 0x80;
    memset(padding + 1, 0, sizeof(padding) - 1);
    if (i < 56) {
        MD4_Update(ctx, padding, 56 - i);
    } else {
        MD4_Update(ctx, padding, 64 - i);
        MD4_Update(ctx, padding, 56);
    }

    ctx->data[56] = ctx->Nh;
    ctx->data[57] = ctx->Nh >> 8;
    ctx->data[58] = ctx->Nh >> 16;
    ctx->data[59] = ctx->Nh >> 24;
    ctx->data[60] = ctx->Nl;
    ctx->data[61] = ctx->Nl >> 8;
    ctx->data[62] = ctx->Nl >> 16;
    ctx->data[63] = ctx->Nl >> 24;

    MD4_Transform(ctx, ctx->data);
    memcpy(md, &ctx->A, 4);
    memcpy(md + 4, &ctx->B, 4);
    memcpy(md + 8, &ctx->C, 4);
    memcpy(md + 12, &ctx->D, 4);
}

