unsigned char* compute_hash(const unsigned char *input, size_t length, const char *algorithm) {
    unsigned char *hash_value = NULL;

    if (strcmp(algorithm, "MD5") == 0) {
        hash_value = (unsigned char *)malloc(MD5_DIGEST_LENGTH);
        MD5(input, length, hash_value);
    } else if (strcmp(algorithm, "SHA256") == 0) {
        hash_value = (unsigned char *)malloc(SHA256_DIGEST_LENGTH);
        SHA256(input, length, hash_value);
    } else {
        return NULL; // Unsupported algorithm
    }

    return hash_value;
}

int main() {
    const char *data = "Hello, World!";
    size_t data_length = strlen(data);

    unsigned char *hash_md5 = compute_hash((unsigned char *)data, data_length, "MD5");
    unsigned char *hash_sha256 = compute_hash((unsigned char *)data, data_length, "SHA256");

    if (hash_md5) {
        printf("MD5: ");
        for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
            printf("%02x", hash_md5[i]);
