void write_data_to_file(double **double_array, int **int_array, int rows, int cols, const char *base_filename) {
    // Perform basic calculations
    double sum = 0.0;
    int count = 0;

    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            sum += double_array[i][j];
            count++;
        }
    }
    double average = sum / count;

    // Generate file name
    char filename[256];
    sprintf(filename, "%s_average-%.2f.txt", base_filename, average);

    // Open file for writing
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Error opening file");
        return;
    }

    // Write the average to the file
    fwrite(&average, sizeof(double), 1, fp);

    // Write the 2D arrays to the file
    fwrite(int_array[0], sizeof(int), rows * cols, fp);
    for (int i = 0; i < rows; ++i) {
        fwrite(double_array[i], sizeof(double), cols, fp);
    }

    // Close the file
    fclose(fp);
}
