#include <windows.h>
#include <stdio.h>

void getJREPath(char* jrePath, size_t pathSize)
{
    HKEY rootKey = HKEY_LOCAL_MACHINE;
    char currVer[16];
    HKEY myKey;
    DWORD readType;
    DWORD hsize = sizeof(currVer);

    if (RegOpenKeyEx(rootKey, "Software\\JavaSoft\\Java Runtime Environment", 0, KEY_QUERY_VALUE, &myKey) != ERROR_SUCCESS)
    {
        snprintf(jrePath, pathSize, "Error: Unable to open registry key.");
        return;
    }

    if (RegQueryValueEx(myKey, "CurrentVersion", NULL, &readType, (LPBYTE)currVer, &hsize) != ERROR_SUCCESS)
    {
        RegCloseKey(myKey);
        snprintf(jrePath, pathSize, "Error: Unable to read CurrentVersion.");
        return;
    }
    RegCloseKey(myKey);

    char pathKey[1024];
    snprintf(pathKey, sizeof(pathKey), "Software\\JavaSoft\\Java Runtime Environment\\%s", currVer);

    if (RegOpenKeyEx(rootKey, pathKey, 0, KEY_QUERY_VALUE, &myKey) != ERROR_SUCCESS)
    {
        snprintf(jrePath, pathSize, "Error: Unable to open JRE version key.");
        return;
    }

    hsize = pathSize;
    if (RegQueryValueEx(myKey, "JavaHome", NULL, &readType, (LPBYTE)jrePath, &hsize) != ERROR_SUCCESS)
    {
        RegCloseKey(myKey);
        snprintf(jrePath, pathSize, "Error: Unable to read JavaHome.");
        return;
    }
    RegCloseKey(myKey);
}
