#include <utility>
#include <cstdlib>
#include <algorithm>

using namespace std;

static void FindBestCombination(vector<pair<int, bool>> values, int targetValue, vector<bool>& bestCombination, int& bestSum, int iterations = 1000) {
    vector<bool> currentCombination;
    bestCombination.assign(values.size(), false);
    bestSum = 0;

    for (int rep = 0; rep < iterations; rep++) {
        currentCombination.assign(values.size(), false);
        int currentSum = 0;
        bool reachedTarget = false;

        for (int pass = 0; pass < 2 && !reachedTarget; pass++) {
            for (unsigned int i = 0; i < values.size(); i++) {
                if (pass == 0 ? rand() % 2 : !currentCombination[i]) {
                    if (!values[i].second) { // Only consider unselected values
                        currentSum += values[i].first;
                        currentCombination[i] = true;

                        if (currentSum >= targetValue) {
                            reachedTarget = true;
                            if (currentSum < bestSum || bestSum == 0) {
                                bestSum = currentSum;
                                bestCombination = currentCombination;
                            }
                            currentSum -= values[i].first;
                            currentCombination[i] = false;
                        }
                    }
                }
            }
        }
    }
}
