#include <vector>
#include <algorithm>
#include <random>
#include <gtest/gtest.h>

template <typename T>
class sorted_vector_set {
public:
    void insert(const T& value) {
        if (std::find(data.begin(), data.end(), value) == data.end()) {
            data.push_back(value);
            std::sort(data.begin(), data.end());
        }
    }

    void insert(typename std::vector<T>::iterator first, typename std::vector<T>::iterator last) {
        for (auto it = first; it != last; ++it) {
            insert(*it);
        }
    }

    bool operator==(const sorted_vector_set& other) const {
        return data == other.data;
    }

    bool empty() const {
        return data.empty();
    }

    size_t size() const {
        return data.size();
    }

    typename std::vector<T>::iterator begin() {
        return data.begin();
    }

    typename std::vector<T>::iterator end() {
        return data.end();
    }

    void clear() {
        data.clear();
    }

private:
    std::vector<T> data;
};

void check_invariant(const sorted_vector_set<int>& s) {
    // Check that the elements are sorted and unique
    auto it = s.begin();
    if (it != s.end()) {
        int last = *it;
        ++it;
        for (; it != s.end(); ++it) {
            EXPECT_GE(*it, last);
            last = *it;
        }
    }
}

TEST(SortedVectorSetTest, CreateAndCheckSets) {
