#include <iostream>
#include <cstring>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <unistd.h>

class RobotClient {
public:
    RobotClient(const char* ip, int port);
    ~RobotClient();
    bool initializeConnection();
    bool sendCommand(const std::string& command);
    std::string receiveResponse();

private:
    char m_pcIp[16];
    int m_nPort;
    int m_nSocket;
    struct sockaddr_in m_server;

    void closeConnection();
};

RobotClient::RobotClient(const char* ip, int port) {
    strncpy(m_pcIp, ip, sizeof(m_pcIp) - 1);
    m_pcIp[sizeof(m_pcIp) - 1] = '\0';
    m_nPort = port;
    m_nSocket = -1;
}

RobotClient::~RobotClient() {
    closeConnection();
}

bool RobotClient::initializeConnection() {
    m_nSocket = socket(AF_INET, SOCK_STREAM, 0);
    if (m_nSocket == -1) {
        std::cerr << "Could not create socket" << std::endl;
        return false;
    }

    m_server.sin_family = AF_INET;
    m_server.sin_port = htons(m_nPort);
    if (inet_pton(AF_INET, m_pcIp, &m_server.sin_addr) <= 0) {
        std::cerr << "Invalid address/ Address not supported" << std::endl;
        return false;
    }

    if (connect(m_nSocket, (struct sockaddr*)&m_server, sizeof(m_server)) < 0) {
        std::cerr << "Connection failed" << std::endl;
        return false;
    }

    return true;
}

bool RobotClient::sendCommand(const std::string& command) {
    if (send(m_nSocket, command.c_str(), command.size(), 0) < 0) {
        std::cerr << "Send failed" << std::endl;
        return false;
    }
    return true;
}

std::string RobotClient::receiveResponse() {
    char buffer[1024] = {0};
    int bytesRead = recv(m_nSocket, buffer, sizeof(buffer) - 1, 0);
    if (bytesRead < 0) {
        std::cerr << "Receive failed" << std::endl;
        return "";
    }
    buffer[bytesRead] = '\0';
    return std::string(buffer);
}

void RobotClient::closeConnection() {
    if (m_nSocket != -1) {
        close(m_nSocket);
        m_nSocket = -1;
    }
}

int main() {
    RobotClient client("192.168.1.100", 8080);
    if (!client.initializeConnection()) {
        return -1;
    }

    std::string command;
    while (true) {
        std::cout << "Enter command (or 'exit' to quit): ";
        std::getline(std::cin, command);
        if (command == "exit") {
            break;
        }

        if (client.sendCommand(command)) {
            std::string response = client.receiveResponse();
            std::cout << "Response: " << response << std::endl;
        }
    }

    return 0;
}
