#include <stdio.h>

void setEnvironmentVariable(const char *var) {
    char *equalSign = strchr(var, '=');
    if (equalSign) {
        // Remove existing environment variable if it exists
        char *envName = strndup(var, equalSign - var);
        unsetenv(envName);
        free(envName);

        // Allocate memory for the new environment variable
        char *copyEnv = (char *)malloc(strlen(var) + 1);
        if (copyEnv) {
            strcpy(copyEnv, var);
            // Set the new environment variable
            putenv(copyEnv);
        }
    }
}
