#include <map>
#include <string>

struct Page {
    int id;
    char* data;

    Page(int identifier, char* pageData) : id(identifier), data(pageData) {}
    int getId() const { return id; }
};

class PagePool {
private:
    std::map<int, Page*> pages;

public:
    Page* createPage(int id, char* data) {
        Page* newPage = new Page(id, data);
        pages.insert(std::make_pair(id, newPage));
        return newPage;
    }

    Page* retrievePage(int id) {
        auto it = pages.find(id);
        if (it != pages.end()) {
            return it->second;
        }
        return nullptr;
    }

    void deletePage(int id) {
        auto it = pages.find(id);
        if (it != pages.end()) {
            delete it->second; // Free the memory
            pages.erase(it);
        }
    }

    ~PagePool() {
        for (auto& pair : pages) {
            delete pair.second; // Free memory for all pages
        }
    }
};
