    db->size += strlen(key) + strlen(value) + 2;
}

void load_keys(Database *db, const char *keys[], const char *values[], size_t num_keys) {
    for (size_t i = 0; i < num_keys; i++) {
        load_data(db, keys[i], values[i]);
    }
    // Commit any remaining changes after loading all keys
    if (db->size > 0) {
        commit_changes(db);
    }
}

int main() {
