template <typename Container>
std::vector<size_t> get_unique_element_counts(const std::vector<Container>& containers) {
    std::vector<size_t> counts;
    for (const auto& container : containers) {
        std::unordered_set<typename Container::value_type> unique_elements(container.begin(), container.end());
        counts.push_back(unique_elements.size());
    }
    return counts;
}
