#include <algorithm>
#include <iterator>
#include <vector>

template <typename Iterator>
class Graph {
public:
    using vid_t = int;
    using idx_t = size_t;

    Graph() : adj_(nullptr), vtx_(nullptr), nv_(0), ne_(0) {}
    ~Graph() {
        delete[] adj_;
        delete[] vtx_;
        delete[] deg_;
    }

    void createAdjacencyList(Iterator beg, Iterator end) {
        nv_ = *(std::max_element(beg, end)) + 1;
        ne_ = std::distance(beg, end) / 2;
        if (!(nv_ && ne_)) { return; }

        adj_ = new vid_t[2 * ne_];
        vtx_ = new vid_t*[nv_ + 1];
        deg_ = new idx_t[nv_];
        std::fill(deg_, deg_ + nv_, 0);

        // Count degrees
        for (Iterator el = beg; el != end; el += 2) {
            deg_[*el]++;
            deg_[*(el + 1)]++;
        }

        // Set heads
        vtx_[0] = 0;
        for (idx_t i = 0; i < nv_; ++i) {
            vtx_[i + 1] = vtx_[i] + deg_[i];
        }

        // Fill adjacency list
        std::vector<idx_t> current(nv_, 0);
        for (Iterator el = beg; el != end; el += 2) {
            vid_t u = *el;
            vid_t v = *(el + 1);
            adj_[vtx_[u] + current[u]++] = v;
            adj_[vtx_[v] + current[v]++] = u; // For undirected graph
        }
    }

private:
    vid_t* adj_;
    vid_t** vtx_;
    idx_t* deg_;
    idx_t nv_;
    idx_t ne_;
};
