void createTempFile() {
    // Create a temporary file
    char tempFileName[] = "tempfileXXXXXX";
    int fd = mkstemp(tempFileName);
    if (fd == -1) {
        std::cerr << "Failed to create temporary file." << std::endl;
        return;
    }

    // Save some data to the temporary file
    std::ofstream tempFile(tempFileName);
    if (tempFile.is_open()) {
        tempFile << "This is some temporary data." << std::endl;
        tempFile.close();
    } else {
        std::cerr << "Failed to write to temporary file." << std::endl;
        close(fd);
        return;
