#include <stdio.h>
#include <stdlib.h>
#include <cufft.h>

#define FFTN1 256
#define FFTN2 256

void allocHostBuffer(void** buffer, size_t size) {
    *buffer = malloc(size);
}

void allocDeviceBuffer(cufftComplex** buffer, size_t size) {
    cudaMalloc((void**)buffer, size);
}

void copyToDevice(cufftComplex* deviceBuffer, cufftComplex* hostBuffer, size_t size) {
    cudaMemcpy(deviceBuffer, hostBuffer, size, cudaMemcpyHostToDevice);
}

void copyToHost(cufftComplex* hostBuffer, cufftComplex* deviceBuffer, size_t size) {
    cudaMemcpy(hostBuffer, deviceBuffer, size, cudaMemcpyDeviceToHost);
}

void freeDeviceBuffer(cufftComplex* buffer) {
    cudaFree(buffer);
}

void freeHostBuffer(void* buffer) {
    free(buffer);
}

int main() {
    int n_ffts = 1;
    size_t N = FFTN1 * FFTN2;
    size_t used_bytes = N * sizeof(cufftComplex);

    cufftComplex *source, *result, *d_source, *d_result;
    cufftHandle plan;

    // Allocate host memory
    allocHostBuffer((void**)&source, used_bytes);
    allocHostBuffer((void**)&result, used_bytes);

    // Initialize host memory with random values
    for (size_t i = 0; i < N; i++) {
        source[i].x = (rand() / (float)RAND_MAX) * 2 - 1;
        source[i].y = (rand() / (float)RAND_MAX) * 2 - 1;
    }

    // Allocate device memory
    allocDeviceBuffer(&d_source, used_bytes);
    allocDeviceBuffer(&d_result, used_bytes);

    // Copy data to device
    copyToDevice(d_source, source, used_bytes);

    // Create FFT plan
    cufftPlan2d(&plan, FFTN1, FFTN2, CUFFT_C2C);

    // Execute FFT
    cufftExecC2C(plan, d_source, d_result, CUFFT_FORWARD);

    // Copy result back to host
    copyToHost(result, d_result, used_bytes);

    // Clean up
    cufftDestroy(plan);
    freeDeviceBuffer(d_source);
    freeDeviceBuffer(d_result);
    freeHostBuffer(source);
    freeHostBuffer(result);

    return 0;
}
