#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

void format_signed_integer(int8_t value, char *output) {
    char buffer[50];
    char formatted[60] = {0};
    int index = 0;
    int is_negative = value < 0;

    if (is_negative) {
        value = -value;
    }

    // Convert integer to string
    itoa(value, buffer, 10);

    // Add sign if negative
    if (is_negative) {
        formatted[index++] = '-';
    }

    int len = strlen(buffer);
    for (int i = 0; i < len; i++) {
        if (i > 0 && (len - i) % 3 == 0) {
            formatted[index++] = ',';
        }
        formatted[index++] = buffer[i];
    }
    formatted[index] = '\0';

    // Handle line breaks at 78 characters
    int output_index = 0;
    for (int i = 0; i < index; i++) {
        if (output_index == 78) {
            output[output_index++] = '\n';
            output_index = 0;
        }
        output[output_index++] = formatted[i];
    }
    output[output_index] = '\0';
}
