int32_t splitUnicodeString(const UnicodeString &input, UnicodeString **&substrings, int32_t *&lengths) {
    UErrorCode status = U_ZERO_ERROR;
    int32_t list_length = 0;
    UChar32 cp = 0;
    int32_t start = 0;
    int32_t i = 0;

    if (input.length() == 0) {
        substrings = (UnicodeString **)uprv_malloc(sizeof(UnicodeString *));
        lengths = (int32_t *)uprv_malloc(sizeof(int32_t));
        if (substrings == NULL || lengths == NULL) {
            return -1; // Memory allocation error
        }
        substrings[0] = new UnicodeString();
        lengths[0] = 0;
        return 1;
    }

    int32_t inputLength = input.length();
    substrings = (UnicodeString **)uprv_malloc(inputLength * sizeof(UnicodeString *));
    lengths = (int32_t *)uprv_malloc(inputLength * sizeof(int32_t));
    if (substrings == NULL || lengths == NULL) {
        return -1; // Memory allocation error
    }

    for (i = 0; i < inputLength; i += U16_LENGTH(cp)) {
        cp = input.char32At(i);
        if (isCanonSegmentStarter(cp)) {
            if (i > start) {
                substrings[list_length] = new UnicodeString(input, start, i - start);
                lengths[list_length] = i - start;
                list_length++;
            }
            start = i;
        }
    }
    if (start < inputLength) {
        substrings[list_length] = new UnicodeString(input, start, inputLength - start);
        lengths[list_length] = inputLength - start;
        list_length++;
    }

    return list_length;
}
