#include <stdarg.h>
#include <stdlib.h>

int* reverseArguments(int numArgs, ...) {
    va_list args;
    va_start(args, numArgs);

    int* argArray = (int*)malloc(numArgs * sizeof(int));
    if (argArray == NULL) {
        return NULL; // Allocation failed
    }

    // Store arguments in the array
    for (int i = 0; i < numArgs; i++) {
        argArray[i] = va_arg(args, int);
    }
    va_end(args);

    // Reverse the order of the arguments
    int* reversedArray = (int*)malloc(numArgs * sizeof(int));
    if (reversedArray == NULL) {
        free(argArray);
        return NULL; // Allocation failed
    }

    for (int i = 0; i < numArgs; i++) {
        reversedArray[i] = argArray[numArgs - 1 - i];
    }

    free(argArray);
    return reversedArray; // Return pointer to the allocated reversed array
}
