import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import javax.imageio.ImageIO;

public byte[] generatePPMImage(PageDocument doc, int pageNumber, int displayWidth, int displayHeight) throws Exception {
    double kx, ky;
    int pageWidth = doc.getPageCropWidth(pageNumber);
    kx = ((double) displayWidth) / pageWidth * 72.0;
    int pageHeight = doc.getPageCropHeight(pageNumber);
    ky = ((double) displayHeight) / pageHeight * 72.0;
    int resolution = (int) Math.min(kx, ky);

    BufferedImage image = doc.displayPage(pageNumber, resolution, resolution);

    ByteArrayOutputStream baos = new ByteArrayOutputStream();
    ImageIO.write(image, "ppm", baos);
    return baos.toByteArray();
}
