#include <iostream>
#include <vector>
#include <random>
#include <cassert>

class Matrix {
public:
    static std::vector<std::vector<double>> projectRows(const std::vector<std::vector<double>>& matrix, const std::vector<double>& vector) {
        std::vector<std::vector<double>> result(matrix.size(), std::vector<double>(vector.size(), 0.0));
        for (size_t i = 0; i < matrix.size(); ++i) {
            for (size_t j = 0; j < vector.size(); ++j) {
                result[i][j] = matrix[i][j] * vector[j]; // Simple projection operation
            }
        }
        return result;
    }
};

void testMatrixProjection(int numSamples, int tableSize, int inputDim) {
    std::vector<std::vector<double>> matrix(tableSize, std::vector<double>(inputDim));
    std::vector<double> vector(inputDim);

    // Randomize matrix and vector
    std::mt19937 rng(0); // Fixed seed for reproducibility
    std::uniform_real_distribution<double> dist(0.0, 1.0);

    for (size_t i = 0; i < tableSize; ++i) {
        for (size_t j = 0; j < inputDim; ++j) {
            matrix[i][j] = dist(rng);
        }
    }

    for (size_t j = 0; j < inputDim; ++j) {
        vector[j] = dist(rng);
    }

    // Perform projection
    auto projected = Matrix::projectRows(matrix, vector);

    // Log inputs and outputs
    std::cout << "Inputs:\n";
    std::cout << "Matrix:\n";
    for (const auto& row : matrix) {
        for (const auto& val : row) {
            std::cout << val << " ";
        }
        std::cout << "\n";
    }

    std::cout << "Vector:\n";
    for (const auto& val : vector) {
        std::cout << val << " ";
    }
    std::cout << "\nOutputs (Projected):\n";
    for (const auto& row : projected) {
        for (const auto& val : row) {
