#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_NODES 26

int graph[MAX_NODES][MAX_NODES];
int visited[MAX_NODES];

void dfs(int node, int n) {
    visited[node] = 1;
    for (int i = 0; i < n; i++) {
        if (graph[node][i] && !visited[i]) {
            dfs(i, n);
        }
    }
}

int countConnectedComponents(int n) {
    int count = 0;
    memset(visited, 0, sizeof(visited));
    for (int i = 0; i < n; i++) {
        if (!visited[i]) {
            dfs(i, n);
            count++;
        }
    }
    return count;
}

int buildGraphAndCountComponents(char edges[][6], int m) {
    memset(graph, 0, sizeof(graph));
    for (int i = 0; i < m; i++) {
        int u = edges[i][0] - 'A';
        int v = edges[i][2] - 'A';
        graph[u][v] = 1;
        graph[v][u] = 1; // Assuming undirected graph
    }
    return countConnectedComponents(MAX_NODES);
}

