                                &buf,
                                &count_xferred,
                                &tag,
                                timeout,
                                NULL);
                TEST_CHK_BCCEQ(bcc);
            }
            getri(&ri);
            assert(ri.user_id == (loop + inx));
            bcc = BREPLYX(recv_buffer,
                          0,
                          &count_written,
                          ri.message_tag,
                          XZFIL_ERR_OK);
            TEST_CHK_BCCEQ(bcc);
        }

        // read close message
        bcc = BREADUPDATEX(filenum,
                           recv_buffer,
                           BUFSIZ,
                           &count_read,
                           0);
        if (nowait) {
            TEST_CHK_BCCEQ(bcc);
            tfilenum = filenum;
            bcc = BAWAITIOX(&tfilenum,
                            &buf,
                            &count_xferred,
                            &tag,
                            timeout,
                            NULL);
        }
        TEST_CHK_BCCNE(bcc);
        assert(sys_msg->u_z_msg.z_msgnumber[0] == XZSYS_VAL_SMSG_CLOSE);
        getri(&ri);
        assert(ri.user_id == 0);
        bcc = BREPLYX(recv_buffer,
                      0,
                      &count_written,
                      ri.message_tag,
                      XZFIL_ERR_OK);
        TEST_CHK_BCCEQ(bcc);
        ferr = BFILE_CLOSE_(filenum, 0);
        TEST_CHK_FEOK(ferr);
    }
    if (client) {
        ferr = file_mon_process_shutdown();
        TEST_CHK_FEIGNORE(ferr);
    } else {
        ferr = file_mon_process_shutdown();
        TEST_CHK_FEOK(ferr);
    }
    util_test_finish(client);
    return 0;
