#include <vector>
#include <random>

class EmbeddingLayer {
public:
    EmbeddingLayer(int embedding_size, int label_width, int num_label_types, float stddev) 
        : embedding_size(embedding_size), label_width(label_width), num_label_types(num_label_types) {
        initializeWeights(stddev);
    }

    std::vector<float>& getWeights() {
        return weights;
    }

private:
    int embedding_size;
    int label_width;
    int num_label_types;
    std::vector<float> weights;

    void initializeWeights(float stddev) {
        int total_size = embedding_size * label_width * num_label_types;
        weights.resize(total_size);

        std::random_device rd;
        std::mt19937 gen(rd());
        std::normal_distribution<> dis(0.0, stddev);

        for (int i = 0; i < total_size; ++i) {
            weights[i] = dis(gen);
        }
    }
};
