static volatile std::sig_atomic_t running = 1;

void signal_handler(int signal) {
    running = 0;
}

void check(const char* msg, lcb_STATUS err) {
    if (err != LCB_SUCCESS) {
        std::cerr << msg << ": " << lcb_strerror_short(err) << std::endl;
        exit(EXIT_FAILURE);
    }
}

void row_callback(lcb_INSTANCE *instance, int cbtype, const lcb_RESPQUERY *resp) {
    if (lcb_respquery_status(resp) != LCB_SUCCESS) {
        std::cerr << "Query failed: " << lcb_strerror_short(lcb_respquery_status(resp)) << std::endl;
        return;
    }
    const char *row;
    size_t row_len;
    lcb_respquery_row(resp, &row, &row_len);
    std::cout << "Row: " << std::string(row, row_len) << std::endl;
}

