#include <CL/cl.h>
#include <vector>

void executeKernel(cl_context context, cl_command_queue queue, cl_kernel kernel, 
                   const std::vector<float>& inputData, std::vector<float>& outputData, 
                   std::vector<float>& tempStorage) {
    // Allocate device memory
    cl_mem d_input = clCreateBuffer(context, CL_MEM_READ_ONLY | CL_MEM_COPY_HOST_PTR, 
                                     inputData.size() * sizeof(float), 
                                     (void*)inputData.data(), nullptr);
    cl_mem d_output = clCreateBuffer(context, CL_MEM_WRITE_ONLY, 
                                      outputData.size() * sizeof(float), nullptr, nullptr);
    cl_mem d_temp = clCreateBuffer(context, CL_MEM_READ_WRITE, 
                                    tempStorage.size() * sizeof(float), nullptr, nullptr);

    // Set kernel arguments
    clSetKernelArg(kernel, 0, sizeof(cl_mem), &d_input);
    clSetKernelArg(kernel, 1, sizeof(cl_mem), &d_output);
    clSetKernelArg(kernel, 2, sizeof(cl_mem), &d_temp);

    // Define the global and local work sizes
    size_t globalWorkSize = inputData.size();
    size_t localWorkSize = 64; // Example local size

    // Execute the kernel
    clEnqueueNDRangeKernel(queue, kernel, 1, nullptr, &globalWorkSize, &localWorkSize, 0, nullptr, nullptr);

    // Copy the result back to host memory
    clEnqueueReadBuffer(queue, d_output, CL_TRUE, 0, 
                         outputData.size() * sizeof(float), 
                         outputData.data(), 0, nullptr, nullptr);

    // Clean up
    clReleaseMemObject(d_input);
    clReleaseMemObject(d_output);
    clReleaseMemObject(d_temp);
}
