#include <fstream>
#include <system_error>
#include <cstdint>
#include <cstring>
#include <new>

struct HeightMapPoint {
    float x, y, z;
};

struct HeightMap {
    std::uint32_t width, height;
    HeightMapPoint* data;

    ~HeightMap() {
        if (data) {
            delete[] data;
        }
    }
};

HeightMap* readBitmapFile(const char* filename) {
    std::ifstream file(filename, std::ios::binary);
    if (!file.is_open()) {
        throw std::system_error(errno, std::generic_category(), "Failed to open file: " + filename);
    }

    BITMAPFILEHEADER bitmapFileHeader;
    BITMAPINFOHEADER bitmapInfoHeader;

    file.read(reinterpret_cast<char*>(&bitmapFileHeader), sizeof(bitmapFileHeader));
    if (bitmapFileHeader.bfType != 0x4D42) { // BM
        throw std::runtime_error("Invalid bitmap file header.");
    }

    file.read(reinterpret_cast<char*>(&bitmapInfoHeader), sizeof(bitmapInfoHeader));

    if (bitmapInfoHeader.biBitCount != 24) {
        throw std::runtime_error("Unsupported bitmap bit depth.");
    }

    std::uint32_t imageSize = bitmapInfoHeader.biWidth * bitmapInfoHeader.biHeight * 3;
    HeightMap* heightMap = new HeightMap();
    heightMap->width = bitmapInfoHeader.biWidth;
    heightMap->height = bitmapInfoHeader.biHeight;

    heightMap->data = new HeightMapPoint[bitmapInfoHeader.biWidth * bitmapInfoHeader.biHeight];
    if (!heightMap->data) {
        delete heightMap;
        throw std::bad_alloc();
    }

    file.seekg(bitmapFileHeader.bfOffBits);

    for (std::uint32_t i = 0; i < bitmapInfoHeader.biWidth * bitmapInfoHeader.biHeight; ++i) {
        HeightMapPoint& point = heightMap->data[i];
        file.read(reinterpret_cast<char*>(&point.y), sizeof(point.y));
        point.x = static_cast<float>(i % bitmapInfoHeader.biWidth);
        point.z = static_cast<float>(i / bitmapInfoHeader.biWidth);
    }

    file.close();

    return heightMap;
}
