template <std::size_t N>
void test_op_xor_eq()
{
    std::bitset<N> bitset1;
    std::bitset<N> bitset2;

    std::mt19937 generator; // Mersenne Twister pseudo-random number generator
    std::uniform_int_distribution<int> distribution(0, 1); // Distribution for generating random numbers

