#include <stddef.h>

void* aligned_malloc(size_t size) {
    const size_t cache_line_size = 64; // Example cache line size
    void* ptr = malloc(size + cache_line_size + sizeof(void*));
    if (!ptr) {
        return NULL;
    }

    // Align the pointer
    void** aligned_ptr = (void**)(((uintptr_t)(ptr) + sizeof(void*) + cache_line_size - 1) & ~(cache_line_size - 1));
    aligned_ptr[-1] = ptr; // Store the original pointer just before the aligned pointer

    return aligned_ptr;
}

void aligned_free(void* ptr) {
    if (ptr) {
        free(((void**)ptr)[-1]); // Free the original pointer
    }
}

int test_memory_alignment(size_t size) {
    void* mem = aligned_malloc(size);
    if (!mem) {
        return 0; // Allocation failed
    }

    // Check alignment
    const size_t cache_line_size = 64; // Example cache line size
    if (((uintptr_t)mem % cache_line_size) != 0) {
        aligned_free(mem);
        return 0; // Not properly aligned
    }

    aligned_free(mem);
    return 1; // Properly aligned
}

