template <typename T>
ucs_status_t atomic_add(entity *e, void *mem_location, size_t size, ucp_rkey_t rkey) {
    ucs_status_t status;
    T value;

    // Check if the memory location is properly aligned
    if ((uintptr_t)mem_location % alignof(T) != 0) {
        return UCS_ERR_INVALID_ARG;
    }

    // Read the current value from the memory location
    value = *static_cast<T*>(mem_location);

    // Perform the atomic addition operation based on the size of T
