        status = ucp_atomic_add32(e->ep(), static_cast<uint32_t>(static_cast<uint32_t>(value) + static_cast<uint32_t>(1)),
                                 static_cast<uintptr_t>(mem_location), rkey);
    } else if (sizeof(T) == sizeof(uint64_t)) {
        status = ucp_atomic_add64(e->ep(), static_cast<uint64_t>(value) + 1, static_cast<uintptr_t>(mem_location), rkey);
