        EVP_DigestFinal_ex(ctx, hash, &hash_length) != 1) {
        EVP_MD_CTX_free(ctx);
        return false; // Hashing failed
    }

    EVP_MD_CTX_free(ctx);

    if (hash_length != certificate->signature_length) {
        return false; // Hash lengths do not match
    }

    return CRYPTO_memcmp(hash, certificate->signature, hash_length) == 0;
