int64_t FindBestCombination(const std::vector<std::pair<int64_t, bool>>& values, int64_t targetValue, int iterations = 1000) {
    std::vector<char> bestCombination;
    int64_t bestTotal = -1;

    for (int nRep = 0; nRep < iterations; nRep++) {
        std::vector<char> currentCombination(values.size(), false);
        int64_t currentTotal = 0;

