#include <iostream>
#include <vector>
#include <cstdlib>
#include <cstring>

void convolution(const float* input_image, const float* filter, const float* bias, 
                 float* output_image, int input_height, int input_width, 
                 int filter_height, int filter_width, int stride, int output_height, int output_width) {
    // Perform convolution operation
    for (int y = 0; y < output_height; ++y) {
        for (int x = 0; x < output_width; ++x) {
            float sum = 0.0f;
            for (int fy = 0; fy < filter_height; ++fy) {
                for (int fx = 0; fx < filter_width; ++fx) {
                    int input_y = y * stride + fy;
                    int input_x = x * stride + fx;
                    sum += input_image[input_y * input_width + input_x] * filter[fy * filter_width + fx];
                }
            }
            output_image[y * output_width + x] = sum + bias[0]; // Assuming single bias for simplicity
        }
    }
}

