#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_TOKENS 100
#define MAX_TOKEN_LENGTH 50

char** parse_multiline_string(const char* input, int* token_count) {
    char** token_list = malloc(MAX_TOKENS * sizeof(char*));
    char* input_copy = strdup(input);
    char* line = strtok(input_copy, "\n");
    int count = 0;

    while (line != NULL) {
        char* token = strtok(line, " ");
        while (token != NULL) {
            // Trim leading and trailing whitespace
            while (isspace((unsigned char)*token)) token++;
            char* end = token + strlen(token) - 1;
            while (end > token && isspace((unsigned char)*end)) end--;
            end[1] = '\0'; // Null-terminate the trimmed string

            // Check if the token is valid
            if ((isdigit(*token) || *token == '-' || *token == '"') && count < MAX_TOKENS) {
                token_list[count] = strdup(token);
                count++;
            }
            token = strtok(NULL, " ");
        }
        line = strtok(NULL, "\n");
    }

    free(input_copy);
    *token_count = count;
    return token_list;
}

void free_token_list(char** token_list, int token_count) {
    for (int i = 0; i < token_count; i++) {
        free(token_list[i]);
    }
    free(token_list);
}

int main() {
    const char* input = " 123 -45 \"hello\" \n 67.89 -\"world\" \n invalid_token ";
