    if (result == NULL) {
        return NULL; // Memory allocation failed
    }

    // Find the position of the delimiter (e.g., ':')
    const char* delimiter = strchr(input, ':');
    if (delimiter != NULL) {
        size_t server_name_length = delimiter - input;
        size_t password_length = strlen(delimiter + 1);

        // Allocate memory for server name and password
        server_name = malloc(server_name_length + 1);
        password = malloc(password_length + 1);

        if (server_name == NULL || password == NULL) {
            free(server_name);
            free(password);
            free(result);
            return NULL; // Memory allocation failed
        }

        // Copy the server name and password
        strncpy(server_name, input, server_name_length);
        server_name[server_name_length] = '\0'; // Null-terminate the string
        strcpy(password, delimiter + 1); // Copy the password

        result[0] = server_name;
        result[1] = password;
    } else {
        // If no delimiter is found, return NULL
        free(result);
        return NULL;
    }

    return result; // Return the tuple
