        param->sourceHeight = svtParam->sourceHeight;
        param->fpsNum = svtParam->frameRateNumerator;
        param->fpsDenom = svtParam->frameRateDenominator;
        svtParam->encoderBitDepth = inputBitDepth;
    }
#endif

