#include <string>
#include <vector>
#include <sstream>

std::vector<std::string> extractUrlComponents(const std::string& url) {
    std::vector<std::string> components;
    std::string protocol, host, port;

    std::size_t protocolEnd = url.find("://");
    if (protocolEnd != std::string::npos) {
        protocol = url.substr(0, protocolEnd);
        components.push_back(protocol);

        std::size_t hostStart = protocolEnd + 3; // Skip "://"
        std::size_t portStart = url.find(':', hostStart);
        std::size_t hostEnd = (portStart != std::string::npos) ? portStart : url.length();

        host = url.substr(hostStart, hostEnd - hostStart);
        components.push_back(host);

        if (portStart != std::string::npos) {
            std::size_t portEnd = url.find('/', portStart);
            port = url.substr(portStart + 1, (portEnd != std::string::npos ? portEnd : url.length()) - portStart - 1);
            components.push_back(port);
        } else {
            components.push_back(""); // No port specified
        }
    }

    return components;
}
