    int count;
    SkScalar *fIntervals;
    SkScalar fIntervalLength;
    int fInitialDashIndex;
    SkScalar fInitialDashLength;
} SkDashPathEffect;

SkDashPathEffect* CreateDashPathEffect(const SkScalar intervals[], int count, SkScalar phase, bool scaleToFit) {
    SkDashPathEffect *effect = NULL;

    if (!intervals || !count || count <= 0) {
        goto error;
    }

    effect = (SkDashPathEffect *)sk_malloc_throw(sizeof(SkDashPathEffect));
    if (!effect) {
        goto error;
    }

    effect->scaleToFit = scaleToFit;
    effect->count = count;

    effect->fIntervals = (SkScalar *)sk_malloc_throw(sizeof(SkScalar) * count);
    if (!effect->fIntervals) {
        goto error_free_effect;
    }

    memset(effect->fIntervals, 0, sizeof(SkScalar) * count);

    SkScalar len = 0;
    for (int i = 0; i < count; i++) {
        if (intervals[i] < 0) {
            goto error_free_intervals;
        }
        effect->fIntervals[i] = intervals[i];
        len += intervals[i];
    }

    effect->fIntervalLength = len;

    if (len > 0) {
        if (phase < 0) {
            phase = -phase;
            if (phase > len) {
                phase = fmod(phase, len);
            }
            phase = len - phase;
        }

        if (!isfinite(phase) || !isfinite(len)) {
            goto error_free_intervals;
        }

        int index = (int)floor(phase / effect->fIntervals[0]);
        if (index >= count) {
            goto error_free_intervals;
        }

        effect->fInitialDashLength = effect->fIntervals[index];
        effect->fInitialDashIndex = index;
    } else {
        goto error_free_intervals;
    }

    return effect;

error_free_intervals:
    free(effect->fIntervals);
error_free_effect:
    free(effect);
error:
    return NULL;
}
