#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define SECTION_SIZE 128

typedef struct {
    char name[64];
    void *ptr;
    size_t size;
    size_t offset;
    int index;
} section;

void validate_section(section *section) {
    if (!section || !section->name || !section->ptr || section->size <= 0 || section->offset <= 0) {
        return;
    }
}

int compare_sections(const void *a, const void *b) {
    const section *section_a = (const section *)a;
    const section *section_b = (const section *)b;

    if (section_a->index < section_b->index) {
        return -1;
    } else if (section_a->index > section_b->index) {
        return 1;
    } else {
        return strcmp(section_a->name, section_b->name);
    }
}

section *sort_sections(section *sections, size_t num_sections) {
    validate_section(sections);

    section *sorted_sections = malloc(num_sections * sizeof(section));
    if (!sorted_sections) {
        perror("malloc failure");
        return NULL;
    }

    memcpy(sorted_sections, sections, num_sections * sizeof(section));

    qsort(sorted_sections, num_sections, sizeof(section), compare_sections);

    free(sections);

    return sorted_sections;
}
