#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

struct pck_votos {
    char CURP[10];
    char celular[10];
    char partido[5];
};

int main(int argc, char *argv[]) {
    if (argc != 3) {
        printf("Usage: %s [IP_ADDRESS] [PORT]\n", argv[0]);
        exit(1);
    }

    int sockfd;
    struct sockaddr_in server_addr;
    struct pck_votos msg;
    struct pck_votos res;
    socklen_t addr_len = sizeof(server_addr);

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        exit(1);
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(atoi(argv[2]));
    inet_pton(AF_INET, argv[1], &server_addr.sin_addr);

    memset(&msg, 0, sizeof(msg));
    strcpy(msg.CURP, "0000000001");
    strcpy(msg.celular, "0000000001");
    strcpy(msg.partido, "PRD");

    if (sendto(sockfd, (char *)&msg, sizeof(msg), 0, (const struct sockaddr *)&server_addr, addr_len) < 0) {
        perror("sendto failed");
        close(sockfd);
        exit(1);
    }

    if (recvfrom(sockfd, (char *)&res, sizeof(res), 0, (struct sockaddr *)&server_addr, &addr_len) < 0) {
        perror("recvfrom failed");
        close(sockfd);
        exit(1);
    }

    printf("Received CURP: %s\n", res.CURP);
    printf("Received celular: %s\n", res.celular);
    printf("Received partido: %s\n", res.partido);

    close(sockfd);
    exit(0);
}
