#include <openssl/hmac.h>
#include <openssl/sha.h>
#include <string>
#include <iomanip>
#include <sstream>

std::string HexEncode(const unsigned char* data, size_t length) {
    std::ostringstream oss;
    for (size_t i = 0; i < length; ++i) {
        oss << std::hex << std::setw(2) << std::setfill('0') << static_cast<int>(data[i]);
    }
    return oss.str();
}

std::string CalculateSHA256HMAC(const std::string& message, const std::string& secret) {
    unsigned char digest[SHA256_DIGEST_LENGTH];
    unsigned int digestLength;

    HMAC(EVP_sha256(), secret.c_str(), secret.length(),
         reinterpret_cast<const unsigned char*>(message.c_str()), message.length(),
         digest, &digestLength);

    return HexEncode(digest, digestLength);
}
