#include <iostream>
#include <cstring>

float* computeDifferences(int lLBytes, int height) {
    // Allocate and initialize the 2D array
    float* array = new float[lLBytes * height];
    memset(array, 0, lLBytes * height * sizeof(float));

    // Allocate arrays for differences
    float* deltaN = new float[lLBytes * height];
    float* deltaS = new float[lLBytes * height];
    float* deltaW = new float[lLBytes * height];
    float* deltaE = new float[lLBytes * height];
    float* deltaNE = new float[lLBytes * height];
    float* deltaSE = new float[lLBytes * height];
    float* deltaSW = new float[lLBytes * height];
    float* deltaNW = new float[lLBytes * height];

    memset(deltaN, 0, lLBytes * height * sizeof(float));
    memset(deltaS, 0, lLBytes * height * sizeof(float));
    memset(deltaW, 0, lLBytes * height * sizeof(float));
    memset(deltaE, 0, lLBytes * height * sizeof(float));
    memset(deltaNE, 0, lLBytes * height * sizeof(float));
    memset(deltaSE, 0, lLBytes * height * sizeof(float));
    memset(deltaSW, 0, lLBytes * height * sizeof(float));
    memset(deltaNW, 0, lLBytes * height * sizeof(float));

    // Compute differences
    for (int y = 0; y < height; ++y) {
        for (int x = 0; x < lLBytes; ++x) {
            int index = y * lLBytes + x;

            // North
            if (y > 0) {
                deltaN[index] = array[index] - array[(y - 1) * lLBytes + x];
            }
            // South
            if (y < height - 1) {
                deltaS[index] = array[(y + 1) * lLBytes + x] - array[index];
            }
            // West
            if (x > 0) {
                deltaW[index] = array[index] - array[y * lLBytes + (x - 1)];
            }
            // East
            if (x < lLBytes - 1) {
                deltaE[index] = array[y * lLBytes + (x + 1)] - array[index];
            }
            // North-East
            if (y > 0 && x < lLBytes - 1) {
                deltaNE[index] = array[(y - 1) * lLBytes + (x + 1)] - array[index];
            }
            // South-East
            if (y < height - 1 && x < lLBytes - 1) {
                deltaSE[index] = array[(y + 1) * lLBytes + (x + 1)] - array[index];
            }
            // South-West
            if (y < height - 1 && x > 0) {
                deltaSW[index] = array[(y + 1) * lLBytes + (x - 1)] - array[index];
            }
            // North-West
            if (y > 0 && x > 0) {
                deltaNW[index] = array[(y - 1) * lLBytes + (x - 1)] - array[index];
            }
        }
    }

    // Clean up allocated difference arrays if needed
    delete[] deltaN;
    delete[] deltaS;
    delete[] deltaW;
    delete[] deltaE;
    delete[] deltaNE;
    delete[] deltaSE;
    delete[] deltaSW;
    delete[] deltaNW;

    return array;
}
