void linearRegression(const std::vector<DataPoint>& data, double& slope, double& intercept) {
    double sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0;
    int n = data.size();

    for (const auto& point : data) {
        sumX += point.x;
        sumY += point.y;
        sumXY += point.x * point.y;
        sumX2 += point.x * point.x;
    }

    slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);
    intercept = (sumY - slope * sumX) / n;
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <datafile>" << std::endl;
        return 1;
    }

    std::ifstream file(argv[1]);
    if (!file.is_open()) {
        std::cerr << "Error opening file: " << argv[1] << std::endl;
        return 1;
    }

    std::vector<DataPoint> data;
    double x, y;
    while (file >> x >> y) {
        data.push_back({x, y});
    }
    file.close();

    int numPoints = data.size();
    std::cout << "Number of data points: " << numPoints << std::endl;

    if (numPoints < 2) {
        std::cerr << "Not enough data points for linear regression." << std::endl;
        return 1;
    }

