#include <vector>

struct Vertex {
    float x, y, z;
};

struct Mesh {
    std::vector<Vertex> vertices;
    std::vector<unsigned int> indices;

    Mesh(std::initializer_list<Vertex> vertices_init, std::initializer_list<unsigned int> indices_init) : vertices(vertices_init), indices(indices_init) {}

    Mesh(const Mesh& other) {
        vertices = other.vertices;
        indices = other.indices;
    }

    Mesh& operator=(Mesh other) {
        swap(vertices, other.vertices);
        swap(indices, other.indices);
        return *this;
    }

    Mesh deepCopy() const {
        Mesh copied(*this);
        return copied;
    }
};

Mesh Mesh::deepCopy() const {
    Mesh copied(*this);
    return copied;
}

Mesh createDeepCopy(const Mesh& mesh) {
    Mesh copied = mesh.deepCopy();
    return copied;
}
