OSStatus InitializeAudioUnit(CFMutableRef inRef, Float64 inSampleRate) {
    OSStatus status = kAudioUnitErr_InvalidProperty;

    // Initialize the audio unit
    AudioComponentDescription desc;
    desc.componentType = kAudioUnitType_Effect;
    desc.componentSubType = kAudioUnitSubType_StereoRoom;
    desc.componentManufacturer = kAudioUnitManufacturer_Apple;
    desc.componentFlags = 0;
    desc.componentFlagsMask = 0;

    AudioComponent instance = AudioComponentFindNext(NULL, &desc);
    if (instance) {
        status = AudioComponentInstanceNew(instance, &fAudioUnit);
        if (status == noErr) {
            status = AudioUnitSetProperty(fAudioUnit, kAudioUnitProperty_CocoaEventConnectionEnable, 0, kCFBooleanTrue, sizeof(Boolean));
            if (status == noErr) {
                // Calculate the buffer size
                UInt32 bufferSize = static_cast<UInt32>(inSampleRate * kBufferSize_Seconds);

                // Allocate memory for the buffer
                fBuffer = static_cast<Float32*>(malloc(bufferSize * 2 * sizeof(Float32))); // Stereo processing
                if (fBuffer) {
                    // Set up the audio stream format
                    AudioStreamBasicDescription format;
                    format.mSampleRate = inSampleRate;
                    format.mFormatID = kAudioFormatLinearPCM;
                    format.mChannelsPerFrame = 2;
                    format.mBytesPerFrame = sizeof(Float32) * format.mChannelsPerFrame;
                    format.mFramesPerPacket = 1;
                    format.mBytesPerPacket = format.mFramesPerPacket * format.mBytesPerFrame;
                    format.mNumberChannels = format.mChannelsPerFrame;
                    format.mDataFormat = kAudioFormatLinearPCM;
                    format.mBitsPerChannel = 32;
                    format.mReserved = 0;

                    status = AudioUnitSetProperty(fAudioUnit, kAudioUnitProperty_StreamFormat, 0, &format, sizeof(format));
                    if (status == noErr) {
