#include <stdio.h>
#include <stdlib.h>
#include <wchar.h>
#include <locale.h>

wchar_t *ReadFileAsUnicode(const char *filename)
{
    FILE *finput;
    long filesize;
    wchar_t *buffer;
    size_t num;

    setlocale(LC_ALL, ""); // Set locale for wide character support

    if ((finput = fopen(filename, "r, ccs=UTF-8")) == NULL) {
        fprintf(stderr, "Error: Cannot open file %s\n", filename);
        return NULL;
    }

    if (fseek(finput, 0, SEEK_END) != 0 || (filesize = ftell(finput)) < 0 || fseek(finput, 0, SEEK_SET) != 0) {
        fprintf(stderr, "Error: File error in file %s\n", filename);
        fclose(finput);
        return NULL;
    }

    buffer = malloc((filesize + 1) * sizeof(wchar_t));
    if (buffer == NULL) {
        fprintf(stderr, "Error: Error allocating %ld bytes of memory\n", filesize + 1);
        fclose(finput);
        return NULL;
    }

    num = fread(buffer, sizeof(wchar_t), filesize / sizeof(wchar_t), finput);
    if (ferror(finput)) {
        fprintf(stderr, "Error: Error reading file %s\n", filename);
        free(buffer);
        fclose(finput);
        return NULL;
    }

    buffer[num] = L'\0'; // Null-terminate the wide string
    fclose(finput);
    return buffer;
}
