#define BUFFER_SIZE 1024

void BREPLYX(int socket, const char *reply) {
    send(socket, reply, strlen(reply), 0);
}

void handle_message(int client_socket) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);

    if (bytes_received < 0) {
        perror("recv failed");
        return;
    }

    buffer[bytes_received] = '\0'; // Null-terminate the received message

    // Extract user ID from the message (assuming it's in the format "userid@=12345/")
    char *user_id_start = strstr(buffer, "userid@=");
    char user_id[50];
    if (user_id_start) {
        sscanf(user_id_start, "userid@=%49[^/]", user_id);
    } else {
        strcpy(user_id, "unknown");
    }

    // Prepare the reply message
    char reply[BUFFER_SIZE];
    snprintf(reply, sizeof(reply), "Hello user %s, your message was received!", user_id);

    // Send the reply back to the sender
    BREPLYX(client_socket, reply);
}

