#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAX_NODES 100

typedef struct {
    int *nodes;
    int size;
} Path;

Path* bfs_shortest_path(int **adj_matrix, int num_nodes, int start, int end) {
    bool visited[MAX_NODES] = {false};
    int parent[MAX_NODES];
    int queue[MAX_NODES];
    int front = 0, rear = 0;

    for (int i = 0; i < num_nodes; i++) {
        parent[i] = -1;
    }

    visited[start] = true;
    queue[rear++] = start;

    while (front < rear) {
        int current = queue[front++];

        if (current == end) {
            Path *path = (Path *)malloc(sizeof(Path));
            path->nodes = (int *)malloc(MAX_NODES * sizeof(int));
            path->size = 0;

            for (int at = end; at != -1; at = parent[at]) {
                path->nodes[path->size++] = at;
            }

            // Reverse the path
            for (int i = 0; i < path->size / 2; i++) {
                int temp = path->nodes[i];
                path->nodes[i] = path->nodes[path->size - 1 - i];
                path->nodes[path->size - 1 - i] = temp;
            }

            return path;
        }

        for (int i = 0; i < num_nodes; i++) {
            if (adj_matrix[current][i] == 1 && !visited[i]) {
                visited[i] = true;
                parent[i] = current;
                queue[rear++] = i;
            }
        }
    }

    return NULL; // No path found
}

int main() {
