#include <flann/flann.hpp>
#include <vector>

int kNearestNeighborsWithinRadius(const std::vector<std::vector<float>>& points, 
                                   const std::vector<float>& query_point, 
                                   float radius) {
    // Create a FLANN index for the 3D points
    flann::Matrix<float> dataset(new float[points.size() * 3], points.size(), 3);
    for (size_t i = 0; i < points.size(); ++i) {
        dataset[i][0] = points[i][0];
        dataset[i][1] = points[i][1];
        dataset[i][2] = points[i][2];
    }

    flann::Index<flann::L2<float>> index(dataset, flann::KDTreeIndexParams(4));
    index.buildIndex();

    // Prepare the query point
    flann::Matrix<float> query(new float[3], 1, 3);
    query[0][0] = query_point[0];
    query[0][1] = query_point[1];
    query[0][2] = query_point[2];

    // Prepare the output for indices and distances
    const int max_nn = 1000;
    flann::Matrix<int> indices(new int[max_nn], 1, max_nn);
    flann::Matrix<float> dists(new float[max_nn], 1, max_nn);

    // Perform radius search
    int num_neighbors = index.radiusSearch(query, indices, dists, radius * radius, flann::SearchParams(128));

    // Clean up
    delete[] dataset.ptr();
    delete[] indices.ptr();
    delete[] dists.ptr();

    return num_neighbors;
}
