#include <stdio.h>
#include <string.h>

#define ALPHABET_SIZE 26
#define MAX_N 1000

typedef struct TrieNode {
    struct TrieNode *children[ALPHABET_SIZE];
    int count;
} TrieNode;

TrieNode nodes[MAX_N];
int nodeCount = 0;

TrieNode* createNode() {
    TrieNode *newNode = &nodes[nodeCount++];
    newNode->count = 0;
    for (int i = 0; i < ALPHABET_SIZE; i++) {
        newNode->children[i] = NULL;
    }
    return newNode;
}

void insert(TrieNode *root, const char *str) {
    while (*str) {
        int index = *str - 'a';
        if (root->children[index] == NULL) {
            root->children[index] = createNode();
        }
        root = root->children[index];
        root->count++;
        str++;
    }
}

void countOccurrences(TrieNode *root, int *occurrences) {
    for (int i = 0; i < ALPHABET_SIZE; i++) {
        if (root->children[i] != NULL) {
            occurrences[i] += root->children[i]->count;
            countOccurrences(root->children[i], occurrences);
        }
    }
}

int* countCharacterOccurrences(const char *str) {
    TrieNode *root = createNode();
    insert(root, str);

    static int occurrences[ALPHABET_SIZE] = {0};
    countOccurrences(root, occurrences);

    return occurrences;
}

int main() {
    char input[MAX_N];
    scanf("%s", input);

    int *occurrences = countCharacterOccurrences(input);

    for (int i = 0; i < ALPHABET_SIZE; i++) {
        if (occurrences[i] > 0) {
            printf("%c: %d\n", 'a' + i, occurrences[i]);
        }
    }

    return 0;
}
