#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <ctype.h>

char* trim_whitespace(const char* str) {
    while (isspace((unsigned char)*str)) str++;
    if (*str == 0) return strdup(""); // Return empty string if only whitespace

    const char* end = str + strlen(str) - 1;
    while (end > str && isspace((unsigned char)*end)) end--;

    size_t len = end - str + 1;
    char* trimmed = (char*)malloc(len + 1);
    if (trimmed) {
        strncpy(trimmed, str, len);
        trimmed[len] = '\0';
    }
    return trimmed;
}

int parse_name_value(const char* input, char** name, char** value) {
    if (!input) return 0;

    const char* colon = strchr(input, ':');
    if (!colon) return 0;

    *name = trim_whitespace(input);
    if (!*name) return 0;

    *value = trim_whitespace(colon + 1);
    if (!*value) {
        free(*name);
        return 0;
    }

    return 1;
}

int main() {
    const char* input = "   name:   value   ";
    char* name = NULL;
    char* value = NULL;

    if (parse_name_value(input, &name, &value)) {
        printf("Name: '%s', Value: '%s'\n", name, value);
        free(name);
        free(value);
    } else {
        printf("Invalid input format.\n");
    }

    return 0;
}
