#include <windows.h>
#include <memory>
#include <stdexcept>

class Thread
{
public:
    // Constructor.
    template <typename Function>
    Thread(Function f, void* arg = nullptr)
    {
        using func_type = void(*)(void*);
        auto func = [](void* arg) {
            auto f = static_cast<func_type>(arg);
            f(arg);
        };

        std::unique_ptr<func_type> func_ptr(new func_type(f));
        DWORD thread_id = 0;
        HANDLE thread_handle = ::CreateThread(
            nullptr,          // default security attributes
            0,               // default stack size
            func,           // thread function
            func_ptr.get(), // argument to thread function
            0,               // default creation flags
            &thread_id);     // receive thread identifier

        if (!thread_handle)
        {
            DWORD last_error = ::GetLastError();
            throw std::runtime_error("Failed to create thread: " + std::to_string(last_error));
        }

        // Detach the thread handle to avoid resource leaks
        ::CloseHandle(thread_handle);
        thread_id_ = thread_id;
    }

    DWORD get_thread_id() const
    {
        return thread_id_;
    }

private:
    DWORD thread_id_;
};
