#include <iostream>
#include <vector>
#include <random>
#include <memory>

enum class InputType {
    Dense,
    Sparse,
    Sequence
};

template<typename T>
class Matrix {
public:
    Matrix(int rows, int cols) : rows(rows), cols(cols) {
        data = std::make_unique<T[]>(rows * cols);
    }

    T& operator()(int row, int col) {
        return data[row * cols + col];
    }

    void print() {
        for (int i = 0; i < rows; ++i) {
            for (int j = 0; j < cols; ++j) {
                std::cout << (*this)(i, j) << " ";
            }
            std::cout << std::endl;
        }
    }

private:
    int rows, cols;
    std::unique_ptr<T[]> data;
};

template<typename T>
Matrix<T> createRandomMatrix(int rows, int cols, InputType type) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<T> dist(0, 1);

    Matrix<T> matrix(rows, cols);

    switch (type) {
        case InputType::Dense:
            for (int i = 0; i < rows; ++i) {
                for (int j = 0; j < cols; ++j) {
                    matrix(i, j) = dist(gen);
                }
            }
            break;

        case InputType::Sparse:
            for (int i = 0; i < rows; ++i) {
                for (int j = 0; j < cols; ++j) {
                    if (dist(gen) > 0.7) { // 30% chance to be non-zero
                        matrix(i, j) = dist(gen);
                    } else {
                        matrix(i, j) = 0;
                    }
                }
            }
            break;

        case InputType::Sequence:
            for (int i = 0; i < rows; ++i) {
                for (int j = 0; j < cols; ++j) {
                    matrix(i, j) = static_cast<T>(i + j); // Simple sequence
                }
            }
            break;
    }

    return matrix;
}

int main() {
    int rows = 5;
    int cols = 5;

    auto denseMatrix = createRandomMatrix<float>(rows, cols, InputType::Dense);
    std::cout << "Dense Matrix:\n";
    denseMatrix.print();

    auto sparseMatrix = createRandomMatrix<float>(rows, cols, InputType::Sparse);
    std::cout << "\nSparse Matrix:\n";
    sparseMatrix.print();

    auto sequenceMatrix = createRandomMatrix<float>(rows, cols, InputType::Sequence);
    std::cout << "\nSequence Matrix:\n";
    sequenceMatrix.print();

    return 0;
}
