			char c;
			while (sleep_and_input(&c))
			{
				if (c == 27)
				{
					// escape code, read another character
#ifdef _WIN32
					c = _getch();
#else
					c = getc(stdin);
#endif
					if (c != '[') break;
#ifdef _WIN32
					c = _getch();
#else
					c = getc(stdin);
#endif
					if (c == 65)
					{
						// arrow up
						--active_torrent;
						if (active_torrent < 0) active_torrent = 0;
					}
					else if (c == 66)
					{
