#include <stdio.h>

void topic_modeling(double **wp, double **dp, int W, int D, int T, double ***probs, int **sumdp, int **ztot) {
    int i, j;

    // Allocate memory for output matrices
    *probs = (double **)malloc(W * sizeof(double *));
    for (i = 0; i < W; i++) {
        (*probs)[i] = (double *)malloc((T + 1) * sizeof(double));
    }

    *sumdp = (int *)malloc(D * sizeof(int));
    *ztot = (int *)malloc((T + 1) * sizeof(int));

    // Initialize sumdp and ztot
    for (i = 0; i < D; i++) {
        (*sumdp)[i] = 0;
    }
    for (i = 0; i < (T + 1); i++) {
        (*ztot)[i] = 0;
    }

    // Calculate topic probabilities for each word
    for (i = 0; i < W; i++) {
        double total = 0.0;
        for (j = 0; j < T; j++) {
            (*probs)[i][j] = wp[i][j] / (dp[j][i] + 1e-10); // Avoid division by zero
            total += (*probs)[i][j];
        }
        // Normalize probabilities
        for (j = 0; j < T; j++) {
            (*probs)[i][j] /= total;
        }
        (*probs)[i][T] = total; // Store total probability in last column
    }

    // Calculate sum of topic probabilities for each document
    for (i = 0; i < D; i++) {
        for (j = 0; j < T; j++) {
            (*sumdp)[i] += dp[i][j];
        }
    }

    // Calculate total number of words in each topic
    for (i = 0; i < T; i++) {
        for (j = 0; j < D; j++) {
            (*ztot)[i] += dp[j][i];
        }
    }
}
