#include <vector>
#include <stdexcept>

std::vector<std::vector<double>> addBorderValue(const std::vector<std::vector<double>>& input, double borderValue) {
    if (input.empty() || input[0].empty()) {
        throw std::invalid_argument("Input array must not be empty.");
    }

    size_t rows = input.size();
    size_t cols = input[0].size();
    std::vector<std::vector<double>> output(rows, std::vector<double>(cols));

    for (size_t i = 0; i < rows; ++i) {
        for (size_t j = 0; j < cols; ++j) {
            output[i][j] = input[i][j] + borderValue;
        }
    }

    // Special case for border value being zero
    if (borderValue == 0) {
        // If border value is zero, we can return the original array
        return input;
    }

    return output;
}
