#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

using uchar = unsigned char;

std::vector<std::vector<uchar>> gaussian_filter(const std::vector<std::vector<uchar>>& image, 
                                                int width, int height, 
                                                const std::vector<std::vector<float>>& kernel, 
                                                int kernel_size) {
    int offset = kernel_size / 2;
    std::vector<std::vector<uchar>> output(height, std::vector<uchar>(width, 0));

    for (int y = 0; y < height; ++y) {
        for (int x = 0; x < width; ++x) {
            float sum = 0.0f;
            for (int ky = -offset; ky <= offset; ++ky) {
                for (int kx = -offset; kx <= offset; ++kx) {
                    int pixel_y = std::clamp(y + ky, 0, height - 1);
                    int pixel_x = std::clamp(x + kx, 0, width - 1);
                    sum += image[pixel_y][pixel_x] * kernel[ky + offset][kx + offset];
                }
            }
            output[y][x] = static_cast<uchar>(std::clamp(sum, 0.0f, 255.0f));
        }
    }
    return output;
}

int main() {
    // Example usage
    const int width = 5;
    const int height = 5;
    std::vector<std::vector<uchar>> image = {
        { 255, 255, 255, 255, 255 },
        { 255, 0, 0, 0, 255 },
        { 255, 0, 0, 0, 255 },
        { 255, 0, 0, 0, 255 },
        { 255, 255, 255, 255, 255 }
    };

    std::vector<std::vector<float>> kernel = {
        { 0.057118f, 0.124758f, 0.057118f },
        { 0.124758f, 0.272496f, 0.124758f },
        { 0.057118f, 0.124758f, 0.057118f }
    };

    std::vector<std::vector<uchar>> filtered_image = gaussian_filter(image, width, height, kernel, 3);

    // Output the filtered image
    for (const auto& row : filtered_image) {
        for (const auto& pixel : row) {
            std::cout << static_cast<int>(pixel) << " ";
        }
        std::cout << std::endl;
    }

    return 0;
}
