#include <stdexcept>
#include <memory>
#include <type_traits>

template <typename... T>
class variant {
public:
    variant() : data_(nullptr), type_index_(-1) {}

    variant& operator=(variant&& rhs) {
        delete_if_not_empty();
        data_ = rhs.data_;
        type_index_ = rhs.type_index_;
        rhs.data_ = nullptr;
        return *this;
    }

    template <class V>
    variant& operator=(std::auto_ptr<V>& rhs) {
        int const new_index = meta::index_of<V, T...>::value;
        static_assert(new_index < sizeof...(T), "type does not exist in variant");
        delete_if_not_empty();
        type_index_ = new_index;
        data_ = rhs.release();
        return *this;
    }

    template <class V>
    variant& operator=(V&& value) {
        using ValueType = std::decay_t<V>;
        int const new_index = meta::index_of<ValueType, T...>::value;
        if constexpr (new_index < sizeof...(T)) {
            delete_if_not_empty();
            type_index_ = new_index;
            data_ = new ValueType(std::forward<V>(value));
        } else {
            throw std::invalid_argument("type not supported by variant");
        }
        return *this;
    }

    ~variant() {
        delete_if_not_empty();
    }

private:
    void delete_if_not_empty() {
        if (data_) {
            delete data_;
            data_ = nullptr;
            type_index_ = -1;
        }
    }

    void* data_;
    int type_index_;

    // Meta-programming utility to find index of type
    template <typename U, typename... Args>
    struct index_of;

    template <typename U, typename First, typename... Rest>
    struct index_of<U, First, Rest...> {
        static const int value = std::is_same<U, First>::value ? 0 : 1 + index_of<U, Rest...>::value;
    };

    template <typename U>
    struct index_of<U> {
        static const int value = -1; // Type not found
    };
};
