#include <vector>
#include <algorithm>
#include <unordered_map>

template <typename T>
class DisjointSetUnion {
public:
    DisjointSetUnion(const std::vector<T>& elements) {
        for (const auto& element : elements) {
            parent[element] = element;
        }
    }

    T find(T x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]); // Path compression
        }
        return parent[x];
    }

    void unite(T x, T y) {
        T rootX = find(x);
        T rootY = find(y);
        if (rootX != rootY) {
            parent[rootY] = rootX; // Union
        }
    }

private:
    std::unordered_map<T, T> parent;
};

bool areConnected(const std::vector<int>& xs, const std::vector<int>& ys) {
    if (xs.size() != ys.size()) return false;

    DisjointSetUnion<int> dsu(xs);

    for (size_t i = 0; i < xs.size(); ++i) {
        dsu.unite(xs[i], ys[i]);
    }

    for (size_t i = 1; i < xs.size(); ++i) {
        if (dsu.find(xs[0]) != dsu.find(xs[i])) {
            return false;
        }
    }
    return true;
}
