#define MAX_CONTENT_SIZE 1024

void update_max_value(const char *index_filename, int *max_value) {
    FILE *fp;
    char content[MAX_CONTENT_SIZE];
    int piece_count = 0;

    fp = fopen(index_filename, "r");
    if (fp == NULL) {
        return; // File not present or error occurred
    }

    // Read and concatenate the contents of the file
    size_t total_read = 0;
    while (fgets(content + total_read, MAX_CONTENT_SIZE - total_read, fp) != NULL) {
        total_read += strlen(content + total_read);
        if (total_read >= MAX_CONTENT_SIZE - 1) {
            break; // Prevent buffer overflow
        }
    }
    fclose(fp);

    // Count the number of pieces in the content
    char *line = strtok(content, "\n");
    while (line != NULL) {
        piece_count++;
        line = strtok(NULL, "\n");
    }

    // Update the maximum value based on the number of pieces
    *max_value = piece_count;
