class LinearSolverInterface {
public:
    virtual void Solve(const std::vector<std::vector<double>>& matrix, 
                       const std::vector<double>& rhs, 
                       std::vector<double>& solution) = 0;
};

void SolveLinearSystem(const std::vector<std::vector<double>>& matrix, 
                       const std::vector<double>& rhs, 
                       LinearSolverInterface& solver, 
                       const std::vector<double>& scaling_factors, 
                       bool use_scaling) {
    size_t dim = matrix.size();
    std::vector<double> scaled_rhs(rhs.size());

    // Scale the right-hand side if required
    if (use_scaling) {
        auto start = std::chrono::high_resolution_clock::now();
        for (size_t i = 0; i < rhs.size(); ++i) {
            scaled_rhs[i] = rhs[i];
            for (size_t j = 0; j < dim; ++j) {
                scaled_rhs[i] *= scaling_factors[j];
            }
        }
        auto end = std::chrono::high_resolution_clock::now();
        std::chrono::duration<double> elapsed = end - start;
        // Here you can log the elapsed time for scaling if needed
    } else {
        scaled_rhs = rhs;
    }

    // Solve the system using the provided linear solver
    std::vector<double> solution(dim);
    solver.Solve(matrix, scaled_rhs, solution);
}
