#include <arpa/inet.h>
#include <errno.h>
#include <netinet/in.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <unistd.h>

#define PORT 5039
#define MAX_MESSAGE_LENGTH 200

int main() {
    int client_socket = -1;
    struct sockaddr_in server_addr;

    // Initialize socket descriptor to an invalid value
    client_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (client_socket == -1) {
        perror("socket create failed: ");
        exit(EXIT_FAILURE);
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);

    // Validate and sanitize server address
    if (inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr) <= 0) {
        perror("invalid address/address not supported");
        exit(EXIT_FAILURE);
    }

    if (connect(client_socket, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("connection failed: ");
        close(client_socket);
        exit(EXIT_FAILURE);
    }

    printf("connection established.\n");

    char message[MAX_MESSAGE_LENGTH];
    while (1) {
        printf("enter message (or 'exit' to quit): ");
        fgets(message, MAX_MESSAGE_LENGTH, stdin);

        size_t message_len = strlen(message);
        if (strncmp(message, "exit\n", 5) == 0) {
            break;
        }

        if (send(client_socket, message, message_len, 0) < 0) {
            perror("send failed: ");
            close(client_socket);
            exit(EXIT_FAILURE);
        }

        memset(message, 0, MAX_MESSAGE_LENGTH);
        ssize_t bytes_received = recv(client_socket, message, MAX_MESSAGE_LENGTH, 0);
        if (bytes_received <= 0) {
            if (bytes_received < 0) {
                perror("recv failed: ");
            }
            close(client_socket);
            exit(EXIT_FAILURE);
        }

        printf("message received: %s\n", message);
    }

    close(client_socket);

    return EXIT_SUCCESS;
}
