struct MemoryBlock {
    uint64_t start_offset;
    uint64_t size;
};

bool canAllocateMemoryBlock(const std::vector<MemoryBlock>& existing_blocks, 
                            uint64_t new_block_start, 
                            uint64_t new_block_size) {
    // Check for valid allocation size
    if (new_block_size == 0) {
        return false;
    }

    uint64_t new_block_end = new_block_start + new_block_size;

    for (const auto& block : existing_blocks) {
        uint64_t block_start = block.start_offset;
        uint64_t block_end = block.start_offset + block.size;

        // Check for overlap
        if (new_block_start < block_end && new_block_end > block_start) {
            return false; // Overlap detected
        }
    }

    return true; // No overlap, allocation is possible
}
