#include <map>
#include <vector>
#include <algorithm>

std::vector<int> sortOutputCounts(const std::map<int, int>& outputStats, const std::vector<int>& outputCounts) {
    std::vector<std::pair<int, int>> countPairs;

    for (const auto& count : outputCounts) {
        auto it = outputStats.find(count);
        if (it != outputStats.end()) {
            countPairs.emplace_back(it->second, count);
        }
    }

    std::sort(countPairs.begin(), countPairs.end(), [](const auto& a, const auto& b) {
        if (a.first == b.first) {
            return a.second < b.second; // Sort by count value first, then by output count
        }
        return a.first > b.first; // Sort by value in descending order
    });

    std::vector<int> sortedOutputCounts;
    for (const auto& pair : countPairs) {
        sortedOutputCounts.push_back(pair.second);
    }

    return sortedOutputCounts;
}
