public class RandomListSorter
{
    private static readonly Random Random = new Random();

    public static void GenerateAndTestRandomList()
    {
        const int MaxNumberOfElements = 1000;
        var numberOfElements = Random.Next(0, MaxNumberOfElements + 1);

        List<int> originalElements = new List<int>(numberOfElements);

        for (int j = 0; j < numberOfElements; j++)
        {
            originalElements.Add(Random.Next(int.MinValue, int.MaxValue));
        }

        var shuffledElements = originalElements.OrderBy(x => Random.Next()).ToList();
