using System;

public class DisplacementFieldGenerator
{
    private static Random randomizer = new Random();

    public static double[,] GenerateRandomDisplacementField(int width, int height, int stepSize)
    {
        double[,] displacementField = new double[width, height];

        for (int x = 0; x < width; x += stepSize)
        {
            for (int y = 0; y < height; y += stepSize)
            {
                double diffX = GenerateGaussianRandom();
                double diffY = GenerateGaussianRandom();
                displacementField[x, y] = Math.Sqrt(diffX * diffX + diffY * diffY);
            }
        }

        return displacementField;
    }

    private static double GenerateGaussianRandom()
    {
        double u1 = randomizer.NextDouble();
        double u2 = randomizer.NextDouble();
        double z0 = Math.Sqrt(-2.0 * Math.Log(u1)) * Math.Cos(2.0 * Math.PI * u2);
        return z0;
    }
}
