using System;

public static class MatrixGenerator
{
    public static T[,] CreateRandomMatrix<T>(int rows, int columns, T minValue, T maxValue) where T : struct
    {
        var rand = new Random();
        var matrix = new T[rows, columns];

        for (int i = 0; i < rows; i++)
        {
            for (int j = 0; j < columns; j++)
            {
                matrix[i, j] = GenerateRandomValue(rand, minValue, maxValue);
            }
        }

        return matrix;
    }

    private static T GenerateRandomValue<T>(Random rand, T minValue, T maxValue) where T : struct
    {
        if (typeof(T) == typeof(int))
        {
            return (T)(object)rand.Next(Convert.ToInt32(minValue), Convert.ToInt32(maxValue));
        }
        else if (typeof(T) == typeof(float))
        {
            return (T)(object)(rand.NextDouble() * (Convert.ToSingle(maxValue) - Convert.ToSingle(minValue)) + Convert.ToSingle(minValue));
        }
        else if (typeof(T) == typeof(double))
        {
            return (T)(object)(rand.NextDouble() * (Convert.ToDouble(maxValue) - Convert.ToDouble(minValue)) + Convert.ToDouble(minValue));
        }
        else if (typeof(T) == typeof(byte))
        {
            return (T)(object)(byte)rand.Next(Convert.ToInt32(minValue), Convert.ToInt32(maxValue));
        }
        else if (typeof(T) == typeof(short))
        {
            return (T)(object)(short)rand.Next(Convert.ToInt32(minValue), Convert.ToInt32(maxValue));
        }
        else if (typeof(T) == typeof(long))
        {
            return (T)(object)((long)rand.Next() * (Convert.ToInt64(maxValue) - Convert.ToInt64(minValue)) / int.MaxValue + Convert.ToInt64(minValue));
        }
        else
        {
            throw new NotSupportedException($"Type {typeof(T)} is not supported.");
        }
    }
}
