private void Create3DTree(int x, int y, int z)
{
    Random random = new Random();
    int trunkLength = random.Next(5, 10);

    // Create the trunk
    for (int yy = y; yy < y + trunkLength; yy++)
    {
        if (IsBlockEmpty(x, yy, z))
        {
            mWorldRef.SetBlock(x, yy, z, new Block(BlockType.Log));
        }
