        int branchLength = random.Next(2, 5);
        int direction = random.Next(0, 4); // 0: North, 1: East, 2: South, 3: West

        int branchX = x;
        int branchZ = z;

        switch (direction)
        {
            case 0: branchZ -= 1; break; // North
            case 1: branchX += 1; break; // East
            case 2: branchZ += 1; break; // South
            case 3: branchX -= 1; break; // West
