public class Program
{
    public static void Main(string[] args)
    {
        string keyFilePath = "path/to/your/keyfile"; // Replace with your key file path
        string command = "yourCommand"; // Replace with your command
        string arguments = string.Format("{0} {1}", command, keyFilePath);

