public boolean addTown(String townName) {
    Connection connection = null;
    PreparedStatement ps = null;
    ResultSet rs = null;
    int lastInsertedId = 0;

    try {
        connection = DriverManager.getConnection("jdbc:your_database_url", "username", "password");
        connection.setAutoCommit(false);

        ps = connection.prepareStatement("INSERT INTO Towns(name) VALUES(?);", Statement.RETURN_GENERATED_KEYS);
        ps.setString(1, townName);
        ps.executeUpdate();

        rs = ps.getGeneratedKeys();
        if (rs.next()) {
            lastInsertedId = rs.getInt(1);
        }

        connection.commit();
        return lastInsertedId > 0;
    } catch (Exception e) {
        if (connection != null) {
            try {
                connection.rollback();
            } catch (SQLException rollbackEx) {
                rollbackEx.printStackTrace();
            }
        }
        e.printStackTrace();
        return false;
    } finally {
        try {
            if (rs != null) rs.close();
            if (ps != null) ps.close();
            if (connection != null) connection.close();
        } catch (SQLException closeEx) {
            closeEx.printStackTrace();
        }
    }
}
