using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public static class CryptoHelper
{
    public static string Decrypt(string encryptedMessage, string key)
    {
        try
        {
            key = key.Length >= 8 ? key.Substring(0, 8) : key.PadRight(8, ' ');
            byte[] keyBytes = Encoding.UTF8.GetBytes(key);
            byte[] iv = new byte[8]; // Initialization vector
            byte[] buffer = Convert.FromBase64String(encryptedMessage);

            using (DESCryptoServiceProvider provider = new DESCryptoServiceProvider())
            {
                using (MemoryStream memoryStream = new MemoryStream())
                {
                    using (CryptoStream cryptoStream = new CryptoStream(memoryStream, provider.CreateDecryptor(keyBytes, iv), CryptoStreamMode.Write))
                    {
                        cryptoStream.Write(buffer, 0, buffer.Length);
                        cryptoStream.FlushFinalBlock();
                        return Encoding.UTF8.GetString(memoryStream.ToArray());
                    }
                }
            }
        }
        catch
        {
            return "";
        }
    }
}
