using Microsoft.AspNetCore.Mvc;
using System.Collections.Generic;

public class CacheController : ControllerBase
{
    private readonly IDictionary<string, string> _cache = new Dictionary<string, string>();

    [HttpPost]
    [HttpPut]
    [HttpDelete]
    public ActionResult ProcessRequest(string method, string key, string data = null)
    {
        switch (method.ToUpper())
        {
            case "POST":
                if (data != null)
                {
                    _cache[key] = data;
                    return Ok("Data added to cache.");
                }
                return BadRequest("Data is required for POST.");

            case "PUT":
                if (_cache.ContainsKey(key))
                {
                    _cache[key] = data;
                    return Ok("Data updated in cache.");
                }
                return NotFound("Key not found in cache.");

            case "DELETE":
                if (_cache.Remove(key))
                {
                    return Ok("Data removed from cache.");
                }
                return NotFound("Key not found in cache.");

            default:
                return BadRequest("Invalid HTTP method.");
        }
    }
}
