using System;
using System.Linq;
using System.Net.NetworkInformation;

public class Project
{
    public string StartupFile { get; set; }
}

public class StartupFileHelper
{
    public static string GetStartupFilePath(Project project)
    {
        if (!string.IsNullOrEmpty(project.StartupFile))
        {
            return project.StartupFile;
        }

        int port = GetFreePort();
        return $"{project.StartupFile}?port={port}";
    }

    private static int GetFreePort()
    {
        var random = new Random();
        var availablePorts = Enumerable.Range(1200, 58801).ToList();
        var usedPorts = IPGlobalProperties.GetIPGlobalProperties().GetActiveTcpConnections()
            .Select(connection => connection.LocalEndPoint.Port);

        var freePort = availablePorts.Except(usedPorts).FirstOrDefault(port => port > 0);
        return freePort != 0 ? freePort : random.Next(1200, 60001);
    }
}
