internal void RetrieveVillainMinions(string connectionString) // Retrieve Villain Names and Minions Count
{
    using (var connection = new SqlConnection(connectionString))
    {
        connection.Open();
        var cmdText = "SELECT v.Name AS [Villain Name], COUNT(m.Id) AS [Number of Minions] " +
                      "FROM Villains v " +
                      "LEFT JOIN Minions m ON v.Id = m.VillainId " +
                      "GROUP BY v.Name";
        using (var command = new SqlCommand(cmdText, connection))
        {
            using (var reader = command.ExecuteReader())
            {
                if (reader.HasRows)
                {
                    while (reader.Read())
                    {
                        Console.WriteLine($"{reader["Villain Name"]} - {reader["Number of Minions"]}");
                    }
                }
            }
        }
    }
}
