using UnityEngine;

public class CubeSpawner : MonoBehaviour
{
    public GameObject cubePrefab;
    public float spawnRate = 1.0f; // Time in seconds between spawns
    public Vector3 spawnRange = new Vector3(8, 8, 1); // Range for random positioning
    private float timeSinceLastSpawn = 0f;
    private int spawnCount = 0;
    public int maxCubes = 50;

    void Update()
    {
        timeSinceLastSpawn += Time.deltaTime;

        if (timeSinceLastSpawn >= spawnRate)
        {
            SpawnCube();
            timeSinceLastSpawn = 0f;
        }
    }

    void SpawnCube()
    {
        if (spawnCount < maxCubes)
        {
            GameObject newCube = Instantiate(cubePrefab);
            newCube.transform.position = new Vector3(
                Random.Range(-spawnRange.x, spawnRange.x),
                Random.Range(-spawnRange.y, spawnRange.y),
                Random.Range(-spawnRange.z, spawnRange.z)
            );

            spawnCount++;
        }
        else
        {
            spawnCount = 0; // Reset the counter
        }
    }
}
