public static async Task<ProcessResult> StartProcessAsync(string fileName, string arguments, string workingDir)
{
    using (Process process = new Process())
    {
        process.StartInfo.UseShellExecute = false;
        process.StartInfo.RedirectStandardOutput = true;
        process.StartInfo.RedirectStandardInput = true;
        process.StartInfo.FileName = fileName;
        process.StartInfo.Arguments = arguments;
        process.StartInfo.WorkingDirectory = workingDir;
        process.StartInfo.CreateNoWindow = true;

        process.Start();

        var outputTask = ReadOutputAsync(process.StandardOutput);

        // You can handle standard input here if needed
        // For example: process.StandardInput.WriteLine("your command");

        await process.WaitForExitAsync();
        string output = await outputTask;

        return new ProcessResult(output, "", process.ExitCode);
    }
}

private static async Task<string> ReadOutputAsync(StreamReader reader)
{
    return await reader.ReadToEndAsync();
}
