using System;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class TokenGenerator
{
    public async Task<string> GenerateTokenAndSendRequest(string password, string domain, int port, string url)
    {
        string token = HashPassword(password);
        using (HttpClient client = new HttpClient())
        {
            client.BaseAddress = new Uri($"{domain}:{port}");
            var content = new StringContent(token, Encoding.UTF8, "application/json");
            HttpResponseMessage response = await client.PostAsync(url, content);
            return await response.Content.ReadAsStringAsync();
        }
    }

    private string HashPassword(string password)
    {
        using (SHA1 sha1 = SHA1.Create())
        {
            byte[] hashBytes = sha1.ComputeHash(Encoding.UTF8.GetBytes(password));
            StringBuilder result = new StringBuilder();
            foreach (byte b in hashBytes)
            {
                result.Append(b.ToString("x2"));
            }
            return result.ToString();
        }
    }
}
