public class ImageDownloader
{
    private readonly string _connectionString;

    public ImageDownloader(string connectionString)
    {
        _connectionString = connectionString;
    }

    public async Task<bool> DownloadImageAndSaveToDatabaseAsync(string imageUrl)
    {
        try
        {
            using (HttpClient client = new HttpClient())
            {
                var response = await client.GetAsync(imageUrl);
                response.EnsureSuccessStatusCode();

                var imageData = await response.Content.ReadAsByteArrayAsync();
                return SaveImageToDatabase(imageData);
            }
        }
        catch (HttpRequestException ex)
        {
            Console.WriteLine($"Error downloading image: {ex.Message}");
            return false;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Unexpected error: {ex.Message}");
            return false;
        }
    }

    private bool SaveImageToDatabase(byte[] imageData)
    {
        try
        {
            using (SqlConnection connection = new SqlConnection(_connectionString))
            {
                connection.Open();
                using (SqlCommand command = new SqlCommand("INSERT INTO Images (ImageData) VALUES (@ImageData)", connection))
                {
                    command.Parameters.AddWithValue("@ImageData", imageData);
                    command.ExecuteNonQuery();
                }
            }
            return true;
        }
        catch (SqlException ex)
        {
            Console.WriteLine($"Database error: {ex.Message}");
            return false;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Unexpected error while saving to database: {ex.Message}");
            return false;
        }
    }
}
