using Microsoft.AspNetCore.Mvc;

public class MyModelController : Controller
{
    private readonly IRepository<MyModel> repository;

    public MyModelController(IRepository<MyModel> repository)
    {
        this.repository = repository;
    }

    [HttpGet("{id}")]
    public ActionResult<MyModelViewModel> Get(int id)
    {
        var model = repository.Get(id);
        if (model == null)
        {
            return NotFound();
        }
        return View(new MyModelViewModel(model));
    }

    [HttpPost]
    public ActionResult<MyModelViewModel> Post(MyModelViewModel newModel)
    {
        if (ModelState.IsValid)
        {
            var model = new MyModel
            {
                Property1 = newModel.Property1,
                Property2 = newModel.Property2
            };
            repository.Add(model);
            repository.Save();
            return Json(new MyModelViewModel(model));
        }
        return BadRequest(ModelState);
    }

    [HttpPut("{id}")]
    public ActionResult<MyModelViewModel> Put(int id, MyModelViewModel updatedModel)
    {
        var model = repository.Get(id);
        if (model == null)
        {
            return NotFound();
        }

        if (ModelState.IsValid)
        {
            model.Property1 = updatedModel.Property1;
            model.Property2 = updatedModel.Property2;
            repository.Update(model);
            repository.Save();
            return Json(new MyModelViewModel(model));
        }
        return BadRequest(ModelState);
    }
}
