public class ConfigFileUpdater
{
    private XDocument _xmlDocument;

    public ConfigFileUpdater(XDocument xmlDocument)
    {
        _xmlDocument = xmlDocument;
    }

    public XDocument UpdateXmlFile(string existingSectionXPath, string newSectionXml, string insertAfterXPath)
    {
        var existingSections = _xmlDocument.XPathSelectElements(existingSectionXPath);
        if (existingSections.Any())
        {
            var newSection = XDocument.Parse(newSectionXml).Root;
            var insertAfterElement = _xmlDocument.XPathSelectElement(insertAfterXPath);
            insertAfterElement?.AddAfterSelf(newSection);
        }
        return _xmlDocument;
    }
}

