        XmlDocument doc = new XmlDocument();
        Dictionary<string, string> configSettings = new Dictionary<string, string>();

        try
        {
            doc.Load("file://" + configFile);
        }
        catch (XmlException e)
        {
            throw new ConfigurationException("XML Syntax error in: " + configFile, e);
        }

        XmlNode rootNode = doc.DocumentElement;
        if (rootNode == null)
        {
            throw new ConfigurationException("Root element is missing in the configuration file.");
        }

        foreach (XmlNode childNode in rootNode.ChildNodes)
        {
            if (childNode is XmlElement element)
            {
                string key = element.Name;
                string value = element.InnerText;
                configSettings[key] = value;
            }
        }

        return configSettings;
    }
}

