using System.Security.Cryptography;
using System.Text;

public class AccountService
{
    public string UpdatePassword(int userId, string password)
    {
        if (userId <= 0 || string.IsNullOrEmpty(password))
        {
            return "Validation error: Invalid user ID or password.";
        }

        string connectionString = "YourConnectionStringHere"; // Replace with your actual connection string
        using (SqlConnection connection = new SqlConnection(connectionString))
        {
            try
            {
                connection.Open();
                string passwordHash = ComputeSha1Hash(password);
                string query = "UPDATE users SET password_digest = @PasswordDigest WHERE user_id = @UserId";

                using (SqlCommand command = new SqlCommand(query, connection))
                {
                    command.Parameters.AddWithValue("@PasswordDigest", passwordHash);
                    command.Parameters.AddWithValue("@UserId", userId);

                    int rowsAffected = command.ExecuteNonQuery();
                    if (rowsAffected > 0)
                    {
                        return "Password updated successfully.";
                    }
                    else
                    {
                        return "Error: User not found or password update failed.";
                    }
                }
            }
            catch (SqlException ex)
            {
                // Log exception (ex) here if needed
                return "Error: Database operation failed.";
            }
        }
    }

    private string ComputeSha1Hash(string input)
    {
        using (SHA1 sha1 = SHA1.Create())
        {
            byte[] inputBytes = Encoding.UTF8.GetBytes(input);
            byte[] hashBytes = sha1.ComputeHash(inputBytes);
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
        }
    }
}
