using System;
using System.Security.Cryptography;
using System.Text;

public static class StringExtensions
{
    private static readonly string fixedKey = "12345678"; // Must be 8 bytes for DES

    public static string DesEncrypt(this string text, Encoding encoding = null)
    {
        if (string.IsNullOrEmpty(text)) return "";
        encoding = encoding ?? Encoding.UTF8;

        using (DESCryptoServiceProvider des = new DESCryptoServiceProvider())
        {
            des.Mode = CipherMode.ECB;
            des.Padding = PaddingMode.Zeros;
            des.Key = encoding.GetBytes(fixedKey);

            byte[] inputBuffer = encoding.GetBytes(text);
            byte[] outputBuffer = des.CreateEncryptor().TransformFinalBlock(inputBuffer, 0, inputBuffer.Length);
            return Convert.ToBase64String(outputBuffer);
        }
    }
}
