    public async Task<int> GetNextVersionAsync(int streamId, int currentVersion)
    {
        const string query = "SELECT MIN(Version) FROM Versions WHERE StreamId = @StreamId AND Version > @CurrentVersion";

        using (SqlConnection connection = new SqlConnection(_connectionString))
