using System;
using System.IO;
using System.Xml;
using System.Xml.Schema;

public class XmlValidator
{
    public static bool ValidateXml(string xmlContent, string xsdContent)
    {
        XmlSchema schema = XmlSchema.Read(new StringReader(xsdContent), null);
        XmlReaderSettings settings = new XmlReaderSettings();
        settings.Schemas.Add(schema);
        settings.ValidationType = ValidationType.Schema;

        using (XmlReader reader = XmlReader.Create(new StringReader(xmlContent), settings))
        {
            try
            {
                while (reader.Read())
                {
                    if (reader.NodeType == XmlNodeType.Element && reader.HasAttributes)
                    {
                        reader.MoveToFirstAttribute();
                        return string.IsNullOrEmpty(reader.Prefix);
                    }
                }
            }
            catch (XmlSchemaValidationException)
            {
                return false; // XML is not valid against the schema
            }
        }
        return false; // No attributes found
    }
}
