private int UpdateTrackables(string tbCode, List<LogItem> logList)
{
    int rowsAffected = 0;

    // Fetch logs from the database
    List<int> logsIndb = new List<int>();
    DbDataReader dr = _dbcon.ExecuteReader("SELECT ID FROM logs WHERE TrackableCode = @TrackableCode", new DbParameter[] {
        new DbParameter("@TrackableCode", DbType.String) { Value = tbCode }
    });
    while (dr.Read())
    {
        logsIndb.Add((int)dr["ID"]);
    }

    // Prepare parameters for the update
    _dbcon.Command.Parameters.Clear();
    _dbcon.Command.Parameters.Add(new DbParameter("@DistanceKm", DbType.Double));
    _dbcon.Command.Parameters.Add(new DbParameter("@Lat", DbType.Double));
    _dbcon.Command.Parameters.Add(new DbParameter("@Lon", DbType.Double));
    _dbcon.Command.Parameters.Add(new DbParameter("@TrackableCode", DbType.String) { Value = tbCode });

    foreach (var log in logList)
    {
        _dbcon.Command.Parameters["@DistanceKm"].Value = log.DistanceKm;
        _dbcon.Command.Parameters["@Lat"].Value = log.Lat;
        _dbcon.Command.Parameters["@Lon"].Value = log.Lon;

        // Update the trackables table
        rowsAffected += _dbcon.ExecuteNonQuery("UPDATE trackables SET DistanceKm = @DistanceKm, Lat = @Lat, Lon = @Lon WHERE Code = @TrackableCode");
    }

    return rowsAffected;
}
