    }

    using (var context = new ApplicationDbContext())
    {
        var record = context.Records.Find(id);
        if (record == null)
        {
            return HttpNotFound();
        }

        record.Name = model.Name;
        record.Email = model.Email;
        record.Age = model.Age;

        try
        {
            context.SaveChanges();
            return RedirectToAction("Index");
        }
