using System;
using System.Collections.Generic;
using System.Xml;

public class ConfigurationLoader
{
    public Dictionary<string, string> LoadSettings(string filePath)
    {
        XmlDocument doc = new XmlDocument();
        Dictionary<string, string> settings = new Dictionary<string, string>();

        try
        {
            doc.Load(filePath);
        }
        catch (XmlException e)
        {
            throw new Exception("XML Syntax error in: " + filePath, e);
        }

        XmlNode configNode = doc.SelectSingleNode("//configuration");
        if (configNode == null)
        {
            throw new Exception("No configuration element found!");
        }

        foreach (XmlNode settingNode in configNode.ChildNodes)
        {
            if (settingNode.NodeType == XmlNodeType.Element)
            {
                string key = settingNode.Name;
                string value = settingNode.InnerText;
                settings[key] = value;
            }
        }

        return settings;
    }
}
