using System;
using System.Collections.Generic;
using System.Security.Cryptography;

public class Resource
{
    public string Hash { get; set; }
    public byte[] Data { get; set; }
    public string MimeType { get; set; }

    public Resource(string hash, byte[] data, string mimeType)
    {
        Hash = hash;
        Data = data;
        MimeType = mimeType;
    }
}

public class ResourceProcessor
{
    public List<Resource> CreateResources(List<(byte[] Data, string MimeType)> resources)
    {
        var resourceList = new List<Resource>();

        foreach (var resource in resources)
        {
            using (var md5 = MD5.Create())
            {
                var hashBytes = md5.ComputeHash(resource.Data);
                var hashString = BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
                var newResource = new Resource(hashString, resource.Data, resource.MimeType);
                resourceList.Add(newResource);
            }
        }

        return resourceList;
    }
}
