using System;
using System.IO;
using System.Diagnostics;

public class FileCopier
{
    public void CopyFiles(string sourceDirectory, string targetDirectory, string[] includeExtensions, string[] excludeExtensions)
    {
        if (!Directory.Exists(sourceDirectory))
        {
            throw new DirectoryNotFoundException($"Source directory does not exist: {sourceDirectory}");
        }

        if (!Directory.Exists(targetDirectory))
        {
            Directory.CreateDirectory(targetDirectory);
        }

        foreach (var filePath in Directory.GetFiles(sourceDirectory))
        {
            string extension = Path.GetExtension(filePath).ToLower();

            if (ShouldCopyFile(extension, includeExtensions, excludeExtensions))
            {
                string targetFilePath = Path.Combine(targetDirectory, Path.GetFileName(filePath));
                ProcessStartInfo processStartInfo = new ProcessStartInfo
                {
                    FileName = "cmd.exe",
                    Arguments = $"/c copy \"{filePath}\" \"{targetFilePath}\"",
                    RedirectStandardOutput = true,
                    UseShellExecute = false,
                    CreateNoWindow = true
                };

                using (Process process = Process.Start(processStartInfo))
                {
                    process.WaitForExit();
                }
            }
        }

        foreach (var directory in Directory.GetDirectories(sourceDirectory))
        {
            string targetSubDirectory = Path.Combine(targetDirectory, Path.GetFileName(directory));
            CopyFiles(directory, targetSubDirectory, includeExtensions, excludeExtensions);
        }
    }

    private bool ShouldCopyFile(string extension, string[] includeExtensions, string[] excludeExtensions)
    {
        bool isIncluded = includeExtensions.Length == 0 || Array.Exists(includeExtensions, ext => ext.Equals(extension, StringComparison.OrdinalIgnoreCase));
        bool isExcluded = Array.Exists(excludeExtensions, ext => ext.Equals(extension, StringComparison.OrdinalIgnoreCase));
        return isIncluded && !isExcluded;
    }
}
