using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public static class DesDecryptor
{
    private static readonly byte[] Key = Encoding.ASCII.GetBytes("12345678"); // Fixed key (must be 8 bytes)
    private static readonly byte[] IV = new byte[8]; // Initialization vector (can be zeroed for simplicity)

    public static string DecryptHex(string hexString)
    {
        try
        {
            // Convert hex string to byte array
            byte[] buffer = ConvertHexStringToByteArray(hexString);

            using (DESCryptoServiceProvider provider = new DESCryptoServiceProvider())
            {
                using (MemoryStream stream = new MemoryStream())
                {
                    using (CryptoStream cryptoStream = new CryptoStream(stream, provider.CreateDecryptor(Key, IV), CryptoStreamMode.Write))
                    {
                        cryptoStream.Write(buffer, 0, buffer.Length);
                        cryptoStream.FlushFinalBlock();
                        return Encoding.ASCII.GetString(stream.ToArray());
                    }
                }
            }
        }
        catch
        {
            return ""; // Return empty string on error
        }
    }

    private static byte[] ConvertHexStringToByteArray(string hex)
    {
        if (hex.Length % 2 != 0)
            throw new FormatException("Invalid hex string length.");

        byte[] bytes = new byte[hex.Length / 2];
        for (int i = 0; i < hex.Length; i += 2)
        {
            bytes[i / 2] = Convert.ToByte(hex.Substring(i, 2), 16);
        }
        return bytes;
    }
}
