{
reader.ReadStartElement();
while (true)
{
string line = "";
char[] buf = new char[1];
int count = 1;
for (int i = 0; i < 100; i++)       //read one line
{
count = reader.ReadValueChunk(buf, 0, 1);
if (buf[0] == '\n' || buf[0] == ' ' || buf[0] == '\r' || buf[0] == '\t' || count == 0)
break;
line += buf[0];
}
