{
for (int i = 0; i < vector_size / 2; i++)
{
dataLat[i] = dataLat[i * 2];
dataLong[i] = dataLong[i * 2];
dataZ[i] = dataZ[i * 2];
dataT[i] = dataT[i * 2];
dataD[i] = dataD[i * 2];
}
data_size = vector_size / 2;
Decimation *= 2;
}

