using System;
using System.IO;
using System.Xml;
using System.Xml.Schema;

public class XmlValidator
{
    public event EventHandler<ValidationEventArgs> ValidationError;

    public void ValidateXml(string xmlContent, string dtdPath)
    {
        try
        {
            XmlDocument xmlDoc = new XmlDocument();
            xmlDoc.LoadXml(xmlContent);
            xmlDoc.Schemas.Add(null, dtdPath);
            xmlDoc.Validate(ValidationCallback);
            Console.WriteLine("XML document is valid.");
        }
        catch (XmlException ex)
        {
            Console.WriteLine("XML Exception: " + ex.Message);
            OnValidationError(new ValidationEventArgs(ex));
        }
        catch (XmlSchemaValidationException ex)
        {
            Console.WriteLine("Schema Validation Exception: " + ex.Message);
            OnValidationError(new ValidationEventArgs(ex));
        }
    }

    private void ValidationCallback(object sender, ValidationEventArgs e)
    {
        Console.WriteLine("Validation Error: " + e.Message);
        OnValidationError(e);
    }

    protected virtual void OnValidationError(ValidationEventArgs e)
    {
        ValidationError?.Invoke(this, e);
    }
}
