using System;
using System.Security.Cryptography;
using System.Text;

public static class EncryptionHelper
{
    public static string TripleDESEncrypt(string plainText, Guid key1, Guid key2)
    {
        if (string.IsNullOrEmpty(plainText)) return string.Empty;

        byte[] key = CombineGuids(key1, key2);
        using (TripleDESCryptoServiceProvider tdes = new TripleDESCryptoServiceProvider())
        {
            tdes.Mode = CipherMode.ECB;
            tdes.Padding = PaddingMode.PKCS7;
            tdes.Key = key;

            byte[] inputBuffer = Encoding.UTF8.GetBytes(plainText);
            byte[] outputBuffer = tdes.CreateEncryptor().TransformFinalBlock(inputBuffer, 0, inputBuffer.Length);
            return Convert.ToBase64String(outputBuffer);
        }
    }

    private static byte[] CombineGuids(Guid key1, Guid key2)
    {
        byte[] combined = new byte[24];
        Buffer.BlockCopy(key1.ToByteArray(), 0, combined, 0, 16);
        Buffer.BlockCopy(key2.ToByteArray(), 0, combined, 16, 8);
        return combined;
    }
}
