using System.Reflection;

class Program
{
    static void Main(string[] args)
    {
        string sourcePath = @"C:\Path\To\NewVersion\YourApp.exe";
        string destinationPath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "YourApp.exe");

