public class ConfigFileUpdater
{
    private XDocument _xmlDocument;

    public ConfigFileUpdater(XDocument xmlDocument)
    {
        _xmlDocument = xmlDocument;
    }

    public XDocument UpdateXmlFile(string xpathToExistingSection, string xmlElementToInsert, string xpathToInsertAfter)
    {
        var existingSections = _xmlDocument.XPathSelectElements(xpathToExistingSection);
        if (existingSections.Any())
        {
            XElement newElement = XElement.Parse(xmlElementToInsert);
            var insertAfterElement = _xmlDocument.XPathSelectElements(xpathToInsertAfter).FirstOrDefault();
            insertAfterElement?.AddAfterSelf(newElement);
        }
        return _xmlDocument;
    }
}

