public void UpdateConfigurationNode(XmlDocument xmlConfig, string keyValue)
{
    XmlNode rootNode = xmlConfig.DocumentElement;

    // Look for the existing configuration node
    XmlNode configNode = rootNode.SelectSingleNode("property[@name='" + keyValue + "']");
    if (configNode != null)
    {
        // Node found, remove it
        rootNode.RemoveChild(configNode);
    }

    // Create a new configuration node with the same key value
    configNode = xmlConfig.CreateElement("property");
    XmlAttribute xmlAttr = xmlConfig.CreateAttribute("name");
    xmlAttr.Value = keyValue;
    configNode.Attributes.Append(xmlAttr);

    // Append the new node to the root
    rootNode.AppendChild(configNode);
}
