using System;
using System.Security.Cryptography;
using System.Text;

public class SymmetricEncryptionTest
{
    public void TestEncryptionDecryption(string algorithm, byte[] key, string plaintext)
    {
        // Validate key size
        using (var cipher = SymmetricAlgorithm.Create(algorithm))
        {
            if (cipher == null)
                throw new ArgumentException("Invalid algorithm specified.");

            if (key.Length * 8 != cipher.KeySize)
                throw new ArgumentException("Invalid key size.");

            cipher.Key = key;
            cipher.Mode = CipherMode.ECB;
            cipher.Padding = PaddingMode.Zeros;

            // Convert plaintext to bytes
            byte[] plaintextBytes = Encoding.UTF8.GetBytes(plaintext);
            byte[] encryptedBytes;
            byte[] decryptedBytes;

            // Encrypt
            using (var encryptor = cipher.CreateEncryptor())
            {
                encryptedBytes = encryptor.TransformFinalBlock(plaintextBytes, 0, plaintextBytes.Length);
            }

            // Decrypt
            using (var decryptor = cipher.CreateDecryptor())
            {
                decryptedBytes = decryptor.TransformFinalBlock(encryptedBytes, 0, encryptedBytes.Length);
            }

            // Check if decryption is the inverse of encryption
            if (!AreEqual(plaintextBytes, decryptedBytes))
                throw new Exception("Decryption did not yield the original plaintext.");

            // Check if encrypted message is not the same as the original plaintext
            if (AreEqual(plaintextBytes, encryptedBytes))
                throw new Exception("Encrypted message should not be the same as the original plaintext.");
        }
    }

    private bool AreEqual(byte[] a, byte[] b)
    {
        if (a.Length != b.Length)
            return false;

        for (int i = 0; i < a.Length; i++)
        {
            if (a[i] != b[i])
                return false;
        }
        return true;
    }
}
