import java.security.SecureRandom;

public class PasswordGenerator {

    private static final String CHARACTERS = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    private static final String END_CHARACTERS = "%$";

    public static String generatePassword(int length) {
        if (length <= 0) {
            throw new IllegalArgumentException("Invalid password length specified.");
        }

        SecureRandom random = new SecureRandom();
        StringBuilder password = new StringBuilder(length);

        // Generate the main part of the password
        for (int i = 0; i < length - 2; i++) {
            int index = random.nextInt(CHARACTERS.length());
            password.append(CHARACTERS.charAt(index));
        }

        // Append the restricted characters at the end
        int endIndex = random.nextInt(END_CHARACTERS.length());
        password.append(END_CHARACTERS.charAt(endIndex));

        return password.toString();
    }

    public static void main(String[] args) {
        int passwordLength = 10; // Example length
        String password = generatePassword(passwordLength);
        System.out.println("Generated Password: " + password);
    }
}
