import com.codahale.metrics.Graphite;
import com.codahale.metrics.GraphiteReporter;
import com.codahale.metrics.MetricFilter;
import com.codahale.metrics.MetricRegistry;
import com.codahale.metrics.MetricGauge;

import java.net.InetSocketAddress;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.TimeUnit;

public class MetricNotificationService {
    private final GraphiteReporter graphiteReporter;
    private final MetricRegistry metricRegistry;
    private final Map<String, MetricGauge> metricMap;

    private static MetricNotificationService instance;

    private MetricNotificationService() {
        Graphite graphite = new Graphite(new InetSocketAddress(
                StartupProperties.get().getProperty("falcon.graphite.hostname"),
                Integer.parseInt(StartupProperties.get().getProperty("falcon.graphite.port"))
        ));
        this.metricRegistry = new MetricRegistry();
        this.graphiteReporter = GraphiteReporter.forRegistry(metricRegistry)
                .convertDurationsTo(TimeUnit.SECONDS)
                .filter(MetricFilter.ALL)
                .build(graphite);
        this.metricMap = new HashMap<>();
    }

    public static MetricNotificationService get() {
        if (instance == null) {
            instance = new MetricNotificationService();
        }
        return instance;
    }

    public void registerMetric(String name, MetricGauge metricGauge) {
        metricMap.put(name, metricGauge);
        metricRegistry.register(name, metricGauge);
    }
}
