public class ConnectionManager {

    public List<InetSocketAddress> createInetSocketAddresses(List<String> hostPortList, String username, String password, String serverId, boolean createEnrichmentConnection, String driverLocation, String driverName, int connectionTimeout) {
        if (hostPortList == null) {
            return null;
        }

