        for (String hostPort : hostPortList) {
            String[] addresses = hostPort.split(":");
            if (addresses.length != 2) {
                throw new ArrayIndexOutOfBoundsException("Not in host:port format");
            }

            String host = addresses[0].trim();
            int port;
            try {
                port = Integer.parseInt(addresses[1].trim());
            } catch (NumberFormatException e) {
                throw new ArrayIndexOutOfBoundsException("Port is not a valid number");
            }

