import java.util.ArrayList;
import java.util.List;
import java.util.Random;

public class ObjectMutator {

    public List<Object> mutateList(List<Object> originalList, Random rng) {
        List<Object> mutatedList = new ArrayList<>(originalList);
        List<Object> discreteValues = new ArrayList<>();

        for (int i = 0; i < originalList.size(); i++) {
            double r = rng.nextGaussian() * (originalList.size() * 0.2);
            int newIndex = Math.min(Math.max((int) Math.round(i + r), 0), originalList.size() - 1);
            Object newValue = originalList.get(newIndex);
            mutatedList.set(i, newValue);
            discreteValues.add(newValue);
        }

        return mutatedList;
    }

    public List<Object> getDiscreteValues(List<Object> originalList, Random rng, int iterations) {
        List<Object> allDiscreteValues = new ArrayList<>();
        for (int i = 0; i < iterations; i++) {
            List<Object> mutated = mutateList(originalList, rng);
            allDiscreteValues.addAll(mutated);
        }
        return allDiscreteValues;
    }
}
