private static SortedBinaryDocValues compareData(Random random, LeafReaderContext context, IndexFieldData<?> left, IndexFieldData<?> right, Preprocessor pre) throws Exception {
    AtomicFieldData leftData = left.load(context);
    AtomicFieldData rightData = right.load(context);

    // Validate input types
    if (leftData.getClass() != rightData.getClass()) {
        throw new IllegalArgumentException("Input types must be the same.");
    }

    Class<?> dataType = leftData.getClass();
    int numDocs = context.reader().maxDoc();

    // Initialize SortedBinaryDocValues for result
    SortedBinaryDocValues result = tr_new(SortedBinaryDocValues.class);

    // Load data and perform type conversion
    Object leftConverted = TypeConversions.coerce(dataType, leftData.bytes);
    Object rightConverted = TypeConversions.coerce(dataType, rightData.bytes);

    // Perform bounds checking on array indices derived from user-controlled input
    byte[] leftBytes = (byte[]) leftConverted;
    byte[] rightBytes = (byte[]) rightConverted;
    int leftLength = leftBytes.length;
    int rightLength = rightBytes.length;
    int minLength = Math.min(leftLength, rightLength);

    for (int i = 0; i < minLength; i++) {
        int leftIndex = i;
        int rightIndex = i;

        // Perform binary search on left data
        int leftIndex1 = binarySearch(leftBytes, 0, leftLength - 1, leftBytes[i]);
        if (leftIndex1 >= 0) {
            leftIndex = leftIndex1;
        } else {
            leftIndex = binarySearch(leftBytes, 0, leftLength, leftBytes[i]);
            if (leftIndex < 0) {
                // Data out of order, return empty result
                result.setLength(0);
                return result;
            }
        }

        // Perform binary search on right data
        int rightIndex1 = binarySearch(rightBytes, 0, rightLength - 1, rightBytes[i]);
        if (rightIndex1 >= 0) {
            rightIndex = rightIndex1;
        } else {
            rightIndex = binarySearch(rightBytes, 0, rightLength, rightBytes[i]);
            if (rightIndex < 0) {
                // Data out of order, return empty result
                result.setLength(0);
                return result;
            }
        }

        // Add result to SortedBinaryDocValues
        result.addValue(new BytesRef(numDocs, leftBytes, leftIndex, leftIndex + 1));
        result.addValue(new BytesRef(numDocs, rightBytes, rightIndex, rightIndex + 1));
    }

    // Handle remaining elements
    if (leftLength > minLength) {
        result.addValue(new BytesRef(numDocs, leftBytes, minLength, leftLength));
    }
    if (rightLength > minLength) {
        result.addValue(new BytesRef(numDocs, rightBytes, minLength, rightLength));
    }

    return result;
}

private static int binarySearch(byte[] arr, int left, int right, byte key) {
    while (left <= right) {
        int mid = (left + right) / 2;
        if (arr[mid] == key) {
            return mid;
        } else if (arr[mid] < key) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return -(left + 1);
}
