import java.util.concurrent.CountDownLatch;
import java.util.concurrent.atomic.AtomicInteger;

public class ConcurrentGraphTraversal {
    private static final int TOTAL_THREADS = 250;
    private static final AtomicInteger vertices = new AtomicInteger(0);
    private static final AtomicInteger edges = new AtomicInteger(0);
    private static final AtomicInteger completedThreads = new AtomicInteger(0);
    private static final CountDownLatch countDownLatch = new CountDownLatch(TOTAL_THREADS);

    public static void main(String[] args) throws InterruptedException {
        Graph graph = new Graph(); // Assume Graph is a predefined class for graph operations

        for (int i = 0; i < TOTAL_THREADS; i++) {
            new Thread(() -> {
                try {
                    Random random = new Random();
                    Vertex a = graph.addVertex();
                    Vertex b = graph.addVertex();
                    Edge e = a.addEdge("friend", b);

                    a.property("test", Thread.currentThread().getId());
                    b.property("blah", random.nextDouble());
                    e.property("bloop", random.nextInt());

                    vertices.getAndAdd(2);
                    edges.getAndAdd(1);
                    graph.commit(); // Assume commit method exists

                    completedThreads.getAndAdd(1);
                    System.out.println("Completed Threads: " + completedThreads.get());
                } catch (Exception e) {
                    e.printStackTrace();
                } finally {
                    countDownLatch.countDown();
                }
            }).start();
        }

        countDownLatch.await();
        System.out.println("Total Vertices: " + vertices.get());
        System.out.println("Total Edges: " + edges.get());
        System.out.println("Total Completed Threads: " + completedThreads.get());
    }
}
