import java.io.IOException;
import java.util.Collection;
import java.util.Map;

public class JsonGenerator {

    @Nonnull
    public static String toJson(@Nonnull Object object) throws IOException {
        StringBuilder jsonBuilder = new StringBuilder();
        generateJson(object, jsonBuilder);
        return jsonBuilder.toString();
    }

    private static void generateJson(Object object, StringBuilder jsonBuilder) {
        if (object == null) {
            jsonBuilder.append("null");
        } else if (object instanceof String) {
            jsonBuilder.append("\"").append(escapeString((String) object)).append("\"");
        } else if (object instanceof Number || object instanceof Boolean) {
            jsonBuilder.append(object.toString());
        } else if (object instanceof Map) {
            jsonBuilder.append("{");
            Map<?, ?> map = (Map<?, ?>) object;
            boolean first = true;
            for (Map.Entry<?, ?> entry : map.entrySet()) {
                if (!first) {
                    jsonBuilder.append(",");
                }
                jsonBuilder.append("\"").append(escapeString(entry.getKey().toString())).append("\":");
                generateJson(entry.getValue(), jsonBuilder);
                first = false;
            }
            jsonBuilder.append("}");
        } else if (object instanceof Collection) {
            jsonBuilder.append("[");
            Collection<?> collection = (Collection<?>) object;
            boolean first = true;
            for (Object item : collection) {
                if (!first) {
                    jsonBuilder.append(",");
                }
                generateJson(item, jsonBuilder);
                first = false;
            }
            jsonBuilder.append("]");
        } else {
            jsonBuilder.append("{");
            boolean first = true;
            for (var field : object.getClass().getDeclaredFields()) {
                field.setAccessible(true);
                if (!first) {
                    jsonBuilder.append(",");
                }
                try {
                    jsonBuilder.append("\"").append(escapeString(field.getName())).append("\":");
                    generateJson(field.get(object), jsonBuilder);
                } catch (IllegalAccessException e) {
                    jsonBuilder.append("\"").append(escapeString(field.getName())).append("\":null");
                }
                first = false;
            }
            jsonBuilder.append("}");
        }
    }

    private static String escapeString(String str) {
        return str.replace("\\", "\\\\")
                  .replace("\"", "\\\"")
                  .replace("\b", "\\b")
                  .replace("\f", "\\f")
                  .replace("\n", "\\n")
                  .replace("\r", "\\r")
                  .replace("\t", "\\t");
    }
}
