import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;

public class WeightedItemNormalizer<T> {

    public Map<T, Double> normalizeWeights(List<T> weightedItems, Function<T, Double> weightFunc) {
        Map<T, Double> normalized = new HashMap<>();
        double sum = 0.0;

        for (T item : weightedItems) {
            sum += weightFunc.apply(item);
        }

        for (T item : weightedItems) {
            normalized.put(item, weightFunc.apply(item) / sum);
        }

        return normalized;
    }
}
