import java.util.HashMap;

public class DisjointPairs {
    private static class UnionFind {
        private HashMap<Integer, Integer> parent = new HashMap<>();

        public UnionFind(int[] elements) {
            for (int element : elements) {
                parent.put(element, element);
            }
        }

        public int find(int element) {
            if (parent.get(element) != element) {
                parent.put(element, find(parent.get(element)));
            }
            return parent.get(element);
        }

        public void unite(int element1, int element2) {
            int root1 = find(element1);
            int root2 = find(element2);
            if (root1 != root2) {
                parent.put(root1, root2);
            }
        }
    }

    public static int countDisjointPairs(int[] array) {
        long startTime = System.currentTimeMillis();
        UnionFind uf = new UnionFind(array);
        int count = 0;

        for (int i = 0; i < array.length; i++) {
            for (int j = i + 1; j < array.length; j++) {
                if (uf.find(array[i]) != uf.find(array[j])) {
                    count++;
                }
            }
        }

        long endTime = System.currentTimeMillis();
        System.out.println("Time taken: " + (endTime - startTime) + " milliseconds");
        return count;
    }

    public static void main(String[] args) {
        int[] inputArray = {1, 2, 3, 4, 5};
        int result = countDisjointPairs(inputArray);
        System.out.println("Number of disjoint pairs: " + result);
    }
}
