import org.glassfish.jersey.server.model.OAuthFlows;
import org.glassfish.jersey.server.model.OAuthFlow;
import org.glassfish.jersey.server.model.Scopes;

public void configureKeycloakSecurity(OpenAPI openApi, String keycloakRealmPath) {
    openApi.getComponents().addSecuritySchemes("OIDC", createOIDCScheme(keycloakRealmPath));
    openApi.getComponents().addSecuritySchemes("OAUTH2", createOAuth2Scheme(keycloakRealmPath));

    SecurityScheme oidcScheme = openApi.getComponents().getSecuritySchemes().get("OIDC");
    SecurityScheme oauth2Scheme = openApi.getComponents().getSecuritySchemes().get("OAUTH2");

    OAuthFlows oauth2Flows = new OAuthFlows();
