import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class GeoPointComparator {

    public static void compareGeoPointSets(GeoPointDataSet left, GeoPointDataSet right, double distanceTolerance) throws Exception {
        int numDocs = left.getNumDocuments();
        for (int i = 0; i < numDocs; ++i) {
            List<GeoPoint> leftPoints = left.getGeoPoints(i);
            List<GeoPoint> rightPoints = right.getGeoPoints(i);

            int numLeftValues = leftPoints.size();
            int numRightValues = rightPoints.size();
            assertEquals(numLeftValues, numRightValues);

            if (numLeftValues > 0) {
                Collections.sort(leftPoints);
                Collections.sort(rightPoints);

                for (int j = 0; j < numLeftValues; ++j) {
                    GeoPoint leftPoint = leftPoints.get(j);
                    GeoPoint rightPoint = rightPoints.get(j);
                    assertTrue("Points are not within the specified distance tolerance", 
                               arePointsEqualWithinTolerance(leftPoint, rightPoint, distanceTolerance));
                }
            }
        }
    }

    private static boolean arePointsEqualWithinTolerance(GeoPoint point1, GeoPoint point2, double tolerance) {
        double distance = calculateDistance(point1, point2);
        return distance <= tolerance;
    }

    private static double calculateDistance(GeoPoint point1, GeoPoint point2) {
        // Implement the distance calculation logic (e.g., Haversine formula)
        return Math.sqrt(Math.pow(point1.getLat() - point2.getLat(), 2) + 
                         Math.pow(point1.getLon() - point2.getLon(), 2));
    }

