        if (expected != actual) {
            throw new Exception("Assertion failed: expected " + expected + " but got " + actual);
        }
    }

    private static void assertTrue(String message, boolean condition) throws Exception {
        if (!condition) {
            throw new Exception(message);
        }
    }
}
