public class TokenManager {

    private DelegationTokenManagerService tokenManagerService;

    public TokenManager(DelegationTokenManagerService tokenManagerService) {
        this.tokenManagerService = tokenManagerService;
    }

    public Object manageDelegationToken(UserCredentials credentials, String tokenIdentifier) throws Exception {
        Token token = tokenManagerService.createToken(credentials.getUser(), tokenIdentifier);
        if (token != null) {
            // Verify the token
            boolean isVerified = tokenManagerService.verifyToken(token);
            if (isVerified) {
                // Renew the token
                long renewedTime = tokenManagerService.renewToken(token, tokenIdentifier);
                return renewedTime > System.currentTimeMillis() ? token : false;
            }
        }
        return false;
    }

    public boolean cancelDelegationToken(Token token, String tokenIdentifier) throws Exception {
        try {
            tokenManagerService.cancelToken(token, tokenIdentifier);
            return true;
        } catch (DelegationTokenManagerException ex) {
            return false;
        }
    }
}
