public void populateGraphDatabase(ExecutorService executorService, SQLgGraph sqlgGraph, int iterations) {
    VertexLabel vertexLabel = sqlgGraph.getTopology().ensureVertexLabelExist("vertex", new HashMap<>() {{
        put("property1", PropertyDefinition.of(PropertyType.STRING));
        put("property2", PropertyDefinition.of(PropertyType.INTEGER));
    }});
    vertexLabel.ensureEdgeLabelExist("connectedTo", vertexLabel, new HashMap<>() {{
        put("edgeProperty", PropertyDefinition.of(PropertyType.DOUBLE));
    }});
    sqlgGraph.tx().commit();

    for (int i = 0; i < iterations; i++) {
        executorService.submit(() -> {
            try {
                Random random = new Random();
                sqlgGraph.tx().begin();

                Vertex vertexA = sqlgGraph.addVertex();
                Vertex vertexB = sqlgGraph.addVertex();
                Edge edge = vertexA.addEdge("connectedTo", vertexB);

                vertexA.property("property1", "value" + random.nextInt(100));
                vertexA.property("property2", random.nextInt(100));
                vertexB.property("property1", "value" + random.nextInt(100));
                vertexB.property("property2", random.nextInt(100));
                edge.property("edgeProperty", random.nextDouble());

                sqlgGraph.tx().commit();
            } catch (Exception e) {
                sqlgGraph.tx().rollback();
                LOGGER.error("Error during graph population", e);
            }
        });
    }
}
