import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;

public class CommandLineChecker {

    private static final String COMMAND = "your_command_here"; // Replace with your command
    private static final String PATTERN = "your_pattern_here"; // Replace with the pattern to check
    private static final long SLEEP_TIME = 1000; // Time to sleep in milliseconds

    public boolean checkForPattern() throws IOException, InterruptedException {
        boolean patternFound = false;

        while (true) {
            Process process = Runtime.getRuntime().exec(COMMAND);
            process.waitFor();
            InputStream is = process.getInputStream();
            InputStreamReader isr = new InputStreamReader(is);
            BufferedReader buff = new BufferedReader(isr);
            String line;
            patternFound = false;

            while ((line = buff.readLine()) != null) {
                if (line.contains(PATTERN)) {
                    patternFound = true;
                    break;
                }
            }

            if (!patternFound) {
                break; // Exit loop if pattern is not found
            }

            Thread.sleep(SLEEP_TIME); // Sleep before checking again
        }

        return patternFound;
    }

    public static void main(String[] args) {
        CommandLineChecker checker = new CommandLineChecker();
        try {
            boolean result = checker.checkForPattern();
            System.out.println("Pattern found: " + result);
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }
}
