import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.spec.IvParameterSpec;
import java.security.SecureRandom;
import java.util.Base64;

public class AesEncryption {

    public static void main(String[] args) {
        if (args.length < 2) {
            System.out.println("Usage: java AesEncryption <keySizeInBits> <messageToEncrypt>");
            return;
        }

        int keySize = Integer.parseInt(args[0]);
        String message = args[1];

        if (keySize < 128 || keySize % 8 != 0) {
            System.out.println("Invalid key size. Key size must be a multiple of 8 and greater than or equal to 128 bits.");
            return;
        }

        try {
            KeyGenerator keyGen = KeyGenerator.getInstance("AES");
            keyGen.init(keySize);
            SecretKey key = keyGen.generateKey();

            byte[] keyBytes = key.getEncoded();
            System.out.println("Generated key: " + bytesToHex(keyBytes));

            Cipher cipher = Cipher.getInstance("AES/CTR/NoPadding");
            IvParameterSpec iv = new IvParameterSpec(new byte[16]); // 16 bytes IV
            SecureRandom random = new SecureRandom();
            byte[] ivBytes = iv.getIV();
            random.nextBytes(ivBytes);

            cipher.init(Cipher.ENCRYPT_MODE, key, iv);

            byte[] messageBytes = message.getBytes();
            byte[] encryptedBytes = new byte[cipher.getOutputSize(messageBytes.length)];

            int encryptedLength = cipher.update(messageBytes, 0, messageBytes.length, encryptedBytes, 0).length;
            encryptedLength += cipher.doFinal(encryptedBytes, encryptedLength).length;

            System.out.println("Encrypted message: " + bytesToHex(encryptedBytes));

        } catch (Exception e) {
            System.out.println("Error: " + e.getMessage());
        }
    }

    private static String bytesToHex(byte[] bytes) {
        return Base64.getEncoder().encodeToString(bytes);
    }
}
