import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class DateRangeUtil {

    public String getDateRangeWithHash(String dateRange) throws NoSuchAlgorithmException {
        String[] dates = dateRange.split("/");
        if (dates.length != 2) {
            throw new IllegalArgumentException("Invalid date range format. Expected 'startDate/endDate'.");
        }

        String startDate = dates[0];
        String endDate = dates[1];

        String interval = startDate + "/" + endDate;
        String hash = hashString(dateRange);

        return hash + interval;
    }

    private String hashString(String input) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] hashBytes = digest.digest(input.getBytes());
        StringBuilder hexString = new StringBuilder();

        for (byte b : hashBytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }

        return hexString.toString();
    }
}
