public class KijiDataRequestSerializer {

    public byte[] serializeRequest(KijiDataRequest request) throws IOException {
        ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
        try (ObjectOutputStream objectOutputStream = new ObjectOutputStream(byteArrayOutputStream)) {
            objectOutputStream.writeObject(request);
        }
        return byteArrayOutputStream.toByteArray();
    }

    public boolean compareRequests(KijiDataRequest originalRequest) throws IOException, ClassNotFoundException {
        byte[] serializedRequest = serializeRequest(originalRequest);

        KijiDataRequest deserializedRequest;
        try (ObjectInputStream objectInputStream = new ObjectInputStream(new ByteArrayInputStream(serializedRequest))) {
