import java.io.*;

public class SerializedObject<T> {

    public ByteArrayOutputStream serialize(T object) {
        if (object == null) {
            throw new IllegalArgumentException("Input object cannot be null.");
        }

        try {
            ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
            ObjectOutputStream objectOutputStream = new ObjectOutputStream(byteArrayOutputStream);

            objectOutputStream.writeObject(object);
            objectOutputStream.flush();

            return byteArrayOutputStream;
        } catch (IOException e) {
            throw new RuntimeException("Failed to serialize object.", e);
        }
    }

    @SuppressWarnings("unchecked")
    public <SERIALIZABLE_T extends Serializable & T> T deserialize(ByteArrayOutputStream byteArrayOutputStream) {
        if (byteArrayOutputStream == null) {
            throw new IllegalArgumentException("ByteArrayOutputStream cannot be null.");
        }

        try {
            ObjectInputStream objectInputStream = new ObjectInputStream(new ByteArrayInputStream(byteArrayOutputStream.toByteArray()));
            SERIALIZABLE_T deserializedObject = (SERIALIZABLE_T) objectInputStream.readObject();
            return deserializedObject;
        } catch (IOException | ClassNotFoundException e) {
            throw new RuntimeException("Failed to deserialize object.", e);
        }
    }
}
