import java.io.*;
import java.util.Hashtable;
import java.util.List;
import java.util.ArrayList;

public class FileDataFilter {
    public static void main(String[] args) {
        String directoryPath = "path/to/directory"; // Specify the directory path
        String dataType = "specificDataType"; // Specify the type of data to filter
        List<String> filteredFiles = new ArrayList<>();
        Hashtable<String, Object> dataStore = new Hashtable<>();

        File dir = new File(directoryPath);
        if (dir.isDirectory()) {
            File[] files = dir.listFiles();
            if (files != null) {
                for (File file : files) {
                    if (file.isFile()) {
                        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
                            Object data = ois.readObject();
                            if (data instanceof YourDataType && ((YourDataType) data).getType().equals(dataType)) {
                                filteredFiles.add(file.getName());
                                dataStore.put(file.getName(), data);
                            }
                        } catch (FileNotFoundException e) {
                            System.err.println("File not found: " + file.getName());
                        } catch (ClassNotFoundException e) {
                            System.err.println("Class not found for file: " + file.getName());
                        } catch (IOException e) {
                            System.err.println("IOException for file: " + file.getName());
                        }
                    }
                }
            }
        }

        System.out.println("Filtered files containing specified data type:");
        for (String fileName : filteredFiles) {
            System.out.println(fileName);
        }
    }
}

class YourDataType implements Serializable {
    private String type;

    public YourDataType(String type) {
        this.type = type;
    }

    public String getType() {
        return type;
    }
}
