public class MapSerializer {

    public static void serializeMap(Map<String, Object> map, ObjectOutputStream out) throws IOException {
        out.writeObject(map);
    }

    public static Map<String, Object> deserializeMap(ObjectInputStream in) throws IOException, ClassNotFoundException {
        return (Map<String, Object>) in.readObject();
    }

    public static void main(String[] args) {
