import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class FileHashUtil {

    public static String calculateSHA1(File file) throws IOException, NoSuchAlgorithmException {
        MessageDigest sha1 = MessageDigest.getInstance("SHA-1");
        try (FileInputStream fis = new FileInputStream(file)) {
            byte[] dataBuffer = new byte[1048576]; // 1 MB buffer
            int bytesRead;
            while ((bytesRead = fis.read(dataBuffer)) != -1) {
                sha1.update(dataBuffer, 0, bytesRead);
            }
        }
        StringBuilder hexString = new StringBuilder();
        for (byte b : sha1.digest()) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }
}
