import org.apache.mina.core.filterchain.IoFilter;
import org.apache.mina.transport.socket.nio.NioSocketConnector;
import org.apache.mina.core.session.IoSession;
import org.apache.mina.filter.executor.ExecutorFilter;
import org.apache.mina.filter.logging.LoggingFilter;
import org.apache.mina.filter.ssl.SslFilter;

import java.net.InetSocketAddress;
import java.net.URI;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class SocketConnectionManager {

    public IoSession setupSocketConnection(URI uri, int timeout, List<IoFilter> filters, int maxPoolSize) throws Exception {
        String host = uri.getHost();
        int port = uri.getPort();

        InetSocketAddress address = new InetSocketAddress(host, port);
        NioSocketConnector connector = new NioSocketConnector();

        // Create worker pool executor
        ExecutorService workerPool = Executors.newFixedThreadPool(maxPoolSize);
        connector.getFilterChain().addLast("threadPool", new ExecutorFilter(workerPool));
        connector.getFilterChain().addLast("logger", new LoggingFilter());

        // Add custom filters
        for (IoFilter filter : filters) {
            connector.getFilterChain().addLast(filter.getClass().getSimpleName(), filter);
        }

        connector.setConnectTimeoutMillis(timeout);
        IoSession session = connector.connect(address).awaitUninterruptibly().getSession();

        return session;
    }
}
