    private HmmDecoder decoder;

    public PartOfSpeechTagger(String modelPath) throws FileNotFoundException, IOException, ClassNotFoundException {
        FileInputStream fileIn = new FileInputStream(modelPath);
        ObjectInputStream objIn = new ObjectInputStream(fileIn);
        hmm = (HiddenMarkovModel) objIn.readObject();
        decoder = new HmmDecoder(hmm);
        objIn.close();
