import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class MacAddressRetriever {

    public List<String> getMacAddresses() {
        List<String> macAddresses = new ArrayList<>();
        String OS = System.getProperty("os.name").toLowerCase();
        String[] cmd;

        if (OS.contains("win")) {
            cmd = new String[]{"getmac"};
        } else {
            cmd = new String[]{"ifconfig"};
        }

        try {
            Process p = Runtime.getRuntime().exec(cmd);
            p.waitFor();
            BufferedReader reader = new BufferedReader(new InputStreamReader(p.getInputStream()));
            String line;
            Pattern macPattern;

            if (OS.contains("win")) {
                macPattern = Pattern.compile("([0-9a-fA-F]{2}[-:]){5}([0-9a-fA-F]{2})");
            } else {
                macPattern = Pattern.compile("([0-9a-fA-F]{2}[:-]){5}([0-9a-fA-F]{2})");
            }

            while ((line = reader.readLine()) != null) {
                Matcher matcher = macPattern.matcher(line);
                while (matcher.find()) {
                    macAddresses.add(matcher.group());
                }
            }
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }

        return macAddresses;
    }

    public static void main(String[] args) {
        MacAddressRetriever retriever = new MacAddressRetriever();
        List<String> macAddresses = retriever.getMacAddresses();
        System.out.println("MAC Addresses: " + macAddresses);
    }
}
