import java.io.*;
import java.net.HttpURLConnection;
import java.net.URL;
import java.nio.file.Files;
import java.nio.file.Path;

public class DictionaryDownloader {

    public static void main(String[] args) {
        String url = "http://example.com/dictionary.txt"; // Replace with the actual URL
        String existingDictionaryPath = "path/to/existing/dictionary.txt"; // Replace with the actual path

        try {
            Path tempFile = downloadDictionary(url);
            replaceExistingDictionary(tempFile, existingDictionaryPath);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static Path downloadDictionary(String urlString) throws IOException {
        URL url = new URL(urlString);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");

        if (connection.getResponseCode() != HttpURLConnection.HTTP_OK) {
            throw new IOException("Failed to download file: " + connection.getResponseMessage());
        }

        Path tempFile = Files.createTempFile("dictionary", ".txt");
        try (InputStream in = connection.getInputStream();
             OutputStream out = new FileOutputStream(tempFile.toFile())) {
            byte[] buffer = new byte[4096];
            int bytesRead;
            while ((bytesRead = in.read(buffer)) != -1) {
                out.write(buffer, 0, bytesRead);
            }
        }

        connection.disconnect();
        return tempFile;
    }

    private static void replaceExistingDictionary(Path tempFile, String existingDictionaryPath) throws IOException {
        Files.move(tempFile, Path.of(existingDictionaryPath), java.nio.file.StandardCopyOption.REPLACE_EXISTING);
    }
}
