import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

public class HashGenerator {

    private static final Map<String, String> algorithms = new HashMap<>();

    static {
        algorithms.put("md5", "MD5");
        algorithms.put("sha1", "SHA-1");
        algorithms.put("sha256", "SHA-256");
        algorithms.put("sha384", "SHA-384");
        algorithms.put("sha512", "SHA-512");
    }

    public static String generateHash(String input, String algorithm) {
        String algo = algorithms.get(algorithm.toLowerCase());
        if (algo == null) {
            return "Invalid algorithm name.";
        }

        try {
            MessageDigest digest = MessageDigest.getInstance(algo);
            byte[] hashBytes = digest.digest(input.getBytes());
            StringBuilder hashString = new StringBuilder();
            for (byte b : hashBytes) {
                hashString.append(String.format("%02x", b));
            }
            return hashString.toString();
        } catch (NoSuchAlgorithmException e) {
            return "Error: " + e.getMessage();
        }
    }

    public static void main(String[] args) {
        String input = "Hello, World!";
        String algorithm = "SHA-256";

        String hashValue = generateHash(input, algorithm);
        System.out.println("Hash value: " + hashValue);
    }
}
