import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.InputStream;
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class MD5Generator {

    public void generateMD5(String filePath) {
        File sourceFile = new File(filePath);
        File md5File = new File(sourceFile.getAbsolutePath() + ".md5");

        try (InputStream stream = new FileInputStream(sourceFile);
             FileOutputStream fos = new FileOutputStream(md5File)) {

            System.out.println("Generating MD5 for " + sourceFile.getName() + "...");
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] dataBytes = new byte[1024];
            int nread;

            while ((nread = stream.read(dataBytes)) != -1) {
                md.update(dataBytes, 0, nread);
            }

            byte[] md5Bytes = md.digest();
            StringBuilder sb = new StringBuilder();
            for (byte b : md5Bytes) {
                sb.append(String.format("%02x", b));
            }

            fos.write(sb.toString().getBytes());
            System.out.println("MD5 hash written to " + md5File.getName());
        } catch (IOException | NoSuchAlgorithmException e) {
            throw new RuntimeException("Error generating MD5 hash", e);
        }
    }
}
