import org.apache.commons.codec.binary.Hex;

public class UserDAOService {

    private UserDAO userDAO;

    public UserDAOService(UserDAO userDAO) {
        this.userDAO = userDAO;
    }

    public void createOrUpdateUser(String userName, String url, boolean trustedAlways, String algorithm) throws IdentityProviderException {
        User user = new User();

        try {
            user.setUserName(userName);
            user.setUrl(url);
            user.setTrustedAlways(trustedAlways);

            MessageDigest digest = MessageDigest.getInstance(algorithm);
            byte[] hash = digest.digest((userName + ":" + url).getBytes());
