import java.io.*;
import java.net.Socket;

public class RemoteMethodCaller {

    private String serverAddress;
    private int serverPort;

    public RemoteMethodCaller(String serverAddress, int serverPort) {
        this.serverAddress = serverAddress;
        this.serverPort = serverPort;
    }

    public Object callMethod(String methodName, Object... params) throws IOException, ClassNotFoundException {
        try (Socket socket = new Socket(serverAddress, serverPort);
             ObjectOutputStream out = new ObjectOutputStream(socket.getOutputStream());
             ObjectInputStream in = new ObjectInputStream(socket.getInputStream())) {

            // Create request object
            Request request = new Request(methodName, params);
            out.writeObject(request);
            out.flush();

            // Read response
            Response response = (Response) in.readObject();
            if (response.isError()) {
                throw new RuntimeException("Error calling method: " + response.getErrorMessage());
            }

            return response.getResult();
        }
    }

    private static class Request implements Serializable {
        private String methodName;
        private Object[] params;

        public Request(String methodName, Object[] params) {
            this.methodName = methodName;
            this.params = params;
        }
    }

    private static class Response implements Serializable {
        private boolean error;
        private String errorMessage;
        private Object result;

        public boolean isError() {
            return error;
        }

        public String getErrorMessage() {
            return errorMessage;
        }

        public Object getResult() {
            return result;
        }
    }
}
