public String calculateETag(Change change) {
    CurrentUser user = control.getCurrentUser();
    Hasher hasher = Hashing.md5().newHasher();

    // Include last updated timestamp, row version, and account ID
    hasher.putLong(change.getLastUpdated().getMillis());
    hasher.putInt(change.getRowVersion());
    hasher.putString(user.getAccountId().toString(), StandardCharsets.UTF_8);

    // Iterate over project revisions and include revision IDs
    ProjectState projectState = change.getProjectState();
    for (Revision revision : projectState.getRevisions()) {
        hasher.putString(revision.getId().toString(), StandardCharsets.UTF_8);
    }

    return hasher.hash().toString();
}
