import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SocketChannel;
import java.nio.channels.ReadableByteChannel;

public class RemoteHostConnector {
    private SocketChannel socketChannel;
    private ByteBuffer messageBuffer;

    public RemoteHostConnector(ByteBuffer messageBuffer) {
        this.messageBuffer = messageBuffer;
    }

    public void connectAndSend(String host, int port) throws IOException {
        socketChannel = SocketChannel.open();
        socketChannel.setOption(java.net.StandardSocketOptions.SO_KEEPALIVE, true);
        socketChannel.connect(new InetSocketAddress(host, port));

        sendMessage();
    }

    private void sendMessage() throws IOException {
        messageBuffer.flip();
        while (messageBuffer.hasRemaining()) {
            socketChannel.write(messageBuffer);
        }
        messageBuffer.clear();
    }

    public void flush() throws IOException {
        sendMessage();
    }

    public void close() throws IOException {
        if (socketChannel != null && socketChannel.isOpen()) {
            socketChannel.close();
        }
    }
}
