import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import org.apache.commons.compress.compressors.lzop.LzopCompressorOutputStream;

public class FileCompressor {

    public static String compressFile(String filePath, int compressionLevel) throws IOException, NoSuchAlgorithmException {
        File inputFile = new File(filePath);
        File compressedFile = new File(inputFile.getAbsolutePath() + ".lzo");

        try (FileInputStream fis = new FileInputStream(inputFile);
             FileOutputStream fos = new FileOutputStream(compressedFile);
             LzopCompressorOutputStream lzopOut = new LzopCompressorOutputStream(fos)) {

            byte[] buffer = new byte[4096];
            int length;
            while ((length = fis.read(buffer)) != -1) {
                lzopOut.write(buffer, 0, length);
            }
        }

        return calculateMD5(compressedFile);
    }

    private static String calculateMD5(File file) throws IOException, NoSuchAlgorithmException {
        MessageDigest md5 = MessageDigest.getInstance("MD5");
        try (FileInputStream fis = new FileInputStream(file)) {
            byte[] buffer = new byte[4096];
            int length;
            while ((length = fis.read(buffer)) != -1) {
                md5.update(buffer, 0, length);
            }
        }
        StringBuilder sb = new StringBuilder();
        for (byte b : md5.digest()) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
