import akka.util.Timeout;
import java.net.InetSocketAddress;
import java.util.concurrent.TimeUnit;

public class DiscoveryActor extends AbstractActor {
    private final ActorRef remoteRef;
    private final InetSocketAddress remoteAddress;
    private final int discoveryPort;
    private final ActorSystem system;
    private final ActorRef tcp = Tcp.get(system).manager();

    public DiscoveryActor(String remoteIp, int discoveryPort) {
        this.remoteAddress = new InetSocketAddress(remoteIp, 0);
        this.discoveryPort = discoveryPort;
        this.system = ActorSystem.create("DiscoverySystem");

        getContext().system().log().info("Creating DiscoveryActor...");

        final Props props = Props.create(DiscoveryActor.class, () -> new DiscoveryActor(remoteIp, discoveryPort));
        getContext().actorOf(props, "discoveryActor");

        getContext().system().log().info("Sending discovery message to remote address...");

        tcp.tell(TcpMessage.connect(remoteAddress, null, null, new Timeout(CONNECT_TIMEOUT, TimeUnit.SECONDS), false), getSelf());

        receive(message -> {
            if (message instanceof Tcp.Connected) {
                getContext().system().log().info("Connected to remote address.");
                final ActorRef connection = getContext().actorOf(Props.create(DiscoverySender.class, remoteAddress, discoveryPort), "connection");
                getSender().tell(Status.SUCCESS, getSelf());
                connection.tell(new DiscoveryMessage(), getSelf());
            } else if (message instanceof Tcp.CommandFailed) {
                getContext().system().log().error("Failed to connect to remote address.");
                getSender().tell(Status.FAILURE, getSelf());
            }
        });
    }

    private static final int CONNECT_TIMEOUT = 5000;

