import java.util.List;

public class ProcessExecutor {

    public static boolean executeProcess(String executablePath, List<String> arguments) {
        Process process = null;
        try {
            // Build command
            String[] command = new String[arguments.size() + 1];
            command[0] = executablePath;
            for (int i = 0; i < arguments.size(); i++) {
                command[i + 1] = arguments.get(i);
            }

            // Start the process
            process = Runtime.getRuntime().exec(command);
            logExecutionDetails(executablePath, arguments);

            // Monitor process status
            Watchdog watchdog = new Watchdog(process);
            new Thread(watchdog).start();

            return true;
        } catch (Exception e) {
            System.err.println("Error starting process: " + e.getMessage());
            return false;
        } finally {
            if (process != null) {
                try {
                    process.waitFor();
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        }
    }

    private static void logExecutionDetails(String executablePath, List<String> arguments) {
        System.out.println("Executing: " + executablePath + " with arguments: " + String.join(" ", arguments));
    }

    private static class Watchdog implements Runnable {
        private final Process process;

        public Watchdog(Process process) {
            this.process = process;
        }

        @Override
        public void run() {
            try {
                int exitCode = process.waitFor();
                System.out.println("Process exited with code: " + exitCode);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                System.err.println("Watchdog interrupted.");
            }
        }
    }
}
