import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class CommandExecutor {

    public String executeCommand(String command, boolean waitForCompletion) {
        StringBuilder outputBuilder = new StringBuilder();
        Process process = null;

        try {
            process = Runtime.getRuntime().exec(command);
            if (waitForCompletion) {
                process.waitFor();
            }

            try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    outputBuilder.append(line).append("\n");
                }
            }

            // Optionally read error stream
            try (BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {
                String line;
                while ((line = errorReader.readLine()) != null) {
                    outputBuilder.append(line).append("\n");
                }
            }

        } catch (IOException e) {
            outputBuilder.append("IOException: ").append(e.getMessage()).append("\n");
        } catch (InterruptedException e) {
            outputBuilder.append("InterruptedException: ").append(e.getMessage()).append("\n");
        } finally {
            if (process != null) {
                process.destroy();
            }
        }

        return outputBuilder.toString().trim();
    }
}
