import java.security.NoSuchAlgorithmException;

public class HashUtil {

    public static long getHash(String input, String hashFunction) {
        try {
            MessageDigest digest = MessageDigest.getInstance(hashFunction);
            byte[] hashBytes = digest.digest(input.getBytes());
            return bytesToLong(hashBytes);
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalArgumentException("Invalid hash function: " + hashFunction, e);
        }
    }

    private static long bytesToLong(byte[] bytes) {
        long result = 0;
        for (int i = 0; i < Math.min(bytes.length, Long.BYTES); i++) {
            result = (result << 8) | (bytes[i] & 0xFF);
        }
        return result;
    }

    public static void main(String[] args) {
        String input = "Hello, World!";
        long hashValue = getHash(input, "SHA-256");
        System.out.println("Hash value: " + hashValue);
    }
