import java.io.FileInputStream;
import java.io.ObjectInputStream;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

public class ObjectLoader {
    private static final Logger logger = Logger.getLogger(ObjectLoader.class.getName());

    public static <T> List<T> loadObjectsFromFile(String path, Class<T> clazz) {
        List<T> objects = new ArrayList<>();
        ObjectInputStream ois = null;
        try {
            ois = new ObjectInputStream(new FileInputStream(path));
            while (true) {
                try {
                    T obj = clazz.cast(ois.readObject());
                    objects.add(obj);
                } catch (EOFException e) {
                    break; // End of file reached
                }
            }
        } catch (Exception e) {
            logger.warning("在从" + path + "加载对象时发生异常: " + e);
        } finally {
            if (ois != null) {
                try {
                    ois.close();
                } catch (IOException e) {
                    logger.warning("关闭ObjectInputStream时发生异常: " + e);
                }
            }
        }
        return objects;
    }
}
