                mostSigBits |= (hashBytes[i] & 0xff);
            }
            for (int i = 8; i < 16; i++) {
                leastSigBits <<= 8;
                leastSigBits |= (hashBytes[i] & 0xff);
            }
            return new UUID(mostSigBits, leastSigBits);
        } catch (NoSuchAlgorithmException e) {
            // Handle the exception (e.g., log it and return a default UUID)
