import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.ResultSet;
import java.sql.Statement;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import org.w3c.dom.Document;
import org.w3c.dom.NodeList;

public class DataExtractor {

    public static void main(String[] args) {
        if (args.length < 1) {
            System.err.println("Please provide at least one file path.");
            return;
        }

        for (String filePath : args) {
            File file = new File(filePath);
            if (file.exists()) {
                if (filePath.endsWith(".xml")) {
                    extractFromXML(file);
                } else if (filePath.endsWith(".sql")) {
                    extractFromSQL(filePath);
                } else {
                    System.err.println("Unsupported file format: " + filePath);
                }
            } else {
                System.err.println("File not found: " + filePath);
            }
        }
    }

    private static void extractFromXML(File file) {
        try {
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            DocumentBuilder builder = factory.newDocumentBuilder();
            Document document = builder.parse(file);
            document.getDocumentElement().normalize();

            NodeList nodeList = document.getElementsByTagName("*");
            System.out.println("Extracted XML Data from " + file.getName() + ":");
            for (int i = 0; i < nodeList.getLength(); i++) {
                System.out.println(nodeList.item(i).getNodeName() + ": " + nodeList.item(i).getTextContent());
            }
        } catch (Exception e) {
            System.err.println("Error processing XML file: " + file.getName());
            e.printStackTrace();
        }
    }

    private static void extractFromSQL(String filePath) {
        String url = "jdbc:sqlite:your_database.db"; // Update with your database URL
        try (Connection conn = DriverManager.getConnection(url);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery("SELECT * FROM your_table")) { // Update with your SQL query

            System.out.println("Extracted SQL Data from " + filePath + ":");
            while (rs.next()) {
                // Assuming the table has columns named 'column1' and 'column2'
                System.out.println("Column1: " + rs.getString("column1") + ", Column2: " + rs.getString("column2"));
            }
        } catch (Exception e) {
            System.err.println("Error processing SQL file: " + filePath);
            e.printStackTrace();
        }
    }
}
