import java.nio.charset.Charsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Map;

public byte[] getHashCode(Map<String, String> pathsMap, String moduleName, boolean createSymlinks, boolean createHeaderMap) {
    try {
        MessageDigest sha1 = MessageDigest.getInstance("SHA-1");
        byte[] coreKeyBytes = "coreKey".getBytes(Charsets.UTF_8);
        sha1.update(coreKeyBytes);

        byte[] symlinkStateValue;
        if (createSymlinks) {
            symlinkStateValue = "symlinks-enabled".getBytes(Charsets.UTF_8);
        } else {
            symlinkStateValue = "symlinks-disabled".getBytes(Charsets.UTF_8);
        }
        sha1.putInt(symlinkStateValue.length);
        sha1.putBytes(symlinkStateValue);

        byte[] hmapStateValue;
        if (createHeaderMap) {
            hmapStateValue = "hmap-enabled".getBytes(Charsets.UTF_8);
        } else {
            hmapStateValue = "hmap-disabled".getBytes(Charsets.UTF_8);
        }
        sha1.putInt(hmapStateValue.length);
        sha1.putBytes(hmapStateValue);

        if (moduleName != null) {
            byte[] moduleNameValue = moduleName.getBytes(Charsets.UTF_8);
            sha1.putInt(moduleNameValue.length);
            sha1.putBytes(moduleNameValue);
        }

        sha1.putInt(0);

        for (Map.Entry<String, String> entry : pathsMap.entrySet()) {
            byte[] keyBytes = entry.getKey().getBytes(Charsets.UTF_8);
            byte[] valueBytes = entry.getValue().getBytes(Charsets.UTF_8);
            sha1.putInt(keyBytes.length);
            sha1.putBytes(keyBytes);
            sha1.putInt(valueBytes.length);
            sha1.putBytes(valueBytes);
        }

        return sha1.digest();
    } catch (NoSuchAlgorithmException e) {
