import java.io.FileInputStream;
import java.io.FileNotFoundException;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.FileOutputStream;
import java.io.Serializable;

public class SingletonClass implements Serializable {
    private static SingletonClass instance;
    private static final String FILE_PATH = "singleton.ser";

    private SingletonClass() {
        // Private constructor to prevent instantiation
    }

    public static SingletonClass getInstance() {
        if (instance == null) {
            instance = load(FILE_PATH);
            if (instance == null) {
                instance = new SingletonClass();
                save(FILE_PATH, instance);
            }
        }
        return instance;
    }

    private static SingletonClass load(String path) {
        SingletonClass ret = null;
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(path))) {
            ret = (SingletonClass) ois.readObject();
        } catch (FileNotFoundException e) {
            // File not found, return null
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        }
        return ret;
    }

    private static void save(String path, SingletonClass instance) {
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(path))) {
            oos.writeObject(instance);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
