                       .append(entry.getValue()).append("\", ");
        }
        // Remove the last comma and space
        if (jsonBuilder.length() > 1) {
            jsonBuilder.setLength(jsonBuilder.length() - 2);
        }
        jsonBuilder.append("}");
        return jsonBuilder.toString();
    }
