public class ServiceManager {
    private boolean serviceRunning;
    private final Random random;
    private final Timer timer;

    public ServiceManager() {
        this.serviceRunning = false;
        this.random = new Random();
        this.timer = new Timer();
    }

    public void startService() {
        if (!serviceRunning) {
            serviceRunning = true;
            System.out.println("Service started.");
            scheduleStopService();
        } else {
            System.out.println("Service is already running.");
        }
    }

    public void stopService() {
        if (serviceRunning) {
            serviceRunning = false;
            System.out.println("Service stopped.");
            sendMessage("Service has been stopped.");
        } else {
            System.out.println("Service is not running.");
        }
    }

    private void scheduleStopService() {
        int delay = random.nextInt(5000) + 1000; // Random delay between 1 and 5 seconds
        timer.schedule(new TimerTask() {
            @Override
            public void run() {
                stopService();
                startService(); // Restart the service after stopping
            }
        }, delay);
    }

    private void sendMessage(String message) {
