import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.net.HttpURLConnection;
import java.net.URL;

public class FileUploader {

    public static void main(String[] args) {
        // Example usage
        String filePath = "path/to/your/file.txt";
        String serverUrl = "http://example.com/upload";
        try {
            boolean success = uploadFile(filePath, serverUrl);
            System.out.println("Upload successful: " + success);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static boolean uploadFile(String filePath, String serverUrl) throws IOException {
        File file = new File(filePath);
        if (!file.exists()) {
            throw new IOException("File not found: " + filePath);
        }

        int maxRetries = 3;
        for (int attempt = 1; attempt <= maxRetries; attempt++) {
            HttpURLConnection connection = null;
            try {
                FileInputStream fileInputStream = new FileInputStream(file);
                URL url = new URL(serverUrl);
                connection = (HttpURLConnection) url.openConnection();
                connection.setDoOutput(true);
                connection.setRequestMethod("POST");
                connection.setRequestProperty("Content-Type", "application/octet-stream");
                connection.setRequestProperty("Content-Length", String.valueOf(file.length()));

                // Upload the file
                byte[] buffer = new byte[4096];
                int bytesRead;
                while ((bytesRead = fileInputStream.read(buffer)) != -1) {
                    connection.getOutputStream().write(buffer, 0, bytesRead);
                }
                fileInputStream.close();
                connection.getOutputStream().flush();

                // Check the response code
                int responseCode = connection.getResponseCode();
                if (responseCode == HttpURLConnection.HTTP_OK) {
                    return true; // Upload successful
                } else {
                    System.out.println("Upload failed with response code: " + responseCode);
                }
            } catch (IOException e) {
                System.out.println("Attempt " + attempt + " failed: " + e.getMessage());
                if (attempt == maxRetries) {
                    throw e; // Rethrow exception on final attempt
                }
            } finally {
                if (connection != null) {
                    connection.disconnect();
                }
            }
        }
        return false; // Upload failed after retries
    }
}
