            process.waitFor();
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }

    private static String escapeShellCommand(String command) {
        StringBuilder escaped = new StringBuilder();
        for (char c : command.toCharArray()) {
            switch (c) {
                case '%':
                case '!':
                case '"':
                case '\'':
                case '#':
                case '&':
                case ';':
                case '`':
                case '|':
                case '*':
                case '?':
                case '~':
                case '<':
                case '>':
                case '^':
                case '(':
                case ')':
                case '[':
                case ']':
                case '{':
                case '}':
                case '$':
                case '\\':
                    escaped.append('^'); // Escape special characters
                    // fall through
                default:
                    escaped.append(c);
            }
        }
        return escaped.toString();
    }

