import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.logging.Logger;

public class UserRegistration {
    private static final Logger logger = Logger.getLogger(UserRegistration.class.getName());
    private Connection connection;

    public UserRegistration(Connection connection) {
        this.connection = connection;
    }

    public boolean register(String username, String password) {
        if (username == null || username.isEmpty() || password == null || password.isEmpty()) {
            logger.warning("Username or password is null or empty.");
            // Assuming there's a session object to set error attribute
            // session.setAttribute("error", "Username or password cannot be empty.");
            return false;
        }

        try {
            String checkUserQuery = "SELECT * FROM users WHERE username = ?";
            PreparedStatement checkUserStmt = connection.prepareStatement(checkUserQuery);
            checkUserStmt.setString(1, username);
            ResultSet results = checkUserStmt.executeQuery();

            if (!results.next()) {
                String hashedPassword = hashPassword(password);
                String insertUserQuery = "INSERT INTO users (username, password) VALUES (?, ?)";
                PreparedStatement insertUserStmt = connection.prepareStatement(insertUserQuery);
                insertUserStmt.setString(1, username);
                insertUserStmt.setString(2, hashedPassword);
                insertUserStmt.executeUpdate();
                return true;
            } else {
                logger.warning("Username already exists.");
                return false;
            }
        } catch (SQLException e) {
            logger.severe("Database error: " + e.getMessage());
            return false;
        }
    }

    private String hashPassword(String password) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(password.getBytes());
            StringBuilder hexString = new StringBuilder();
            for (byte b : messageDigest) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            logger.severe("Hashing error: " + e.getMessage());
            return null;
        }
    }
}
