import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Formatter;

public class HashGenerator {

    public static String generateHash(double seed) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            md.update(Double.toString(seed).getBytes());
            byte[] digest = md.digest();
            return formatHash(digest);
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    private static String formatHash(byte[] hash) {
        Formatter formatter = new Formatter();
        for (byte b : hash) {
            formatter.format("%02x", b);
        }
        String result = formatter.toString();
        formatter.close();
        return result.substring(0, 32); // Return only the first 32 characters
    }

    public static void main(String[] args) {
        double seed = 123.456;
        String hash = generateHash(seed);
        System.out.println("Hash: " + hash);
    }
}
