import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

public class IntervalMerger {

    public static String mergeIntervals(List<Segment> segments) {
        if (segments.isEmpty()) {
            return "";
        }

        // Sort segments by start time
        Collections.sort(segments, Comparator.comparing(Segment::getStart));

        LocalDateTime mergedStart = segments.get(0).getStart();
        LocalDateTime mergedEnd = segments.get(0).getEnd();

        for (Segment segment : segments) {
            if (segment.getStart().isBefore(mergedEnd) || segment.getStart().isEqual(mergedEnd)) {
                // Overlapping intervals, merge them
                mergedEnd = segment.getEnd().isAfter(mergedEnd) ? segment.getEnd() : mergedEnd;
            } else {
                // No overlap, finalize the current interval
                break;
            }
        }

        return mergedStart + "-" + mergedEnd;
    }

    public static class Segment {
        private LocalDateTime start;
        private LocalDateTime end;

        public Segment(LocalDateTime start, LocalDateTime end) {
            this.start = start;
            this.end = end;
        }

        public LocalDateTime getStart() {
            return start;
        }

        public LocalDateTime getEnd() {
            return end;
        }
    }
}
