public static String GenerateHashedString(String input, String namespace)
{
    // Create SHA1 object
    SHA1 sha = new SHA1CryptoServiceProvider();

    // Convert input string to byte array
    var enc = new ASCIIEncoding();
    var inputData = enc.GetBytes(input);

    // Compute hash for the input string
    var inputHashed = sha.ComputeHash(inputData);
    var inputHash = BitConverter.ToString(inputHashed).Replace("-", "").ToLower();

    // Compute hash for the namespace
    var namespaceData = enc.GetBytes(namespace);
    var namespaceHashed = sha.ComputeHash(namespaceData);
    var namespaceHash = BitConverter.ToString(namespaceHashed).Replace("-", "").ToLower();

    // Define prefix
    String prefix = "prefix";

    // Return formatted string
    return $"{prefix}:{namespaceHash}:{inputHash}";
}
