const asyncReduce = (array, initialValue, callback) => {
    return new Promise((resolve, reject) => {
        let accumulator = initialValue;
        let index = 0;

        const processNext = () => {
            if (index < array.length) {
                callback(accumulator, array[index], (err, result) => {
                    if (err) {
                        return reject(err);
                    }
                    accumulator = result;
                    index++;
                    processNext();
                });
            } else {
                resolve(accumulator);
            }
        };

        processNext();
    });
};

