const { exec } = require('child_process');

/**
 * Execute a shell command and output the result to the browser.
 *
 * @param {String} command - The shell command to execute
 * @param {Function} callback - The callback function to handle the output
 */
function runShellCommand(command, callback) {
  exec(command, (err, stdout, stderr) => {
    if (err) {
      let output = 'Error executing command';
      if (err.code) {
        output += ` (code: ${err.code})`;
      }
      if (err.signal) {
        output += ` (signal: ${err.signal})`;
      }
      callback(output);
      return;
    }
    callback(stdout || stderr);
  });
}

