const fs = require('fs');
const path = require('path');

function validateAndCreateDirTree(fsObject, dirPath, options) {
    const { createIfMissing, validate } = options;

    function traverse(currentPath) {
        if (validate) {
            try {
                const stats = fsObject.statSync(currentPath);
                if (!stats.isDirectory()) {
                    return false;
                }
            } catch (err) {
                if (err.code !== 'ENOENT') {
                    return false;
                }
            }
        }

        if (createIfMissing) {
            try {
                if (!fsObject.existsSync(currentPath)) {
                    fsObject.mkdirSync(currentPath, { recursive: true });
                }
            } catch (err) {
                return false;
            }
        }

        const entries = fsObject.readdirSync(currentPath);
        for (const entry of entries) {
            const entryPath = path.join(currentPath, entry);
            if (!traverse(entryPath)) {
                return false;
            }
        }

        return true;
    }

    return traverse(dirPath);
}
