#include <stdint.h>
#include <stdio.h>
#include <string.h>

#define OFPAT_SET_TP_DST 0x0A
#define OFP_ACTION_TP_PORT_LEN 8

typedef struct {
    uint16_t type;
    uint16_t len;
} ofp_action_header;

typedef struct {
    char *error;
    int code;
} error_dict;

typedef struct {
    uint16_t type;
    // Additional fields can be added here
} action_dict;

typedef struct {
    action_dict action;
    int updated_offset;
} result_dict;

result_dict parse_openflow_action(uint8_t *buffer, int offset) {
    result_dict result;
    ofp_action_header *header = (ofp_action_header *)(buffer + offset);

    if (header->len != OFP_ACTION_TP_PORT_LEN) {
        result.action.type = 0; // Indicate error
        result.updated_offset = offset;
        result.error = (char *)malloc(256);
        snprintf(result.error, 256, "OFPAT_SET_TP_DST action at offset %d has invalid length (%d).", offset, header->len);
        result.code = 1; // Error code for bad length
        return result;
    }

    result.action.type = header->type;
    result.updated_offset = offset + header->len;
    return result;
}
