const fs = require('fs');
const path = require('path');
const less = require('less');

function compileLessFiles(dir) {
    let compiledFiles = {};

    function searchDirectory(currentDir) {
        const files = fs.readdirSync(currentDir);

        files.forEach(file => {
            const filePath = path.join(currentDir, file);
            const stats = fs.lstatSync(filePath);

            if (stats.isDirectory()) {
                searchDirectory(filePath);
            } else if (path.extname(file) === '.less') {
                const cssFilePath = filePath.replace(/\.less$/, '.css');
                const lessContent = fs.readFileSync(filePath, 'utf8');

                less.render(lessContent)
                    .then(output => {
                        fs.writeFileSync(cssFilePath, output.css);
                        compiledFiles[cssFilePath] = filePath;
                    })
                    .catch(err => {
                        console.error(`Error compiling ${filePath}:`, err);
                    });
            }
        });
    }

    searchDirectory(dir);
    return compiledFiles;
}

