const fs = require('fs');
const path = require('path');
const sass = require('sass');
const ts = require('typescript');
const _ = require('lodash');

// Function to delete a file
function deleteFile(filePath) {
    fs.unlink(filePath, (err) => {
        if (err) {
            console.error(`Error deleting file: ${filePath}`, err);
        } else {
            console.log(`Deleted file: ${filePath}`);
        }
    });
}

// Function to insert text into a file
function insertTextIntoFile(filePath, text) {
    fs.appendFile(filePath, text, (err) => {
        if (err) {
            console.error(`Error inserting text into file: ${filePath}`, err);
        } else {
            console.log(`Inserted text into file: ${filePath}`);
        }
    });
}

// Function to compile Sass to CSS
function compileSass(inputPath, outputPath) {
    const result = sass.compile(inputPath);
    fs.writeFileSync(outputPath, result.css);
