function RandomStar(canvas) {
    var context = canvas.getContext('2d');

    function Star() {
        this.x = Math.random() * canvas.width;
        this.y = Math.random() * canvas.height;
        this.vx = (Math.random() - 0.5) * 2; // Random velocity between -1 and 1
        this.vy = (Math.random() - 0.5) * 2; // Random velocity between -1 and 1
        this.radius = Math.random() * 5 + 1; // Random radius between 1 and 6
    }

