function depthFirstSearch(grid, startX, startY, maxNodes) {
    const rows = grid.length;
    const cols = grid[0].length;
    let visitedCount = 0;

    function dfs(x, y) {
        if (x < 0 || x >= rows || y < 0 || y >= cols || grid[x][y].state === 'visited') {
            return;
        }

        grid[x][y].state = 'visited';
        visitedCount++;

        if (visitedCount < maxNodes) {
            plantRandomNode();
        }

        // Explore neighbors (up, down, left, right)
        dfs(x - 1, y);
        dfs(x + 1, y);
        dfs(x, y - 1);
        dfs(x, y + 1);
    }

    function plantRandomNode() {
        let randomX, randomY;
        do {
            randomX = Math.floor(Math.random() * rows);
            randomY = Math.floor(Math.random() * cols);
        } while (grid[randomX][randomY].state === 'visited');

        grid[randomX][randomY] = {
            x: randomX,
            y: randomY,
            value: Math.floor(Math.random() * 100), // Random value between 0 and 99
            state: 'unvisited'
        };
    }

    dfs(startX, startY);
}
