const fs = require('fs');

function loadDataFromFiles(files, callback) {
    const contents = {};
    let filesProcessed = 0;

    for (const id in files) {
        const path = files[id];

        fs.stat(path, (err, stat) => {
            if (err) {
                return callback(err);
            }

            if (stat.isFile()) {
                fs.readFile(path, (err, data) => {
                    if (err) {
                        return callback(err);
                    }
                    contents[id] = data;
                    filesProcessed++;

                    if (filesProcessed === Object.keys(files).length) {
