function reformatString(input, separator) {
    // Remove non-digit characters and create an array of digits
    const digits = input.match(/\d+/g);
    if (!digits) return '';

    // Join the digits into a single string
    const digitString = digits.join('');

    // Use a regular expression to group digits and join with the specified separator
    return digitString.replace(/(\d{1,3})(?=(\d{3})+(?!\d))/g, `$1${separator}`);
}

