```javascript
const canvas = document.getElementById('canvas');
const ctx = canvas.getContext('2d');
let particles = [];
const ANIMATION_SECONDS = 1; // Duration of animation in seconds
let time = 0;

class Particle {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.nextX = x;
        this.nextY = y;
        this.dx = 0;
        this.dy = 0;
    }

    update() {
        this.x += this.dx;
        this.y += this.dy;
    }

    render() {
        ctx.fillStyle = 'black';
        ctx.beginPath();
        ctx.arc(this.x, this.y, 5, 0, Math.PI * 2);
        ctx.fill();
    }
}

function initParticles(num) {
    for (let i = 0; i < num; i++) {
        particles.push(new Particle(Math.random() * canvas.width, Math.random() * canvas.height));
    }
}

function updateParticles() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    particles.forEach(p => {
        if (Math.random() < 0.5) {
            // Move horizontally
            p.nextX = Math.random() < 0.5 ? canvas.width + 5 : -5;
            p.nextY = Math.random() * canvas.height;
        } else {
            // Move vertically
            p.nextX = Math.random() * canvas.width;
            p.nextY = Math.random() < 0.5 ? canvas.height + 5 : -5;
        }

        p.dx = (p.nextX - p.x) / (ANIMATION_SECONDS * 60 * Math.random());
        p.dy = (p.nextY - p.y) / (ANIMATION_SECONDS * 60 * Math.random());
    });

    particles.forEach(p => {
        p.update();
        p.render();
    });

    time += 0.016;
    requestAnimationFrame(updateParticles);
}

canvas.addEventListener('click', (event) => {
    const rect = canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;
    particles.push(new Particle(x, y));
});

initParticles(10);
updateParticles();
