function makeRequest(data, callback) {
    var type = ("secretPhrase" in data ? "POST" : "GET");
    var url = NRS.server + "/nxt?requestType=" + data.requestType;

    if (type === "GET") {
        if (typeof data === "string") {
            data += "&random=" + Math.random();
        } else {
            data.random = Math.random();
        }
        url += "&" + new URLSearchParams(data).toString();
    }

    return new Promise((resolve, reject) => {
        var xhr = new XMLHttpRequest();
        xhr.open(type, url, true);
        xhr.setRequestHeader("Content-Type", "application/json;charset=UTF-8");

        xhr.onload = function() {
            if (xhr.status >= 200 && xhr.status < 300) {
                resolve(JSON.parse(xhr.responseText));
            } else {
                if (type === "POST" && (NRS.accountInfo.errorCode && NRS.accountInfo.errorCode === 5)) {
                    if (callback) {
                        callback({ error: "Error code 5 encountered." });
                    }
                }
                reject(new Error(xhr.statusText));
            }
        };

        xhr.onerror = function() {
            reject(new Error("Network Error"));
        };

        if (type === "POST") {
            xhr.send(JSON.stringify(data));
        } else {
            xhr.send();
        }
    });
}
