function createTimeZoneRegex(pattern, timeZone) {
    const validTimeZoneFormats = [
        /^Pacific Time$/,
        /^America\/[A-Za-z_]+$/
    ];

    const isValidTimeZone = validTimeZoneFormats.some(regex => regex.test(timeZone));

    if (!isValidTimeZone) {
        return { error: `Invalid time zone format: ${timeZone}` };
    }

    const escapedPattern = pattern.replace(/[-\/\\^$.*+?()[\]{}|]/g, '\\$&');
    return new RegExp(escapedPattern);
}
