function createAndCheckElement(tagName, content, pattern) {
    // Create a new HTML element
    const element = document.createElement(tagName);

    // Update its innerHTML
    element.innerHTML = content;

    // Check if the innerHTML matches the specific pattern using a regular expression
    const regex = new RegExp(pattern);
    const matches = regex.test(element.innerHTML);

    return matches;
}
