const idCache = {};
let counter = 0;

function generateUniqueId(key) {
    if (idCache[key]) {
        return idCache[key];
    }

    const randomPostfix = Math.random().toString(36).substring(2, 8);
    const uniqueId = `${key}_${counter++}_${randomPostfix}`;
    idCache[key] = uniqueId;

    return uniqueId;
}
