    const combinators = "[>+~]";
    const simpleSelector = "(?:#([\\w-]+)|\\.([\\w-]+)|([\\w-]+)|\\*|\\[([^\\]]+)\\]|:([\\w-]+(?:\\([\\w\\s\\-\\:]*\\))?))";

    const rtrim = new RegExp("^" + whitespace + "+|((?:^|[^\\\\])(?:\\\\.)*)" + whitespace + "+$", "g");
