    const rgroups = new RegExp(simpleSelector + "(?=" + whitespace + "*[>,~+]|$)", "g");
    const rtokens = new RegExp(simpleSelector + "|" + combinators, "g");

    // Trim leading and trailing whitespace
    selector = selector.replace(rtrim, '');

    const components = [];
    let match;

    // Extract combinators and simple selectors
    while ((match = rtokens.exec(selector)) !== null) {
        components.push(match[0]);
    }

    const result = {
        combinators: [],
        simpleSelectors: [],
        attributeTests: []
    };

    components.forEach(component => {
        if (rcombinators.test(component)) {
            result.combinators.push(component);
