function createListManager(defaultList = []) {
    let items = [...defaultList];

    function dispatch(action) {
        if (action.type === 'ADD') {
            items.push(action.item);
        } else if (action.type === 'REMOVE') {
            items = items.filter(item => item !== action.item);
        } else if (action.type === 'CLEAR') {
            items = [];
        }
        return items;
    }

    return dispatch;
}

// Example usage:
