console.log(listManager({ type: 'ADD', item: 'orange' })); // ['apple', 'banana', 'orange']
console.log(listManager({ type: 'REMOVE', item: 'banana' })); // ['apple', 'orange']
console.log(listManager({ type: 'CLEAR' })); // []
