function loadAndExecuteJsFiles(baseDir, jsFiles, callback) {
    let loadedFiles = 0;
    const totalFiles = jsFiles.length;

    jsFiles.forEach(file => {
        const script = document.createElement('script');
        script.src = `${baseDir}/${file}`;
        script.async = true;

        script.onload = () => {
            loadedFiles++;
            if (loadedFiles === totalFiles && callback) {
                callback();
            }
        };

        script.onerror = () => {
            console.error(`Error loading script: ${file}`);
            loadedFiles++;
            if (loadedFiles === totalFiles && callback) {
                callback();
            }
        };

        document.head.appendChild(script);
    });
}

