function coroutine(iterator) {
    const token = Symbol('controlToken');
    let iterators = [iterator];

    function scheduleNext(value) {
        if (iterators.length === 0) return;

        const iter = iterators.shift();
        const ret = iter.next(value);

        if (!ret.done) {
            if (ret.value === token) {
                iterators.push(iter);
            } else {
                iterators.unshift(iter);
            }
            scheduleNext(ret.value);
        }
    }

    return function(value) {
        scheduleNext(value);
    };
}
