function normalizeURL(url) {
    let segments = url.split(/\/+/);
    let normalized = [];

    for (let segment of segments) {
        if (segment === '..') {
            normalized.pop();
        } else if (segment !== '' && segment !== '.') {
            normalized.push(segment);
        }
    }

    return (url.charAt(0) === '/' ? '/' : '') + normalized.join('/');
}
