const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const firebase = require('firebase');
const Gpio = require('onoff').Gpio;

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// Initialize Firebase
const firebaseConfig = {
    apiKey: "AIzaSyB3ZvJDuZ2HD-UppgPvY2by-GI0KnessXw",
    authDomain: "rlexa-9f1ca.firebaseapp.com",
    databaseURL: "https://rlexa-9f1ca.firebaseio.com",
    projectId: "rlexa-9f1ca",
    storageBucket: "rlexa-9f1ca.appspot.com",
    messagingSenderId: "161670508523"
};
firebase.initializeApp(firebaseConfig);
const db = firebase.database();

// Initialize LED
const led = new Gpio(17, 'out'); // Use GPIO pin 17 for the LED

// Serve static files
app.use(express.static('public'));

// Socket.io connection
io.on('connection', (socket) => {
    console.log('Client connected');

    socket.on('message', (msg) => {
        const jMsg = JSON.parse(msg);
        const newLedState = jMsg.led;

        // Update LED state
        led.writeSync(newLedState);

        // Store new state in Firebase
        db.ref('ledState').set({
            state: newLedState
        }).then(() => {
            console.log('LED state updated in Firebase:', newLedState);
        }).catch((error) => {
            console.error('Error updating Firebase:', error);
        });
    });

    socket.on('disconnect', () => {
        console.log('Client disconnected');
    });
});

// Start server
const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server is running on port ${PORT}`);
});
