function splitString(input, delimiter) {
    const result = [];
    const regex = new RegExp(`(.*?)(${delimiter})(.*)`);
    let match;

    while (input.length > 0) {
        match = regex.exec(input);
        if (match) {
            result.push(match[1]);
            input = match[3];
        } else {
            result.push(input);
            break;
        }
    }

    return result;
}
