function parseTokens(inputString, patterns) {
    const results = [];
    const tokens = inputString.split(/\s+/);

    for (let token of tokens) {
        for (let pattern of patterns) {
            const regex = new RegExp(pattern);
            if (regex.test(token)) {
                results.push(token);
                inputString = inputString.replace(token, '');
                break; // Break out of the inner loop to continue with the next token
            }
        }
    }

    return results;
}

