class RandomImageComponent extends React.Component {
    constructor(props) {
        super(props);
        this.state = {
            imgUrl: ''
        };
    }

    componentDidMount() {
        this.getImage();
    }

    getImage() {
        fetch('https://api.example.com/random-image') // Replace with the actual API URL
            .then((response) => {
                return response.json();
            })
            .then((responseJson) => {
                if (responseJson.imageUrl) {
                    this.setState({ imgUrl: responseJson.imageUrl });
                }
            })
            .catch((error) => console.error(error));
    }

    render() {
        return (
            <div>
                {this.state.imgUrl && <img src={this.state.imgUrl} alt="Random" />}
                <button onClick={() => this.getImage()}>Fetch New Image</button>
            </div>
