function parseMidiMetaEvents(stream) {
    const event = {};
    const eventTypeByte = stream.readInt8();

    if ((eventTypeByte & 0xf0) == 0xf0 && eventTypeByte == 0xff) {
        event.type = 'meta';
        const subtypeByte = stream.readInt8();
        const length = stream.readVarInt();

