import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.List;

public class MethodFilter {

    public static List<Method> filterMethods(List<Class<?>> classes, String methodName, Class<?> interfaceType, boolean isAbstract, Class<?> annotation) {
        List<Method> filteredMethods = new ArrayList<>();

        for (Class<?> clazz : classes) {
            Method[] methods = clazz.getDeclaredMethods();
            for (Method method : methods) {
                boolean matchesName = method.getName().equals(methodName);
                boolean matchesInterface = interfaceType == null || interfaceType.isAssignableFrom(clazz);
                boolean matchesAbstract = isAbstract == java.lang.reflect.Modifier.isAbstract(method.getModifiers());
                boolean matchesAnnotation = annotation == null || method.isAnnotationPresent(annotation);

                if (matchesName && matchesInterface && matchesAbstract && matchesAnnotation) {
                    filteredMethods.add(method);
                }
            }
        }

        return filteredMethods;
    }
}
