function getMimeType($filePath) {
    $log = '';
    $detectedMime = null;

    if (substr(PHP_OS, 0, 3) != 'WIN') {
        if (function_exists('exec')) {
            $log .= '- Checking MIME type with UNIX file() command<br />';
            $mime = @exec("file -bi " . escapeshellarg($filePath));
            if (strlen($mime) != 0) {
                $detectedMime = trim($mime);
                $log .= '&nbsp;&nbsp;&nbsp;&nbsp;MIME type detected as ' . $detectedMime . ' by UNIX file() command<br />';
