function uploadEncryptedFile($filePath, $password, $soapUrl) {
    try {
        // Read binary data from the file
        $fp = fopen($filePath, 'rb');
        $fileData = fread($fp, filesize($filePath));
        fclose($fp);

        // Encrypt the file data using the given password
        $encryptedData = openssl_encrypt($fileData, 'aes-256-cbc', $password, 0, substr(hash('sha256', $password), 0, 16));

        // Prepare the file data for the SOAP request
        $file = [
            'dataHandler' => base64_encode($encryptedData),
            'fileName' => basename($filePath),
            'type' => 1, // Adjust type as needed
            'fileSuffix' => pathinfo($filePath, PATHINFO_EXTENSION)
        ];
        $arr['files'] = [$file];

        // Create the SOAP header with security
        $xml = '<wsse:Security xmlns:wsse="http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-secext-1.0.xsd" >
                    <wsse:UsernameToken xmlns:wsu="http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-utility-1.0.xsd">
