/**
 * Hashes a password using a specified algorithm
 *
 * @param	string	$password	Password to be hashed
 * @param	string	$algorithm	Optional algorithm ('SSHA', 'SHA', 'SMD5')
 * @return	string	Hashed password with algorithm used
 * @access	public
 */
function hash_password($password, $algorithm = 'SSHA') {
    $salt = uniqid(mt_rand(), true);

    switch (strtoupper($algorithm)) {
        case 'SHA':
            $hashedPassword = sha1($salt . $password);
            break;
        case 'SMD5':
            $hashedPassword = md5($salt . $password);
            break;
        case 'SSHA':
        default:
