function updateUserPassword($username, $old_password, $new_password, $new_password_confirm) {
    global $connection, $crypt_iterations;

    // Fetch user info from the database
    $query = $connection->prepare('SELECT id, password, salt FROM members WHERE username = ?');
    $query->bind_param('s', $username);
    $query->execute();
    $result = $query->get_result();
    $db_info = $result->fetch_assoc();

    if ($db_info) {
        // Verify old password
        $hashed_old_password = hash_pbkdf2("sha256", $old_password, $db_info['salt'], $crypt_iterations, 20);
        if ($hashed_old_password == $db_info['password']) {
            // Check if new passwords match
            if ($new_password === $new_password_confirm) {
                // Generate new salt and hash new password
                $new_salt = mcrypt_create_iv(16, MCRYPT_DEV_URANDOM);
                $new_salt = md5($new_salt);
                $new_hashed_password = hash_pbkdf2("sha256", $new_password, $new_salt, $crypt_iterations, 20);

                // Update user password and salt in the database
                $update_query = $connection->prepare('UPDATE members SET password = ?, salt = ? WHERE id = ?');
                $update_query->bind_param('ssi', $new_hashed_password, $new_salt, $db_info['id']);

                if ($update_query->execute()) {
                    header("Location: index.php?act=logout");
                    exit();
                }
            }
        }
    }
}
