function submitForm($conn) {
    // Check if all fields are set
    $fields = ['name', 'username', 'password', 'email', 'cpf', 'address', 'number', 'complement', 'neighborhood', 'zip_code', 'city', 'state', 'phone', 'cell_phone'];
    foreach ($fields as $field) {
