function generateImageWithText($text, $width, $height, $fontSize, $fontPath, $x, $y, $padding, $colorHex) {
    // Create a blank image
    $image = imagecreatetruecolor($width, $height);

    // Allocate a color for the background (white)
    $backgroundColor = imagecolorallocate($image, 255, 255, 255);
    imagefill($image, 0, 0, $backgroundColor);

    // Allocate a color for the text
    $color = sscanf($colorHex, "#%2x%2x%2x");
    $textColor = imagecolorallocate($image, $color[0], $color[1], $color[2]);

    // Set the path to the font
    if (!file_exists($fontPath)) {
        return null; // Font file not found
    }

    // Add padding to the position
    $x += $padding;
    $y += $padding;

    // Add the text to the image
    imagettftext($image, $fontSize, 0, $x, $y, $textColor, $fontPath, $text);

    // Return the generated image
    return $image;
}
