}

// crop image (and also crops if image_ratio_crop is used)
if ((!empty($this->image_crop) || !is_null($ratio_crop))) {
if (is_array($this->image_crop)) {
$vars = $this->image_crop;
} else {
$vars = explode(' ', $this->image_crop);
}
