function isFileWritable($file) {
    // Check if the file exists
    if (!file_exists($file)) {
        return false;
    }

    // Use PHP's is_writable function for a quick check
    if (is_writable($file)) {
        return true;
    }

    // For directories and safe_mode "on" installations, try writing a temporary file
    if (is_dir($file)) {
        $tempFile = rtrim($file, '/') . '/' . md5(mt_rand());
        if (($fp = @fopen($tempFile, 'ab')) === false) {
            return false;
        }

        fclose($fp);
        @chmod($tempFile, 0777);
        @unlink($tempFile);
        return true;
    }

    // If it's a file, check if we can write to it by attempting to open it in append mode
    if (($fp = @fopen($file, 'ab')) === false) {
        return false;
    }

    fclose($fp);
    return true;
}
