CREATE OR REPLACE FUNCTION modify_query_with_limit(
    p_sql_query IN VARCHAR2,
    p_offset IN INTEGER DEFAULT NULL,
    p_limit IN INTEGER DEFAULT NULL
) RETURN VARCHAR2 IS
    v_modified_query VARCHAR2(4000);
BEGIN
    -- Set the NLS_DATE_FORMAT
    EXECUTE IMMEDIATE 'ALTER SESSION SET NLS_DATE_FORMAT = ''YYYY-MM-DD HH24:MI:SS''';

    -- Start building the modified query
    v_modified_query := 'SELECT * FROM (SELECT query.*, ROWNUM rnum FROM (' || p_sql_query || ') query';

    -- Handle offset and limit
    IF p_limit IS NOT NULL THEN
        IF p_offset IS NULL THEN
            p_offset := 0;
        END IF;
        v_modified_query := v_modified_query || ' WHERE ROWNUM <= ' || (p_offset + p_limit);
    END IF;

    v_modified_query := v_modified_query || ') WHERE rnum > ' || p_offset;

    RETURN v_modified_query;
END;
