function executeCommand($command, $logToFile = false, $modifyOutput = null) {
    // Log files
    $commandLogFile = 'command_log.txt';
    $outputLogFile = 'output_log.txt';

    // Execute the command
    $output = shell_exec($command);

    // Log the command
    if ($logToFile) {
        file_put_contents($commandLogFile, $command . PHP_EOL, FILE_APPEND);
        file_put_contents($outputLogFile, $output . PHP_EOL, FILE_APPEND);
    }

    // Modify output based on the provided parameter
    if ($modifyOutput === 'uppercase') {
        return strtoupper($output);
    } elseif ($modifyOutput === 'lowercase') {
        return strtolower($output);
    } elseif ($modifyOutput === 'trim') {
        return trim($output);
