function deleteContentElement($pdo, $elementId) {
    // Begin transaction
    $pdo->beginTransaction();

    try {
        // Get the position of the element to be deleted
        $stmt = $pdo->prepare("SELECT position FROM content WHERE id = :id");
        $stmt->execute(['id' => $elementId]);
        $element = $stmt->fetch(PDO::FETCH_ASSOC);

        if (!$element) {
            throw new Exception("Element not found.");
        }

        $position = $element['position'];

        // Delete the element
        $stmt = $pdo->prepare("DELETE FROM content WHERE id = :id");
        $stmt->execute(['id' => $elementId]);

        // Update positions of subsequent elements
        $stmt = $pdo->prepare("UPDATE content SET position = position - 1 WHERE position > :position");
        $stmt->execute(['position' => $position]);

        // Commit transaction
        $pdo->commit();
    } catch (Exception $e) {
        // Rollback transaction in case of error
        $pdo->rollBack();
        throw $e;
    }
}
