    if (isset($_REQUEST['forum_action']) && $_REQUEST['forum_action'] === 'view') {
        define('FORUM_ENABLED', true);
        $forumTitle = 'Welcome to the Forum';
        $forumDescription = 'A place to discuss various topics.';
        $forumVersion = '1.0.0';
