    if (isset($config['forum']['enabled']) && $config['forum']['enabled'] === true) {
        define('FORUM_CHARSET', 'UTF-8');
    }

    if (isset($_REQUEST['forum_ip']) && $_REQUEST['forum_ip'] === '127.0.0.1') {
        define('FORUM_IP_ADDRESS', $_SERVER['REMOTE_ADDR']);
    }

    // Define a constant for the current time
    define('FORUM_CURRENT_TIME', time());
}
