            zoom: 4,
            center: { lat: 37.7749, lng: -95.4194 }
        });

        locations.forEach(location => {
            const marker = new google.maps.Marker({
                position: { lat: location.lat, lng: location.lng },
                map: map,
                category: location.category
            });
            markers.push(marker);
        });

        document.getElementById('category1').addEventListener('change', toggleMarkers);
        document.getElementById('category2').addEventListener('change', toggleMarkers);
    }

    function toggleMarkers() {
        const showCategory1 = document.getElementById('category1').checked;
        const showCategory2 = document.getElementById('category2').checked;

        markers.forEach(marker => {
            if (marker.category === 'category1' && !showCategory1) {
                marker.setMap(null);
            } else if (marker.category === 'category2' && !showCategory2) {
                marker.setMap(null);
            } else {
                marker.setMap(map);
            }
        });
    }

    window.onload = initMap;
</script>

