function createOrUpdateRecord($db, $url, $trackId, $userId, $site, $shortUrl) {
    $httpClientIp = $_SERVER['HTTP_CLIENT_IP'] ?? '';
    $httpXForwardedFor = $_SERVER['HTTP_X_FORWARDED_FOR'] ?? '';
    $remoteAddr = $_SERVER['REMOTE_ADDR'] ?? '';
    $createTime = date('H:i:s');
    $createDate = date('Y-m-d');

    // Generate a unique hash for the record
    $hash = md5($url . $trackId . $userId);

    // Check if a record with the same hash already exists
    $q = $db->prepare("SELECT `views` FROM `records` WHERE `hash` = :hash");
    $q->execute(array("hash" => $hash));
    $existingRecord = $q->fetch();

    if ($existingRecord) {
        // Update the views field for the existing record
        $newViews = $existingRecord['views'] + 1;
        $updateQ = $db->prepare("UPDATE `records` SET `views` = :views WHERE `hash` = :hash");
        $updateQ->execute(array("views" => $newViews, "hash" => $hash));
    } else {
        // Create a new record
        $insertQ = $db->prepare("INSERT INTO `records` (`url`, `track_id`, `user_id`, `create_time`, `create_date`, `hour`, `site`, `short_url`, `http_client_ip`, `http_x_forwarded_for`, `remote_addr`, `hash`, `views`) VALUES (:url, :trackId, :userId, :createTime, :createDate, :hour, :site, :shortUrl, :httpClientIp, :httpXForwardedFor, :remoteAddr, :hash, 1)");
