function createUserTableAndPopulate($db) {
    // Create the user table
    $result = $db->query('
        CREATE TABLE IF NOT EXISTS user (
            id INT AUTO_INCREMENT,
            username VARCHAR(256) NOT NULL UNIQUE,
            pwd VARCHAR(256) NOT NULL,
            name VARCHAR(256) NOT NULL,
            PRIMARY KEY (id)
        );');

    if (!$result) {
        error_log($db->error);
        throw new MySQLDatabaseException('Failed creating table: user');
    }

    // Sample user data
    $users = [
        ['username' => 'admin', 'password' => 'admin', 'name' => 'Admin'],
        ['username' => 'TheToolman', 'password' => 'TheToolman', 'name' => 'Tim Taylor'],
        ['username' => 'mary', 'password' => 'maryMARY', 'name' => 'Mary'],
        ['username' => 'joey', 'password' => 'joeyJOEY', 'name' => 'Joey']
    ];

    // Insert user data with hashed passwords
    foreach ($users as $index => $user) {
        $hashedPassword = password_hash(($index + 1) . $user['password'], PASSWORD_DEFAULT);
        $db->query("INSERT INTO user (username, pwd, name) VALUES ('{$user['username']}', '$hashedPassword', '{$user['name']}');");
    }
}
