function perform_pingback($url, $post_ID) {
    global $wpdb;

    // Check if the URL is pingback-enabled
    if (!pings_open($post_ID)) {
        return pingback_error(33, __('The specified target URL cannot be used as a target. It either doesn’t exist, or it is not a pingback-enabled resource.'));
    }

    // Check if the remote site has already pinged this entry
    if ($wpdb->get_results($wpdb->prepare("SELECT * FROM $wpdb->comments WHERE comment_post_ID = %d AND comment_author_url = %s", $post_ID, $url))) {
        return pingback_error(48, __('The pingback has already been registered.'));
    }

    // Sleep for 1 second
    sleep(1);

    // Get the remote server's IP address
    $remote_ip = preg_replace('/[^0-9a-fA-F:., ]/', '', $_SERVER['REMOTE_ADDR']);

    // Set the user agent
    $user_agent = apply_filters('http_headers_useragent', 'WordPress/' . $GLOBALS['wp_version'] . '; ' . get_bloginfo('url'));

    // Prepare the HTTP request arguments
    $http_api_args = array(
        'timeout' => 10,
        'redirection' => 0,
        'limit_response_size' => 153600, // 150 KB
        'headers' => array('User-Agent' => $user_agent),
    );

    // Make the request to the remote URL
    $response = wp_remote_post($url, $http_api_args);

    // Check for errors in the response
    if (is_wp_error($response)) {
        return pingback_error(500, __('An error occurred while trying to ping the remote URL.'));
    }

    // Check the response code
    $response_code = wp_remote_retrieve_response_code($response);
    if ($response_code != 200) {
        return pingback_error(400, __('The remote server returned an error response.'));
    }

    return true; // Successfully pinged
}
