function updateUserPassword($userId, $newPassword, $resetToken) {
    // Fetch user from the database
    $user = User::find($userId);

    if (!$user) {
        Messaging::message('User not found');
        return;
    }

    // Validate new password
    if (empty($newPassword)) {
        Messaging::message('New password cannot be empty');
        return;
    }

    // Hash the new password
    $hashedPassword = password_hash($newPassword, PASSWORD_BCRYPT);

    // Update user password and deactivate reset token
    $user->encpwd = $hashedPassword;
    $user->forcepwdreset = 0;
    $user->reset_token = null; // Deactivate the reset token
    $user->update();

    // Send status email to the user
    $emailStatus = Mailer::sendPasswordChangeNotification($user->email);
    if ($emailStatus) {
        Messaging::message('Password has been changed and notification sent', 'success');
    } else {
        Messaging::message('Password changed, but failed to send notification');
    }
}
