public function insertData($db, $tableName, $columns, $values)
{
    // Check if the password column is present and hash it
    foreach ($columns as $key => $column) {
        if ($column === "password") {
            $values[$key] = password_hash($values[$key], PASSWORD_DEFAULT);
        }
    }

    // Prepare the SQL insert statement
    $query = "INSERT INTO " . $tableName . " (" . implode(", ", $columns) . ") VALUES (";
    $insertCols = array_map(function($col) { return ":" . $col; }, $columns);
    $query .= implode(", ", $insertCols) . ")";

    $statement = $db->prepare($query);

    // Bind the values to the statement
    foreach ($columns as $key => $column) {
        $statement->bindValue(":" . $column, $values[$key]);
    }

    // Execute the statement
    $result = $statement->execute();

    // Return the result and the last inserted id
    return [
        'result' => $result,
        'lastInsertId' => $db->lastInsertId()
    ];
}
