    def to_json_string(self):
        return json.dumps(self.__dict__)

    @classmethod
    def from_json_string(cls, json_string):
        data = json.loads(json_string)
        return cls(**data)

    @classmethod
    def add_factory(cls, id, factory):
        cls.factories[id] = factory

    @classmethod
    def create(cls, id, data):
