import os

def read_version(file_path):
    if not os.path.exists(file_path):
        return None
    with open(file_path, 'r') as file:
        return file.read().strip()

def write_version(file_path, version):
    with open(file_path, 'w') as file:
        file.write(version)

def increment_version(version):
    major, minor, patch = map(int, version.split('.'))
    patch += 1
    return f"{major}.{minor}.{patch}"

def main():
    version_file = 'current_version.txt'
    stored_version = read_version(version_file)

    if stored_version is None:
        print("Version file not found. Creating a new version file with version 0.0.0.")
        new_version = "0.0.0"
        write_version(version_file, new_version)
    else:
        print(f"Current version: {stored_version}")
        new_version = increment_version(stored_version)
        if new_version != stored_version:
            print(f"Updating version to: {new_version}")
            write_version(version_file, new_version)
        else:
            print("Version is up to date.")

if __name__ == "__main__":
    main()
```

