from collections import Counter
import re

def extract_text_from_pdf(pdf_file):
    return subprocess.check_output(["pdftotext", pdf_file, "-"]).decode('utf-8')

def tokenize(text):
    tokens = re.findall(r'\b\w+\b', text.lower())
    return tokens

def create_bag_of_words(tokens):
    return Counter(tokens)

def write_bag_of_words_to_file(bow, output_file):
    with open(output_file, 'w') as f:
        for word, count in bow.items():
            f.write(f"{word} {count}\n")

def main(pdf_file):
    (base, _) = os.path.splitext(pdf_file)
    text = extract_text_from_pdf(pdf_file)
    tokens = tokenize(text)
    bow = create_bag_of_words(tokens)
    output_file = base + "_bow.txt"
    write_bag_of_words_to_file(bow, output_file)

if __name__ == "__main__":
    import sys
    if len(sys.argv) != 2:
        print("Usage: python script.py <pdf_file>")
        sys.exit(1)
    main(sys.argv[1])
