import os
import hashlib
from urllib.parse import urlparse

def generate_thumbnail_path(url, width, height, ext='png'):
    """
    Generates a unique local path for a thumbnail image based on the original URL,
    width, height, and optional file extension.

    @param url: The original image URL
    @type url: str
    @param width: The desired width of the thumbnail
    @type width: int
    @param height: The desired height of the thumbnail
    @type height: int
    @param ext: The file extension for the thumbnail, defaults to 'png'
    @type ext: str
    @return: Local path of the generated thumbnail
    @rtype: str
    """
    # Decode the URL and create a hash of it
    url = urlparse(url).path
    hexhash = hashlib.md5(url.encode('utf-8')).hexdigest()

    # Construct the thumbnail filename
    filename = f"thumbnail_{hexhash}_{width}x{height}.{ext}"

    # Define the local path (you can change this to your desired directory)
    local_path = os.path.join('thumbnails', filename)

    return local_path
