import re

def compile_template(template):
    TOKENS = re.compile(r'\{(\w+)\}')

    def parse(tokens):
        syntax_rules = {
            'add': ' + ',
            'subtract': ' - ',
            'multiply': ' * ',
            'divide': ' / '
        }
        python_code = []
        for token in tokens:
            if token in syntax_rules:
                python_code.append(syntax_rules[token])
            else:
                python_code.append(token)
        return ''.join(python_code)

    tokens = TOKENS.findall(template)
    python = parse(tokens)
    return eval("lambda _n: %s" % python)

# Example usage:
