import subprocess

def adjust_volume(command):
    try:
        if command == 'up':
            subprocess.check_output(["amixer", "set", "'Master'", "5%+"], stderr=subprocess.STDOUT)
        elif command == 'down':
            subprocess.check_output(["amixer", "set", "'Master'", "5%-"], stderr=subprocess.STDOUT)
        else:
            return "Error: Command not recognized."

        # Retrieve the current volume level
        volume_info = subprocess.check_output(["amixer", "get", "'Master'"], stderr=subprocess.STDOUT).decode()
        volume_level = volume_info.split(",")[0].split()[-1]
        return volume_level
    except subprocess.CalledProcessError as e:
        return f"Error: {e.output.decode().strip()}"
