def execute_code_in_sandbox(code, local_vars=None):
    """Executes the given 'code' in a sandboxed environment with updated local variables."""
    if local_vars is None:
        local_vars = {}

    # Predefined global variables
    global_vars = {
        'global_var1': 42,
        'global_var2': 'Hello, World!'
    }

    # Create a local variable dictionary
    f_locals = {}
    f_locals.update(local_vars)

    # Execute the code
    exec(code, global_vars, f_locals)

    # Check if the last executed statement is truthy
    last_result = f_locals.get('_', None)
    if last_result:
        return last_result
    return None
