import os

def analyze_commit_history():
    tip = os.popen('hg log -r tip --template "{rev}"').read().strip()

    hgchildren = {}
    hgparents = {}
    hgbranch = {}

    hgchildren["0"] = ()
    hgparents["0"] = (None, None)
    hgbranch["0"] = "default"

    for cset in range(1, int(tip) + 1):
        hgchildren[str(cset)] = ()
        prnts = os.popen('hg log -r %d --template "{parents}"' % cset).read().strip().split(' ')
        prnts = list(map(lambda x: x[:x.find(':')], prnts))

        if prnts[0] != '':
            parent = prnts[0].strip()
        else:
            parent = str(cset - 1)

        hgchildren[parent] += (str(cset),)
        hgparents[str(cset)] = tuple(prnts)

        if len(prnts) > 1:
            mparent = prnts[1].strip()
            hgchildren[mparent] += (str(cset),)

    # Calculate the number of branches at each commit
    branch_count = {}
    for commit in range(1, int(tip) + 1):
        branch_count[str(commit)] = len(hgchildren[str(commit)])

    return branch_count

if __name__ == "__main__":
    branches_at_commits = analyze_commit_history()
    for commit, count in branches_at_commits.items():
        print(f'Commit {commit} has {count} branches.')
