import json
import os

class FileBucketReader:
    def __init__(self, source, fail_on_missing_input=False):
        self.source = source
        self.fail_on_missing_input = fail_on_missing_input
        self._iterator = None
        self._load_source()

    def _load_source(self):
        if os.path.isfile(self.source):
            self._iterator = open(self.source, 'r')
        elif isinstance(self.source, list):  # Assuming a list represents a bucket
            self._iterator = iter(self.source)
        else:
            if self.fail_on_missing_input:
                raise ValueError("Input source is missing or invalid.")
            self._iterator = iter([])  # Empty iterator if source is invalid

    def __iter__(self):
        return self

    def __next__(self):
        if self._iterator is None:
            raise StopIteration
        try:
            return next(self._iterator)
        except StopIteration:
            if self._iterator is not None and hasattr(self._iterator, 'close'):
                self._iterator.close()
            raise

    @classmethod
    def from_json(cls, state):
        source = state.get('source')
        fail_on_missing_input = state.get('fail_on_missing_input', False)
        return cls(source, fail_on_missing_input)

    def to_json(self):
        return json.dumps({
            'source': self.source,
            'fail_on_missing_input': self.fail_on_missing_input
        })
