CREATE OR REPLACE FUNCTION rename_and_add_column(
    table_name TEXT,
    old_column_name TEXT,
    new_column_name TEXT,
    new_column_definition TEXT
) RETURNS VOID AS $$
BEGIN
    -- Rename the old column
    EXECUTE format('ALTER TABLE %I RENAME COLUMN %I TO %I;', table_name, old_column_name, new_column_name);

    -- Add the new column with the specified definition
    EXECUTE format('ALTER TABLE %I ADD COLUMN %I %s;', table_name, new_column_name, new_column_definition);
END;
$$ LANGUAGE plpgsql;
