        if not user_name:
            self.errors.append("Empty Username")
        elif not user_password_new or not user_password_repeat:
            self.errors.append("Empty Password")
        elif user_password_new != user_password_repeat:
            self.errors.append("Password and password repeat are not the same")
        elif len(user_password_new) < 6:
            self.errors.append("Password has a minimum length of 6 characters")
        elif len(user_name) > 64 or len(user_name) < 2:
            self.errors.append("Username cannot be shorter than 2 or longer than 64 characters")
        elif not re.match(r'^[a-zA-Z\d]{2,64}$', user_name):
            self.errors.append("Username does not fit the name scheme: only a-Z and numbers are allowed, 2 to 64 characters")
