            self.errors.append("Email cannot be empty")
        elif len(user_email) > 64:
            self.errors.append("Email cannot be longer than 64 characters")
        elif not re.match(r'^[\w\.-]+@[\w\.-]+\.\w+$', user_email):
            self.errors.append("Your email address is not in a valid email format")
        elif user_name in self.users_db:
