DECLARE
    table_name text;
    trigger_name text;
BEGIN
    -- Drop existing triggers with a specific naming convention
    FOR table_name, trigger_name IN
        SELECT pg_class.relname, pg_trigger.tgname
        FROM pg_trigger
        LEFT JOIN pg_class ON (pg_trigger.tgrelid = pg_class.oid)
        WHERE pg_trigger.tgname LIKE 'my_trigger_%'
    LOOP
        EXECUTE format('DROP TRIGGER %I ON %I;', trigger_name, table_name);
    END LOOP;

    -- Check and install the PL/pgSQL language if necessary
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_language WHERE lanname = 'plpgsql') THEN
        EXECUTE 'CREATE LANGUAGE plpgsql';
    END IF;

    -- Create new triggers for each row in a SELECT statement
    FOR table_name IN
        SELECT table_name FROM information_schema.tables WHERE table_schema = 'public'
    LOOP
        EXECUTE format('CREATE TRIGGER my_trigger_%I AFTER INSERT ON %I FOR EACH ROW EXECUTE PROCEDURE my_function();', table_name, table_name);
    END LOOP;
END;
$$ LANGUAGE plpgsql;
