import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.PBEKeySpec;
import java.security.MessageDigest;
import java.security.spec.KeySpec;
import java.util.Base64;

public class CryptoOperations {
    public static void main(String[] args) throws Exception {
        if (args.length < 3) {
            System.out.println("Usage: java CryptoOperations <input> <algorithm> <password>");
            return;
        }

        String inputData = args[0];
        String algorithm = args[1];
        String password = args[2];

        // Generate hash
        MessageDigest digest = MessageDigest.getInstance(algorithm);
        byte[] hash = digest.digest(inputData.getBytes());
        System.out.println("Hash: " + bytesToHex(hash));

        // Derive key from password
        SecretKeyFactory factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
        KeySpec spec = new PBEKeySpec(password.toCharArray(), "salt".getBytes(), 65536, 256);
        SecretKey tmp = factory.generateSecret(spec);
        SecretKey secretKey = new SecretKeySpec(tmp.getEncoded(), "AES");

        // Decrypt input data (assuming inputData is Base64 encoded)
        byte[] cipherText = Base64.getDecoder().decode(inputData);
        Cipher cipher = Cipher.getInstance("AES/ECB/PKCS5Padding");
        cipher.init(Cipher.DECRYPT_MODE, secretKey);
        byte[] plainText = cipher.doFinal(cipherText);

        System.out.println("Decrypted data: " + new String(plainText));
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
