import os
import re

def append_changelog(packages):
    changelog_entries = []
    for package in packages:
        if package.arch == 'src' and ".src.rpm" in package.path:
            pfd = os.popen('rpm -q -p "%s" --changelog' % package.path)
            pfd.readline()  # Skip the date line
            changelog = ""
            for line in pfd:
                if line.startswith("*"):
                    break
                else:
                    if line.startswith("- "):
                        line = line.replace("- ", "", 1)
                    changelog += line
            pfd.close()
            changelog = changelog.strip().replace("\n", "<br />")
            changelog_entries.append({
                "package": package.name,
                "changelog": changelog
            })
