import json

def deserialize_json(string, decode_keys=False):
    """Convert a JSON string into a Python object.

    The keyword argument 'decode_keys' defaults to False.
    If set to True, non-string dictionary keys will be decoded into Python objects.

    >>> str(deserialize_json('"my string"'))
    'my string'
    >>> deserialize_json('{"36": "value"}', decode_keys=True)
    {36: 'value'}
    """
    if decode_keys:
        def custom_decoder(dct):
            return {int(k) if k.isdigit() else k: v for k, v in dct.items()}
        return json.loads(string, object_hook=custom_decoder)
    return json.loads(string)
