import hashlib

def hash_strings(string_list, unit='bytes'):
    """
    Compute a cryptographic hash of a list of strings

    :param string_list: The strings to be hashed
    :param unit: The unit of measurement for the hash value ('bytes', 'hex', 'base64')
    :return: The cryptographic hash (digest) of the strings in the order provided
    """
    sha256_hash = hashlib.sha256()
    for item in string_list:
        sha256_hash.update(item.encode())

    digest = sha256_hash.digest()

    if unit == 'bytes':
        return digest
    elif unit == 'hex':
        return sha256_hash.hexdigest()
    elif unit == 'base64':
        import base64
        return base64.b64encode(digest).decode()
    else:
        raise ValueError("Unrecognized unit. Use 'bytes', 'hex', or 'base64'.")
