import os
import hashlib

def calculate_md5_hashes(directory_path):
    file_hashes = {}

    for filename in os.listdir(directory_path):
        file_path = os.path.join(directory_path, filename)
        if os.path.isfile(file_path):
            with open(file_path, "rb") as read_file:
                the_hash = hashlib.md5()
                while chunk := read_file.read(8192):
                    the_hash.update(chunk)
                file_hashes[filename] = the_hash.hexdigest()

    sorted_files = dict(sorted(file_hashes.items(), key=lambda item: item[1]))
    return {
        "number_of_files": len(sorted_files),
        "file_hash_map": sorted_files
    }
