            System.exit(1);
        }

        String directory = args[0];
        String file = args[1];
        String options = args[2];

        ProcessBuilder processBuilder = new ProcessBuilder();
        processBuilder.command("java", "-cp", "antlr-4.9.2-complete.jar", "org.antlr.Tool", options, file);
        processBuilder.directory(new File(directory));

        try {
            Process process = processBuilder.start();
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));

            StringBuilder output = new StringBuilder();
            String line;

            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            StringBuilder errorOutput = new StringBuilder();
            while ((line = errorReader.readLine()) != null) {
                errorOutput.append(line).append("\n");
            }

            int exitCode = process.waitFor();
            System.out.println(output.toString());

            if (exitCode != 0) {
                System.err.println("ANTLR tool encountered an error:\n" + errorOutput.toString());
                System.exit(exitCode);
            }

        } catch (IOException | InterruptedException e) {
            System.err.println("An error occurred while running the ANTLR tool: " + e.getMessage());
