import hashlib
import os

def hash_message(message, hash_function='sha256', salt=None):
    """Returns the hash value of the message using the specified hash function.

    If salt is not provided, a random salt will be generated.
    The hash value is returned in hexadecimal format.
    """
    if salt is None:
        salt = os.urandom(16)  # Generate a random salt

    if isinstance(message, str):
        message = message.encode('utf-8')

    if hash_function.lower() == 'md5':
        hash_obj = hashlib.md5(salt + message)
    elif hash_function.lower() == 'sha1':
        hash_obj = hashlib.sha1(salt + message)
    elif hash_function.lower() == 'sha256':
        hash_obj = hashlib.sha256(salt + message)
    else:
        raise ValueError("Unsupported hash function. Use 'md5', 'sha1', or 'sha256'.")

    return hash_obj.hexdigest()
