class ColumnFamilyManager {
public:
    ColumnFamilyManager(rocksdb::DB* db, const std::string& cf_name) {
        rocksdb::ColumnFamilyOptions cf_options;
        rocksdb::Status status = db->CreateColumnFamily(cf_options, cf_name, &cf_handle_);
        if (!status.ok()) {
            std::cerr << "Failed to create column family: " << status.ToString() << std::endl;
        }
    }

    ~ColumnFamilyManager() {
        if (cf_handle_) {
            delete cf_handle_;
        }
    }

    rocksdb::ColumnFamilyHandle* GetHandle() const {
        return cf_handle_;
    }

private:
    rocksdb::ColumnFamilyHandle* cf_handle_ = nullptr;
};

class Database {
public:
    Database(const std::string& db_path) {
        rocksdb::Options options;
        options.create_if_missing = true;
        rocksdb::Status status = rocksdb::DB::Open(options, db_path, &db_);
        if (!status.ok()) {
            std::cerr << "Failed to open database: " << status.ToString() << std::endl;
        }
    }

    ~Database() {
        if (db_) {
            delete db_;
        }
    }

    rocksdb::DB* GetDB() const {
        return db_;
    }

    ColumnFamilyManager* CreateColumnFamily(const std::string& cf_name) {
        auto cf_manager = new ColumnFamilyManager(db_, cf_name);
        return cf_manager;
    }

private:
    rocksdb::DB* db_ = nullptr;
};

int main() {
    std::string db_path;
    std::cout << "Enter the path to the database file: ";
