use std::io::{self, Read};
use std::path::Path;

fn output_file_with_args(file_path: &str, args: Vec<String>) -> io::Result<String> {
    let path = Path::new(file_path);
    if !path.is_file() {
        return Err(io::Error::new(io::ErrorKind::NotFound, "Supplied file does not exist"));
    }

    let mut contents = String::new();
    let mut file = fs::File::open(path)?;
