use std::io::Result as IoResult;
use std::mem;
use std::ops::FnOnce;

pub fn execute_with_local_io<F, T>(closure: F) -> IoResult<T>
where
    F: FnOnce() -> IoResult<T>,
{
    let mut task: Box<Task> = match Local::try_take() {
        Some(t) => t,
        None => return Err(std::io::Error::new(std::io::ErrorKind::Other, "No local task available")),
    };

    let result = closure().map(|value| {
        unsafe { mem::transmute_copy(&value) }
    });

    Local::put(task);
    result
}
