use std::sync::atomic::{AtomicPtr, Ordering};
use std::ptr;

struct Node {
    data: Bag,
    next: AtomicPtr<Node>,
}

pub struct ConcBag {
    head: AtomicPtr<Node>,
}

impl ConcBag {
    pub fn new() -> Self {
        ConcBag {
            head: AtomicPtr::new(ptr::null_mut()),
        }
    }

    pub fn insert(&self, t: Bag) {
        let n = Box::into_raw(Box::new(Node {
            data: t,
            next: AtomicPtr::new(ptr::null_mut()),
        }));

        loop {
            let head = self.head.load(Ordering::Relaxed);
            unsafe { (*n).next.store(head, Ordering::Relaxed) };
            if self.head.compare_and_swap(head, n, Ordering::Release) == head {
                break;
            }
        }
    }

    pub unsafe fn collect(&self) -> Vec<Bag> {
        let mut head = self.head.load(Ordering::Relaxed);
        self.head.store(ptr::null_mut(), Ordering::Relaxed);
        let mut elements = Vec::new();

        while head != ptr::null_mut() {
            let node = Box::from_raw(head);
            elements.push(node.data);
            head = node.next.load(Ordering::Relaxed);
        }

        elements
    }
}
