use std::fs::OpenOptions;
use std::io::{self, Write};
use std::path::Path;

fn tee_writer(file_paths: Vec<&str>) -> io::Result<()> {
    let mut writers = Vec::new();

    for path in file_paths {
        let file = OpenOptions::new()
            .create(true)
            .write(true)
