use sha1::{Sha1, Digest};
use base64;

fn hash_and_encode(input: &[u8]) -> String {
    // Create a Sha1 hasher
    let mut hasher = Sha1::new();

    // Write input data
    hasher.update(input);

    // Calculate the hash
    let result = hasher.finalize();

    // Convert the hash to a byte array
    let hash_bytes = result.as_slice();

    // Print the hashed message in hex format
    let hashed_message: String = hash_bytes.iter().map(|b| format!("{:02x}", b)).collect();
    println!("Hashed message: {}", hashed_message);

    // Encode the hash using base64
    let base64_encoded = base64::encode(hash_bytes);

    // Print the base64 encoded output
    println!("Base64 encoded output: {}", base64_encoded);

    base64_encoded
}
