use std::env;
use std::net::SocketAddr;
use std::sync::Arc;
use std::thread;
use std::io::{self, Read, Write};
use flate2::write::GzEncoder;
use flate2::Compression;
use tokio::net::{TcpListener, TcpStream};
use tokio::prelude::*;
use tokio::runtime::Runtime;

fn main() -> io::Result<()> {
    let addr = env::args().nth(1).unwrap_or("127.0.0.1:8080".to_string());
    let addr = addr.parse::<SocketAddr>()?;
    println!("Listening on: {}", addr);

    let listener = TcpListener::bind(&addr)?;
    let runtime = Runtime::new()?;

    runtime.block_on(async {
        loop {
            let (socket, _) = listener.accept().await?;
            let handle = Arc::new(tokio::runtime::Handle::current());
            let thread_pool = Arc::new(threadpool::ThreadPool::new(num_cpus::get()));

            tokio::spawn(async move {
                let mut buffer = Vec::new();
                if let Err(e) = socket.read_to_end(&mut buffer).await {
                    eprintln!("Failed to read from socket; err = {:?}", e);
                    return;
                }

                let thread_pool = Arc::clone(&thread_pool);
                let compressed_data = thread_pool.execute(move || {
                    let mut encoder = GzEncoder::new(Vec::new(), Compression::default());
                    encoder.write_all(&buffer).unwrap();
                    encoder.finish().unwrap()
                }).unwrap();

                if let Err(e) = socket.write_all(&compressed_data).await {
                    eprintln!("Failed to write to socket; err = {:?}", e);
                }
            });
        }
    })
}
