use getopts::Options;
use std::env;

struct Option {
    short_flag: char,
    long_flag: &'static str,
    description: &'static str,
}

fn print_usage(program_name: &str, options: &[Option]) {
    let mut opts = Options::new();

    for option in options {
        opts.optopt(option.short_flag.to_string().as_str(), 
                    option.long_flag, 
                    option.description, 
                    "");
    }

    let usage = opts.usage(&format!("Usage: {} [options]", program_name));
    println!("{}", usage);
}

fn main() {
    let program_name = env::args().next().unwrap_or_else(|| "program".to_string());

    let options = [
        Option { short_flag: 'h', long_flag: "help", description: "Print this help message" },
        Option { short_flag: 'v', long_flag: "version", description: "Print version information" },
        Option { short_flag: 'o', long_flag: "output", description: "Specify output file" },
    ];

    print_usage(&program_name, &options);
}
