#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include <dirent.h>
#include <errno.h>

void copy_files(const char *src, const char *dest, const char *lib_path, const char *compiler_path) {
    struct stat st;
    DIR *dir = opendir(src);
    if (!dir) {
        perror("opendir");
        return;
    }

    if (stat(dest, &st) != 0) {
        if (mkdir(dest, 0755) != 0) {
            perror("mkdir");
            closedir(dir);
            return;
        }
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        char src_path[PATH_MAX];
        char dest_path[PATH_MAX];
        snprintf(src_path, sizeof(src_path), "%s/%s", src, entry->d_name);
        snprintf(dest_path, sizeof(dest_path), "%s/%s", dest, entry->d_name);

        if (stat(src_path, &st) == 0) {
            if (S_ISDIR(st.st_mode)) {
                copy_files(src_path, dest_path, lib_path, compiler_path);
            } else {
                char lib_file_path[PATH_MAX];
                snprintf(lib_file_path, sizeof(lib_file_path), "%s/%s", lib_path, entry->d_name);
                if (access(lib_file_path, F_OK) == 0) {
                    // Copy from library path instead
                    if (link(lib_file_path, dest_path) != 0) {
                        perror("link");
                    }
                } else {
                    // Copy from source path
                    FILE *src_file = fopen(src_path, "rb");
                    if (!src_file) {
                        perror("fopen");
                        continue;
                    }
                    FILE *dest_file = fopen(dest_path, "wb");
                    if (!dest_file) {
                        perror("fopen");
                        fclose(src_file);
                        continue;
                    }
                    char buffer[BUFSIZ];
                    size_t n;
                    while ((n = fread(buffer, 1, sizeof(buffer), src_file)) > 0) {
                        fwrite(buffer, 1, n, dest_file);
                    }
                    fclose(src_file);
                    fclose(dest_file);
                }

                // Set executable bit if it exists in the library path
                if (access(lib_file_path, F_OK) == 0) {
                    chmod(dest_path, st.st_mode | S_IXUSR | S_IXGRP | S_IXOTH);
                }
            }
        }
    }
    closedir(dir);
}
