use hmac::{Hmac, Mac, NewMac};
use sha1::Sha1;
use subtle::ConstantTimeEq;

fn verify_signature(payload: &str, signature: &str, secret: &str) -> bool {
    let sans_prefix = &signature[5..];
    let sigbytes = hex::decode(sans_prefix).ok()?;

    let mut mac = Hmac::<Sha1>::new_from_slice(secret.as_bytes()).expect("HMAC can take key of any size");
    mac.update(payload.as_bytes());

    let result = mac.finalize().into_bytes();

    result.as_slice().ct_eq(&sigbytes).into()
}
