#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

char *get_full_path(const char *filename) {
    char *full_path;
    char *resolved_path;

    // Allocate memory for the full path
    full_path = malloc(PATH_MAX);
    if (full_path == NULL) {
        return NULL; // Memory allocation failed
    }

    // Get the current working directory
    if (getcwd(full_path, PATH_MAX) == NULL) {
        free(full_path);
        return NULL; // Failed to get current working directory
    }

    // Append the filename to the current working directory
    strcat(full_path, "/");
    strcat(full_path, filename);

    // Resolve the full path
    resolved_path = realpath(full_path, NULL);
    free(full_path);

    return resolved_path; // Caller is responsible for freeing the returned path
}
