use std::path::{Path, PathBuf};

fn realpath<P: AsRef<Path>>(path: P) -> std::io::Result<PathBuf> {
    let mut absolute_path = fs::canonicalize(path)?;
    let mut components = absolute_path.components().collect::<Vec<_>>();

    // Remove symlinks from the path
    for i in 0..components.len() {
        if let Some(component) = components.get(i) {
            if component.as_os_str().is_empty() {
                continue;
            }
            let current_path = PathBuf::from(components[..=i].iter().collect::<PathBuf>());
            if current_path.is_symlink() {
                let resolved = fs::read_link(&current_path)?;
                absolute_path = absolute_path.parent().unwrap().join(resolved);
                components = absolute_path.components().collect();
            }
        }
    }

    Ok(absolute_path)
}
