use std::env;
use std::fs;
use std::path::{Path, PathBuf};

fn find_executable<B>(exe_name: B) -> Option<PathBuf>
where
    B: AsRef<Path>,
{
    let exe_name = exe_name.as_ref();
    let current_dir = env::current_dir().ok()?;
    let cargo_dir = env::var("CARGO_MANIFEST_DIR").ok()?;

    let search_dirs = vec![current_dir, PathBuf::from(cargo_dir)];

    for dir in search_dirs {
        let exe_path = dir.join(exe_name);
        if fs::metadata(&exe_path).map(|m| m.is_file()).unwrap_or(false) {
            return Some(exe_path);
        }
    }
    None
}
