use hmac::{Hmac, Mac, NewMac};
use sha1::{Sha1, Digest};
use base64;
use std::io::{self, Read};

pub fn decrypt_blob(username: &str, encrypted_blob: &str, device_id: &str) -> Result<Vec<u8>, io::Error> {
    let encrypted_blob = base64::decode(encrypted_blob).map_err(|_| io::Error::new(io::ErrorKind::InvalidData, "Invalid base64 input"))?;

    let secret = {
        let mut hasher = Sha1::new();
        hasher.update(device_id.as_bytes());
        hasher.finalize().to_vec()
    };

    let key = {
        let mut data = vec![0u8; 24];
        let mut mac = Hmac::<Sha1>::new_from_slice(&secret).map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "Invalid HMAC key"))?;
        mac.update(username.as_bytes());
        let result = mac.finalize();
        let key_bytes = result.into_bytes();
        data[..key_bytes.len()].copy_from_slice(&key_bytes);

        let mut hasher = Sha1::new();
        hasher.update(&data[..20]);
        let hash = hasher.finalize();
        data[..20].copy_from_slice(&hash);
        data[20..].copy_from_slice(&[0; 4]); // Padding for the key
        data
    };

    let mut decrypted_data = vec![0u8; encrypted_blob.len()];
    let mut cipher = aes::ecb_decryptor(aes::KeySize::KeySize192, &key, crypto::blockmodes::NoPadding);
    cipher.decrypt(&mut crypto::buffer::RefReadBuffer::new(&encrypted_blob), &mut crypto::buffer::RefWriteBuffer::new(&mut decrypted_data), true)?;

    let l = encrypted_blob.len();
    for i in 0..l - 0x10 {
        decrypted_data[l - i - 1] ^= decrypted_data[l - i - 0x11];
    }

    Ok(decrypted_data)
}
