use hmac::{Hmac, Mac, NewMac};
use sha1::Sha1;
use std::collections::HashMap;

#[derive(Debug)]
struct Request {
    headers: HashMap<String, String>,
    body: String,
}

#[derive(Debug)]
struct Response {
    status_code: u16,
    body: String,
}

#[derive(Debug)]
struct Config {
    secret: String,
}

fn verify_request(request: Request, config: Config) -> Response {
    let header_value = request.headers.get("X-Signature");

    let payload = request.body.clone();
    let mut hmac = Hmac::<Sha1>::new_from_slice(config.secret.as_bytes()).expect("HMAC can take key of any size");
    hmac.update(payload.as_bytes());

    let computed_result = hmac.finalize();
    let signature = format!("sha1={}", hex::encode(computed_result.into_bytes()));

    match header_value {
        Some(header) if header == &signature => {
            Response {
                status_code: 200,
                body: payload,
            }
        }
        _ => Response {
            status_code: 404,
            body: "Invalid request body.".to_string(),
        },
    }
}
