use std::io::{self, Write};
use std::process::{Command, Stdio};
use tempfile::NamedTempFile;
use anyhow::{Context, Result};

fn main() -> Result<()> {
    // Take input from the user
    let mut input = String::new();
    println!("Enter the Rust code to format:");
    io::stdin().read_line(&mut input)?;

    // Create a temporary file to hold the input code
    let mut temp_file = NamedTempFile::new().context("creating temporary file")?;
    writeln!(temp_file, "{}", input).context("writing to temporary file")?;

    // Run rustfmt on the temporary file
    let output = Command::new("rustfmt")
        .arg(temp_file.path())
        .stdout(Stdio::piped())
        .spawn()
        .context("running rustfmt")?;

    // Capture the output
    let output = output.wait_with_output().context("waiting for rustfmt to finish")?;
    if !output.status.success() {
        return Err(anyhow::anyhow!("rustfmt failed with status: {}", output.status));
    }

    // Write the formatted output to a new temporary file
    let mut formatted_file = NamedTempFile::new().context("creating formatted output file")?;
    formatted_file.write_all(&output.stdout).context("writing formatted output")?;

    println!("Formatted code written to: {}", formatted_file.path().display());

    Ok(())
}
