use std::env;
use std::path::{PathBuf, Path};
use std::process::Command;
use lazy_static::lazy_static;

fn find_cargo_root() -> PathBuf {
    // Execute the command to get the Cargo project root
    let output = Command::new("cargo")
        .arg("metadata")
        .arg("--no-deps")
        .output()
        .expect("Failed to execute cargo command");

    // Convert the output to a string and parse the JSON
    let stdout = String::from_utf8_lossy(&output.stdout);
    let json: serde_json::Value = serde_json::from_str(&stdout).expect("Failed to parse JSON");

    // Extract the root directory from the JSON
    let root = json["workspace"]["root"].as_str().expect("Failed to get root directory");
    PathBuf::from(root)
}

lazy_static! {
    pub static ref CARGO_ROOT: PathBuf = find_cargo_root();
}
