use hmac::{Hmac, Mac, NewMac};
use percent_encoding::{utf8_percent_encode, NON_ALPHANUMERIC};
use sha1::Sha1;
use std::string::String;

type HmacSha1 = Hmac<Sha1>;

fn generate_signature(method: &str, uri: &str, query: &str, consumer_secret: &str) -> String {
    let mut to_sign = String::new();
    to_sign.push_str(method);
    to_sign.push('&');
    to_sign.push_str(&utf8_percent_encode(uri, NON_ALPHANUMERIC).to_string());
    to_sign.push('&');
    to_sign.push_str(&utf8_percent_encode(query, NON_ALPHANUMERIC).to_string());

    let mut mac = HmacSha1::new_varkey(consumer_secret.as_bytes()).expect("HMAC can take key of any size");
    mac.update(to_sign.as_bytes());

    let result = mac.finalize();
    let signature_bytes = result.into_bytes();

    base64::encode(signature_bytes)
}
