#include <string.h>

char *create_temp_file(int *fd) {
    char *template = "/tmp/tempfileXXXXXX"; // Template for temporary file
    char *tempname = malloc(strlen(template) + 1);
    if (tempname == NULL) {
        return NULL;
    }
    strcpy(tempname, template);

#ifdef HAVE_MKSTEMP
    *fd = mkstemp(tempname);
    if (*fd == -1) {
        free(tempname);
        return NULL;
    }
#else
    tempname = mktemp(tempname);
    if (tempname == NULL) {
        free(tempname);
        return NULL;
    }
    *fd = open(tempname, O_RDWR | O_CREAT | O_EXCL, 0600);
    if (*fd == -1) {
        free(tempname);
        return NULL;
    }
#endif

    return tempname;
}
