use std::env;
use std::fs::File;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::process::Command;
use tempfile::NamedTempFile;

pub fn generate_fdset_from_proto(proto_file_path: &str) -> PathBuf {
    // Create a temporary file
    let temp_file = NamedTempFile::new().expect("Failed to create temporary file");
    let temp_file_path = temp_file.path().to_path_buf();

    // Write the protobuf file to the temporary file
    let mut temp_file_writer = File::create(&temp_file_path).expect("Failed to create temp file");
    let proto_content = std::fs::read_to_string(proto_file_path).expect("Failed to read proto file");
    temp_file_writer.write_all(proto_content.as_bytes()).expect("Failed to write to temp file");

    // Define the output path for the fdset
    let fdset_path = env::temp_dir().join("output.fdset");

    // Run the protoc compiler
    let mut cmd = Command::new("protoc");
    cmd.arg("--include_imports")
        .arg("--include_source_info")
        .arg("-o")
        .arg(&fdset_path)
        .arg(temp_file_path);

    cmd.status().expect("Failed to execute protoc");

    // Return the path to the fdset file
    fdset_path
}
