use sha2::{Sha256, Digest};
use std::iter::Iterator;

struct HashedIterator {
    input: String,
    count: usize,
    current: usize,
}

impl HashedIterator {
    fn new(input: String, count: usize) -> Self {
        HashedIterator {
            input,
            count,
            current: 0,
        }
    }
}

impl Iterator for HashedIterator {
    type Item = String;

    fn next(&mut self) -> Option<Self::Item> {
        if self.current < self.count {
            let mut hasher = Sha256::new();
            hasher.update(format!("{}{}", self.input, self.current));
            let result = hasher.finalize();
            self.current += 1;
            Some(format!("{:x}", result))
        } else {
            None
        }
    }
}

fn hashed_sequence(input: &str, count: usize) -> HashedIterator {
    HashedIterator::new(input.to_string(), count)
}
