use std::io::{self, Write};
use md5::{Md5, Digest};

pub fn authenticate_user(username: &str, password: &str, hashed_password: Option<&str>, salt: Option<&[u8]>) -> Result<String, String> {
    // Check for plaintext password authentication
    if let Some(stored_password) = hashed_password {
        if stored_password == password {
            return Ok(format!("Authentication successful for user: {}", username));
        }
    }

    // Check for MD5 hashed password authentication
    if let (Some(stored_hashed_password), Some(salt)) = (hashed_password, salt) {
        let mut hasher = Md5::new();
        hasher.update(password.as_bytes());
        hasher.update(username.as_bytes());
        let output = hasher.finalize();

        let mut hasher = Md5::new();
        hasher.update(&output);
        hasher.update(salt);
        let final_output = format!("md5{:x}", hasher.finalize());

        if final_output == stored_hashed_password {
            return Ok(format!("Authentication successful for user: {}", username));
        }
    }

    Err("Authentication failed".to_string())
}

