use std::fs;
use std::path::{Path, PathBuf};

fn realpath_no_symlinks(path: &str) -> std::io::Result<PathBuf> {
    let mut absolute_path = PathBuf::new();
    let components = Path::new(path).components();

    for component in components {
        match component {
            std::path::Component::RootDir => {
                absolute_path.push(component);
            }
            std::path::Component::Normal(name) => {
                let current_path = absolute_path.join(name);
                if let Ok(target) = fs::read_link(&current_path) {
                    absolute_path = target;
                } else {
                    absolute_path.push(name);
                }
            }
            _ => {}
        }
    }

    Ok(absolute_path.canonicalize()?)
}
