use std::env;
use std::process::Command;
use conduit_middleware::Middleware;
use conduit::{Request, Response};
use std::error::Error;

fn setup_db_connection(db_url: &str) -> (db::Transaction, App, impl Fn(&Request, Result<Response, Box<dyn Error + Send>>) -> Result<Response, Box<dyn Error + Send>>) {
    let migrate = env::current_exe().unwrap().parent().unwrap().join("migrate");
    assert!(Command::new(&migrate).env("DATABASE_URL", db_url).status().unwrap().success());

    let transaction = db::Transaction::begin(db_url).unwrap();
    let app = App::new(); // Assuming App is defined elsewhere

    let middleware = move |req: &Request, res: Result<Response, Box<dyn Error + Send>>| -> Result<Response, Box<dyn Error + Send>> {
        if res.is_ok() {
            if let Some(tx) = req.extensions().get::<db::Transaction>() {
                tx.commit().unwrap();
            }
        }
        res
    };

    (transaction, app, middleware)
}
