use std::env;
use std::fs;
use std::path::Path;
use mach;

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: {} <binary_file>", args[0]);
        return;
    }

    let path = &args[1];
    let buffer = fs::read(path).expect("Failed to read the binary file");

    match mach::Mach::parse(&buffer) {
        Ok(macho) => match macho {
            mach::Mach::Fat(bin) => {
                println!("Parsed a Fat binary:");
                print_multi_arch(&bin);
            }
            mach::Mach::Binary(bin) => {
                println!("Parsed a Mach-O binary:");
                print(&bin);
            }
        },
        Err(err) => {
            eprintln!("Error parsing binary: {:?}", err);
        }
    }
}

fn print_multi_arch(bin: &mach::Fat) {
    for arch in &bin.architectures {
        println!("Architecture: {:?}", arch);
    }
}

fn print(bin: &mach::Binary) {
    println!("Architecture: {:?}", bin.header.arch);
}
