use std::io::{self, Read};
use std::path::Path;

fn hash_json_file<P: AsRef<Path>>(path: P, disable_checks: bool) -> Result<String, io::Error> {
    if !disable_checks && !path.as_ref().exists() {
        return Err(io::Error::new(io::ErrorKind::NotFound, "File does not exist"));
    }

    let mut file = File::open(path)?;
    let mut contents = String::new();
    file.read_to_string(&mut contents)?;

    let _: Value = serde_json::from_str(&contents)?;

    let mut hasher = Sha1::new();
    hasher.update(contents);
    let result = hasher.finalize();

    Ok(format!("{:x}", result))
}
