use std::path::{Path, PathBuf};

pub fn generate_gitignore(repository_path: &Path, templates: &[&str]) -> Result<PathBuf, io::Error> {
    let destination = repository_path.join(".gitignore");
    let mut file = OpenOptions::new().create(true).write(true).truncate(true).open(&destination)?;

