use rust_bencode::{BDict, Bencode, DecodeResult};
use rust_sha1::Sha1;
use std::collections::BTreeMap;

pub fn hash_chunks(bytes: Vec<u8>, chunk_size: usize) -> Result<DecodeResult<BDict>, DecodeError> {
    let mut position = 0;
    let mut map = BTreeMap::new();

    while position < bytes.len() {
        let end = std::cmp::min(position + chunk_size, bytes.len());
        let chunk = &bytes[position..end];

        let mut sha1 = Sha1::new();
        sha1.update(chunk);
        let hash = sha1.digest().bytes().to_vec();

        let chunk_dict = BDict(BTreeMap::new(), chunk.to_vec());
        map.insert(BString::from_str(&hex::encode(hash.clone())), Bencode::BDict(chunk_dict));

        position += chunk_size;
    }

    Ok(DecodeResult(BDict(map, bytes), position))
}
