public class HashConcatenator {
    private static final String PREFIX = "PREFIX_";
    private static final String SUFFIX = "_SUFFIX";

    public static String concatenateHash(String input) throws NoSuchAlgorithmException {
        System.out.println("Input String: " + input);
        String hash = sha1(input);
        System.out.println("SHA-1 Hash: " + hash);
