use std::env;
use std::fs::{self, File};
use std::io::{BufReader, BufRead};

struct History {
    file_name: Option<String>,
    max_file_size: usize,
    buffers: Vec<Buffer>,
}

impl History {
    fn new() -> Self {
        History {
            file_name: None,
            max_file_size: 0,
            buffers: Vec::new(),
        }
    }

    fn set_file_name(&mut self, name: Option<String>) {
        self.file_name = name;
    }

    fn set_max_file_size(&mut self, size: usize) {
        self.max_file_size = size;
    }

    fn push(&mut self, buffer: Buffer) -> Result<(), &'static str> {
        if self.buffers.len() < self.max_file_size {
            self.buffers.push(buffer);
            Ok(())
        } else {
            Err("Max file size reached")
        }
    }

    fn commit_history(&self) {
        if let Some(ref file_name) = self.file_name {
            let mut file = File::create(file_name).unwrap();
            for buffer in &self.buffers {
                writeln!(file, "{}", buffer.content).unwrap();
            }
        }
    }
}

struct Buffer {
    content: String,
}

impl From<&str> for Buffer {
