#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define ERROR_CODE -1

int create_temp_file_descriptors(int *read_fd, int *write_fd) {
    char template[] = "/tmp/tempfileXXXXXX";
    int fd = mkstemp(template);
    if (fd == ERROR_CODE) {
        perror("Failed to create temporary file");
        return ERROR_CODE;
    }

    // Set the file descriptor to non-inheritable
    if (fcntl(fd, F_SETFD, FD_CLOEXEC) == ERROR_CODE) {
        perror("Failed to set file descriptor flags");
        close(fd);
        return ERROR_CODE;
    }

    // Create read and write file descriptors
    *read_fd = open(template, O_RDONLY | O_BINARY);
    *write_fd = fd; // Use the same fd for writing

    if (*read_fd == ERROR_CODE || *write_fd == ERROR_CODE) {
        perror("Failed to open file descriptors");
        close(*read_fd);
        close(*write_fd);
        return ERROR_CODE;
    }

    return 0; // Success
}
