fn open_file_with_program(path: &str) -> Result<(), String> {
    // Check for the BROWSER environment variable
    if let Ok(browser) = env::var("BROWSER") {
        if Command::new(browser).arg(path).spawn().is_ok() {
            return Ok(());
        }
    }

    // List of alternative programs to try
    let programs = ["xdg-open", "gnome-open", "kde-open"];
    let mut tried_programs = Vec::new();

    for program in &programs {
        tried_programs.push(program.to_string());
        if Command::new(program).arg(path).spawn().is_ok() {
