use std::collections::HashMap;
use std::env;

#[derive(Debug)]
struct Config {
    server_port: Option<u16>,
    user_data_path: Option<String>,
    rally_point_port: Option<u16>,
}

struct ArgParser {
    cached_args: Option<Config>,
}

impl ArgParser {
    fn new() -> Self {
        ArgParser { cached_args: None }
    }

    fn parse_args(&mut self) -> &Config {
        if let Some(ref cached) = self.cached_args {
            return cached;
        }

        let args: Vec<String> = env::args().skip(1).collect();
        let mut config = Config {
            server_port: None,
            user_data_path: None,
            rally_point_port: None,
        };

        for arg in args {
            if let Some((key, value)) = arg.split_once('=') {
                match key {
                    "server_port" => config.server_port = value.parse().ok(),
                    "user_data_path" => config.user_data_path = Some(value.to_string()),
                    "rally_point_port" => config.rally_point_port = value.parse().ok(),
                    _ => continue,
                }
            }
        }

        self.cached_args = Some(config);
        self.cached_args.as_ref().unwrap()
    }
}
