use std::collections::HashMap;
use std::hash::Hash;
use hmac::{Hmac, Mac, NewMac};
use sha1::Sha1;
use base64;

pub fn sign<K, V, S>(d: &HashMap<K, V>, secret: S) -> String
where
    K: AsRef<str> + Eq + Hash,
    V: AsRef<str> + Eq + Hash,
    S: AsRef<str>,
{
    let payload = transform_payload(d);

    let mut hmac = Hmac::<Sha1>::new_from_slice(secret.as_ref().as_bytes()).expect("HMAC can take key of any size");
    hmac.update(payload.as_bytes());

    let result = hmac.finalize();
    let code_bytes = result.into_bytes();

    base64::encode(&code_bytes)
}

fn transform_payload<K, V>(d: &HashMap<K, V>) -> String
where
    K: AsRef<str> + Eq + Hash,
    V: AsRef<str> + Eq + Hash,
{
    let mut vec: Vec<String> = d.iter()
        .map(|(k, v)| format!("{}={}", k.as_ref(), v.as_ref()))
        .collect();
    vec.sort();
    vec.join("&")
}

