use serde_json::json;

#[derive(Default)]
struct Pact {
    consumer: Consumer,
    provider: Provider,
    interactions: Vec<Box<dyn Interaction>>,
}

struct Consumer {
    name: String,
}

struct Provider {
    name: String,
}

trait Interaction {
    fn description(&self) -> String;
}

struct SynchronousHttp {
    description: String,
    // other fields...
}

impl Interaction for SynchronousHttp {
    fn description(&self) -> String {
        self.description.clone()
    }
}

fn generate_pact_file(pact: Pact, dir: &Path) -> std::io::Result<String> {
    let pact_json = json!({
        "consumer": {
            "name": pact.consumer.name
        },
        "provider": {
            "name": pact.provider.name
        },
        "interactions": pact.interactions.iter().map(|interaction| {
            json!({
                "description": interaction.description(),
                "request": {
                    "method": "GET",
                    "path": "/"
                },
                "response": {
