use std::env;
use std::process::Command;
use std::path::PathBuf;

fn main() {
    let args: Vec<String> = env::args().collect();

    // Check if the --target flag is present
    let is_build_script = args.iter().any(|arg| arg == "--target");

    if is_build_script {
        // Construct the path to the Rust compiler
        let rustc_path = env::var("RUSTC").unwrap_or_else(|_| "rustc".to_string());

        // Run the rustc command to get the version
        let output = Command::new(rustc_path)
            .arg("--version")
            .output()
            .expect("Failed to execute rustc");

        // Print the version number
        let version = String::from_utf8_lossy(&output.stdout);
        println!("Rust version: {}", version.trim());
    } else {
        println!("This is not a build script.");
    }
}
