use reqwest::Client;
use reqwest::Error;
use reqwest::Certificate;
use std::fs::File;
use std::io::Read;
use std::path::Path;

pub fn create_custom_client<P: AsRef<Path>>(cert_path: P, user_agent: &str) -> Result<Client, Error> {
    let mut builder = Client::builder();

    // Set custom User-Agent header
    builder = builder.user_agent(user_agent);

    // Set Connection header to 'close'
    builder = builder.default_headers({
        let mut headers = reqwest::header::HeaderMap::new();
        headers.insert(reqwest::header::CONNECTION, "close".parse().unwrap());
        headers
    });

    // Load custom certificate from file
    let mut cert_file = File::open(cert_path)?;
    let mut cert_data = Vec::new();
    cert_file.read_to_end(&mut cert_data)?;
    let cert = Certificate::from_pem(&cert_data)?;

    // Add the certificate to the client
    builder = builder.add_root_certificate(cert);

    builder.build()
}
