use std::process;

pub fn create_command(command_line: &str, flavor: Option<&str>) -> process::Command {
    let mut command_parts = command_line.split_whitespace();
    let command = command_parts.next().unwrap_or("");

    let mut cmd = if command.ends_with(".bat") {
        let mut c = process::Command::new("cmd");
        c.arg("/c").arg(command_line);
        c
    } else {
        process::Command::new(command)
    };

    if let Some(flavor) = flavor {
        cmd.arg("--flavor").arg(flavor);
    }

    cmd.args(command_parts);
    cmd
}
