use std::process::Command;
use std::env;
use std::io;

fn open_file_with_command(path: &str) -> Result<String, Vec<String>> {
    let commands = vec!["$BROWSER", "xdg-open", "gnome-open", "kde-open"];
    let mut attempted_commands = Vec::new();

